package com.signpost.store;

import com.signpost.snapshot.CachedBank;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class AccountDataTest
{
	@Test
	void toCachedBankIsKnownOnlyWhenBankAndAsOfArePresent()
	{
		AccountData empty = AccountData.empty();
		assertFalse(empty.toCachedBank().isKnown());

		AccountData withBank = new AccountData(
			Map.of(995, 100), Instant.parse("2026-09-01T00:00:00Z"), Map.of(), Set.of(), List.of(), null, Set.of());
		CachedBank cachedBank = withBank.toCachedBank();

		assertEquals(Map.of(995, 100), cachedBank.getItems());
		assertEquals(Instant.parse("2026-09-01T00:00:00Z"), cachedBank.getAsOf());
	}

	/** Group storage mirrors the bank - known only when both the map and its asOf are present. */
	@Test
	void toCachedGroupStorageIsKnownOnlyWhenMapAndAsOfArePresent()
	{
		assertFalse(AccountData.empty().toCachedGroupStorage().isKnown());

		AccountData data = AccountDataMutations.groupStorage(AccountData.empty(), Map.of(4151, 1), Instant.parse("2026-09-08T10:00:00Z"));
		CachedBank cached = data.toCachedGroupStorage();

		assertTrue(cached.isKnown());
		assertEquals(Map.of(4151, 1), cached.getItems());
		assertEquals(Instant.parse("2026-09-08T10:00:00Z"), cached.getAsOf());
		assertEquals(2, data.getVersion());
	}

	@Test
	void copyIsNotAffectedByMutatingTheOriginal()
	{
		AccountData original = new AccountData(
			new HashMap<>(Map.of(995, 100)),
			Instant.parse("2026-09-01T00:00:00Z"),
			new HashMap<>(),
			new HashSet<>(),
			new ArrayList<>(),
			null,
			new HashSet<>(Set.of("milestone:barrows-gloves")));

		AccountData copy = original.copy();

		original.getBank().put(996, 5);
		original.setBank(new HashMap<>(Map.of(1, 1)));
		original.setBankAsOf(Instant.parse("2026-09-02T00:00:00Z"));
		original.getOwnedManually().add("milestone:fire-cape");
		original.getGroupStorage().put(4151, 1);

		assertEquals(Map.of(995, 100), copy.getBank());
		assertEquals(Instant.parse("2026-09-01T00:00:00Z"), copy.getBankAsOf());
		assertEquals(Set.of("milestone:barrows-gloves"), copy.getOwnedManually(), "copy must not see a later mutation of the original's ownedManually set");
		assertEquals(Map.of(), copy.getGroupStorage(), "copy must not see a later mutation of the original's group storage");
	}
}

package com.signpost.store;

import com.google.gson.Gson;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import static org.junit.jupiter.api.Assertions.assertEquals;

class AccountStoreTest
{
	@TempDir
	Path dir;

	private AccountStore store;

	@BeforeEach
	void setUp()
	{
		store = new AccountStore(dir, new Gson());
	}

	/** Gson leaves omitted collections null; load must hand back something copy() and every mutation can use. */
	@Test
	void fileOmittingCollectionFieldsLoadsWithEmptyCollections() throws Exception
	{
		Files.createDirectories(dir);
		Files.writeString(dir.resolve("42.json"), "{\"focusGoalId\":\"quest:1\"}");

		AccountData data = store.load(42L);

		assertEquals("quest:1", data.getFocusGoalId());
		assertEquals(Map.of(), data.getBank());
		assertEquals(Map.of(), data.getSnoozes());
		assertEquals(Set.of(), data.getIgnores());
		assertEquals(List.of(), data.getPins());
		assertEquals(Set.of(), data.getOwnedManually());
		assertEquals(data, data.copy());
	}

	@Test
	void savedDataRoundTripsThroughLoad()
	{
		AccountData data = new AccountData(
			Map.of(995, 1000, 1511, 28),
			Instant.parse("2026-09-01T12:00:00Z"),
			Map.of("giant_mole", new Snooze(Instant.parse("2026-09-08T00:00:00Z"), "abc123")),
			Set.of("callisto"),
			List.of("barrows gloves", "fire cape"),
			"quest-points",
			Set.of("milestone:barrows-gloves", "milestone:fire-cape"));

		store.save(1234L, data);

		assertEquals(data, store.load(1234L));
	}

	/** A version-1 file (no version field, no group storage) upgrades on load to version 2 with empty, unseen group storage. */
	@Test
	void versionOneFileUpgradesToVersionTwoWithEmptyGroupStorage() throws Exception
	{
		Files.createDirectories(dir);
		Files.writeString(dir.resolve("7.json"), "{\"bank\":{\"995\":10},\"bankAsOf\":\"2026-09-01T12:00:00Z\",\"focusGoalId\":\"quest:1\"}");

		AccountData data = store.load(7L);

		assertEquals(2, data.getVersion());
		assertEquals(Map.of(), data.getGroupStorage());
		assertEquals(null, data.getGroupStorageAsOf());
		assertEquals(false, data.toCachedGroupStorage().isKnown());
		assertEquals(Map.of(995, 10), data.getBank());
		assertEquals("quest:1", data.getFocusGoalId());
	}

	/** Group storage round-trips with its asOf; an account that never saw it writes no groupStorageAsOf. */
	@Test
	void groupStorageRoundTripsAndUnseenStorageWritesNoAsOf() throws Exception
	{
		AccountData seen = AccountDataMutations.groupStorage(AccountData.empty(), Map.of(4151, 2), Instant.parse("2026-09-08T10:00:00Z"));
		store.save(8L, seen);
		assertEquals(seen, store.load(8L));
		assertEquals(Map.of(4151, 2), store.load(8L).getGroupStorage());

		store.save(9L, AccountData.empty());
		String json = Files.readString(dir.resolve("9.json"));
		assertEquals(false, json.contains("groupStorageAsOf"), json);
		assertEquals(true, json.contains("\"version\":2"), json);
	}

	@Test
	void loadOfMissingFileReturnsEmpty()
	{
		assertEquals(AccountData.empty(), store.load(999L));
	}

	@Test
	void loadOfCorruptFileReturnsEmptyAndLogsWarning() throws Exception
	{
		Files.writeString(dir.resolve("555.json"), "{ not valid json ]");

		assertEquals(AccountData.empty(), store.load(555L));
	}
}

package com.signpost.store;

import java.time.Instant;
import java.util.Map;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * {@link AccountDataMutations} is the pure part of every plugin panel action - a
 * plain data transform that returns a new {@link AccountData} and never mutates its input. The
 * executor wiring that serialises calls to it lives in {@code NextTargetPlugin#mutateAccountData}.
 */
class AccountDataMutationsTest
{
	private final Instant until = Instant.parse("2026-09-14T00:00:00Z");

	@Test
	void snoozeAddsAnEntryWithoutMutatingTheInput()
	{
		AccountData original = AccountData.empty();

		AccountData result = AccountDataMutations.snooze(original, "g1", until, "fp1");

		assertTrue(original.getSnoozes().isEmpty(), "input must not be mutated");
		assertEquals(new Snooze(until, "fp1"), result.getSnoozes().get("g1"));
	}

	@Test
	void unsnoozeRemovesTheEntry()
	{
		AccountData original = AccountData.empty();
		original.getSnoozes().put("g1", new Snooze(until, "fp1"));

		AccountData result = AccountDataMutations.unsnooze(original, "g1");

		assertTrue(original.getSnoozes().containsKey("g1"), "input must not be mutated");
		assertFalse(result.getSnoozes().containsKey("g1"));
	}

	@Test
	void ignoreAddsAndUnignoreRemoves()
	{
		AccountData empty = AccountData.empty();

		AccountData ignored = AccountDataMutations.ignore(empty, "g1");
		assertTrue(ignored.getIgnores().contains("g1"));
		assertFalse(empty.getIgnores().contains("g1"), "input must not be mutated");

		AccountData restored = AccountDataMutations.unignore(ignored, "g1");
		assertFalse(restored.getIgnores().contains("g1"));
	}

	@Test
	void pinIsIdempotentAndUnpinRemoves()
	{
		AccountData empty = AccountData.empty();

		AccountData pinnedOnce = AccountDataMutations.pin(empty, "g1");
		AccountData pinnedTwice = AccountDataMutations.pin(pinnedOnce, "g1");

		assertEquals(1, pinnedTwice.getPins().size(), "pinning twice must not duplicate");
		assertEquals("g1", pinnedTwice.getPins().get(0));

		AccountData unpinned = AccountDataMutations.unpin(pinnedTwice, "g1");
		assertFalse(unpinned.getPins().contains("g1"));
	}

	@Test
	void focusSetsAndClearFocusNulls()
	{
		AccountData empty = AccountData.empty();

		AccountData focused = AccountDataMutations.focus(empty, "g1");
		assertEquals("g1", focused.getFocusGoalId());
		assertNull(empty.getFocusGoalId(), "input must not be mutated");

		AccountData cleared = AccountDataMutations.clearFocus(focused);
		assertNull(cleared.getFocusGoalId());
	}

	@Test
	void markOwnedAddsAnEntryWithoutMutatingTheInput()
	{
		AccountData original = AccountData.empty();

		AccountData result = AccountDataMutations.markOwned(original, "milestone:barrows-gloves");

		assertTrue(original.getOwnedManually().isEmpty(), "input must not be mutated");
		assertTrue(result.getOwnedManually().contains("milestone:barrows-gloves"));
	}

	@Test
	void unmarkOwnedRemovesTheEntryWithoutMutatingTheInput()
	{
		AccountData owned = AccountDataMutations.markOwned(AccountData.empty(), "milestone:barrows-gloves");

		AccountData result = AccountDataMutations.unmarkOwned(owned, "milestone:barrows-gloves");

		assertTrue(owned.getOwnedManually().contains("milestone:barrows-gloves"), "input must not be mutated");
		assertFalse(result.getOwnedManually().contains("milestone:barrows-gloves"));
	}

	@Test
	void bankReplacesItemsAndAsOfWithoutMutatingTheInput()
	{
		AccountData original = AccountData.empty();

		AccountData result = AccountDataMutations.bank(original, Map.of(995, 100), until);

		assertTrue(original.getBank().isEmpty(), "input must not be mutated");
		assertEquals(Map.of(995, 100), result.getBank());
		assertEquals(until, result.getBankAsOf());
	}
}

