	@Test
	void dependencyOrderingPreservesExplicitPinOrderAndDoesNotResurrectHiddenPrerequisites()
	{
		GoalStatus room = status("room", GoalCategory.MILESTONE, 5, List.of(new ItemGap("Coins", 0, 200000, List.of(), false)));
