			.bankItem(946, "Knife", 1).inventoryItem(952, "Spade", 1).equipmentItem(1381, "Staff of air", 1)
			.groupStorageItem(2347, "Hammer", 1).bankItem(563, "Law rune", 1).inventoryItem(563, "Law rune", 1)
