	@Test
	void readyQuestCoveringASkillTargetReplacesItAndUnblocksTheParent()
	{
		// 1 xp short of 40 Attack, Waterfall Quest ready and worth 13,750 Attack xp.
		KnowledgeBase kb = new KbBuilder()
			.quest(158, "Waterfall Quest").rewardXp(Skill.ATTACK, 13_750)
			.quest(0, "Animal Magnetism").skill(Skill.ATTACK, 40)
			.build();
		Snapshot snapshot = new SnapshotBuilder().xp(Skill.ATTACK, net.runelite.api.Experience.getXpForLevel(40) - 1).build();

		Advice advice = engine.run(snapshot, kb, AccountData.empty(), now);

		assertFalse(ids(advice.getRanked()).contains("skill:ATTACK:40"), "no grind target: " + ids(advice.getRanked()));
		RankedGoal waterfall = advice.getRanked().stream().filter(r -> r.getStatus().getGoal().getId().equals("quest:158")).findFirst().orElseThrow();
		assertEquals(List.of("Animal Magnetism"), waterfall.getUnblocks());
		assertEquals(5.5, waterfall.getScore(), 1e-9, "priority 5 + one dependent, ready so closeness 1");
		assertTrue(advice.getExplanations().get("quest:158").contains("Unblocks: Animal Magnetism"), advice.getExplanations().get("quest:158").toString());
	}

