package com.signpost.engine;

import com.signpost.engine.model.CombatLevelGap;
import com.signpost.engine.model.Gap;
import com.signpost.engine.model.GearGap;
import com.signpost.engine.model.Goal;
import com.signpost.engine.model.GoalCategory;
import com.signpost.engine.model.GoalStatus;
import com.signpost.engine.model.ItemGap;
import com.signpost.engine.model.PrerequisiteGap;
import com.signpost.engine.model.RankedGoal;
import com.signpost.engine.model.SkillLevelGap;
import com.signpost.kb.KnowledgeBase;
import com.signpost.kb.MilestoneCategory;
import com.signpost.kb.OwnedItem;
import com.signpost.snapshot.AccountType;
import com.signpost.snapshot.Snapshot;
import java.util.List;
import java.util.Set;
import net.runelite.api.Skill;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * {@link WhyBuilder} builds the deterministic "why" text, one clause per
 * applicable rule joined with "; ", capped at 140 characters.
 */
class WhyBuilderTest
{
	private final WhyBuilder whyBuilder = new WhyBuilder();
	private final KnowledgeBase kb = new KbBuilder().build();
	private final Snapshot snap = new SnapshotBuilder().build();

	@Test
	void readyClauseWhenNoGapsAndBankKnown()
	{
		GoalStatus status = status("g1", GoalCategory.QUEST, List.of(), true, false);

		assertEquals("Ready now", whyBuilder.why(rank(status), kb, snap));
	}

	@Test
	void awayClauseCountsLeafGapsSingularAndPlural()
	{
		GoalStatus one = status("g1", GoalCategory.QUEST, List.of(new CombatLevelGap(1, 2, false)), false, false);
		assertEquals("1 requirement away", whyBuilder.why(rank(one), kb, snap));

		GoalStatus two = status("g2", GoalCategory.QUEST,
			List.of(new CombatLevelGap(1, 2, false), new ItemGap("Rune", 0, 1, List.of(), false)), false, false);
		assertEquals("2 requirements away", whyBuilder.why(rank(two), kb, snap));
	}

	@Test
	void bankUnknownClauseAppendedAndNeverLabelledReady()
	{
		// A lone unknown-have ItemGap counts as 0 unmet, so the away-clause reads "0"
		// even though the goal is still barred from "Ready now" by bankUnknown.
		GoalStatus status = status("g1", GoalCategory.QUEST, List.of(new ItemGap("Rune", null, 1, List.of(), false)), false, true);

		assertEquals("0 requirements away; bank unknown", whyBuilder.why(rank(status), kb, snap));
	}

	/** A group ironman whose shared storage has not been seen is told so; readiness is unaffected. */
	@Test
	void groupStorageNotSeenClauseOnlyForGroupIronmanWithUnseenStorage()
	{
		GoalStatus status = status("g1", GoalCategory.QUEST, List.of(), true, false);
		Snapshot unseen = new SnapshotBuilder().accountType(AccountType.GROUP).build();
		Snapshot seen = new SnapshotBuilder().accountType(AccountType.GROUP).groupStorageKnown().build();

		assertEquals("Ready now; group storage not seen", whyBuilder.why(rank(status), kb, unseen));
		assertEquals("Ready now", whyBuilder.why(rank(status), kb, seen));
		assertEquals("Ready now", whyBuilder.why(rank(status), kb, snap), "a non-group account has no group storage to see");
		Snapshot off = new SnapshotBuilder().accountType(AccountType.GROUP).groupStorageOff().build();
		assertEquals("Ready now", whyBuilder.why(rank(status), kb, off), "toggle off: nothing to open, so no clause");
	}

	@Test
	void unlocksClauseListsUpToTwoEntries()
	{
		KnowledgeBase unlockKb = new KbBuilder()
			.milestone("milestone:test", MilestoneCategory.UNLOCK, "Test Unlock", 5)
			.unlocks("Ability A", "Ability B", "Ability C")
			.build();
		GoalStatus status = status("milestone:test", GoalCategory.MILESTONE, List.of(new CombatLevelGap(1, 2, false)), false, false);

		assertEquals("1 requirement away; unlocks Ability A, Ability B", whyBuilder.why(rank(status), unlockKb, snap));
	}

	@Test
	void gearUpgradeClauseWhenTierExceedsHighestOwnedInSubcategory()
	{
		KnowledgeBase gearKb = new KbBuilder()
			.milestone("melee:tier5", MilestoneCategory.GEAR, "Tier 5 Melee", 5)
			.ownedIf("Tier 5 Item", 100).gearTier(5).subcategory("melee")
			.milestone("melee:tier8", MilestoneCategory.GEAR, "Tier 8 Melee", 5)
			.ownedIf("Tier 8 Item", 200).gearTier(8).subcategory("melee")
			.build();
		Snapshot owning = new SnapshotBuilder().inventoryItem(100, "Tier 5 Item", 1).build();
		GoalStatus status = status("melee:tier8", GoalCategory.MILESTONE, List.of(), true, false);

		assertEquals("Ready now; biggest melee upgrade over what you own", whyBuilder.why(rank(status), gearKb, owning));
	}

	@Test
	void materialsAlreadyInBankClauseWhenEveryItemGapIsSatisfied()
	{
		GoalStatus status = status("g1", GoalCategory.QUEST, List.of(new ItemGap("Egg", 5, 5, List.of(), false)), false, false);

		assertEquals("1 requirement away; materials already in bank", whyBuilder.why(rank(status), kb, snap));
	}

	@Test
	void justLevelsClauseListsSkillsWithHaveAndNeed()
	{
		GoalStatus status = status("g1", GoalCategory.QUEST,
			List.of(new SkillLevelGap(Skill.HERBLORE, 61, 70, 500_000, false, null, false)), false, false);

		assertEquals("1 requirement away; just levels: Herblore 61/70", whyBuilder.why(rank(status), kb, snap));
	}

	@Test
	void laterGoalNeverSaysReadyNowEvenWithNoGaps()
	{
		GoalStatus status = status("boss:test", GoalCategory.BOSS, List.of(), true, false);
		RankedGoal later = new RankedGoal(status, 0.25, false, true);

		String why = whyBuilder.why(later, kb, snap);

		assertFalse(why.contains("Ready now"), why);
		assertTrue(why.startsWith("later: stage " + status.getGoal().getStage()), why);
	}


	@Test
	void nonRecommendedGapsDoNotTriggerTheRecommendedClause()
	{
		GoalStatus status = status("g1", GoalCategory.QUEST,
			List.of(new SkillLevelGap(Skill.RANGED, 70, 85, 1_000_000, false, null, false)), false, false);

		String why = whyBuilder.why(rank(status), kb, snap);

		assertFalse(why.contains("recommended:"), why);
	}

	@Test
	void truncationDropsTrailingClausesAtBoundary()
	{
		String c1 = "A".repeat(100);
		String c2 = "B".repeat(45); // "A"*100 + "; " + "B"*45 = 147 chars, over the 140 cap.

		String result = WhyBuilder.truncate(List.of(c1, c2));

		assertEquals(c1, result, "the second clause must be dropped whole, never cut mid-word: " + result);
		assertTrue(result.length() <= 140);
	}

	@Test
	void truncationCutsASingleOverlongClauseWithEllipsis()
	{
		String result = WhyBuilder.truncate(List.of("A".repeat(200)));

		assertEquals("A".repeat(139) + "…", result);
		assertEquals(140, result.length());
	}

	/** A partly owned outfit says how many pieces are held. */
	@Test
	void piecesClauseCountsHeldOutfitPiecesAgainstOwnedIfMin()
	{
		KnowledgeBase outfitKb = new KbBuilder()
			.milestone("milestone:prospector-outfit", MilestoneCategory.GEAR, "Prospector outfit", 6)
			.ownedIf("Prospector helmet", 12013)
			.ownedIf("Prospector jacket", 12014)
			.ownedIf("Prospector legs", 12015)
			.ownedIf("Prospector boots", 12016)
			.ownedIfMin(4)
			.build();
		Snapshot twoPieces = new SnapshotBuilder().bankItem(12013, "Prospector helmet", 1).bankItem(12016, "Prospector boots", 1).build();
		GoalStatus status = status("milestone:prospector-outfit", GoalCategory.MILESTONE, List.of(), true, false);

		assertEquals("Ready now; 2/4 pieces", whyBuilder.why(rank(status), outfitKb, twoPieces));
		assertEquals("Ready now", whyBuilder.why(rank(status), outfitKb, snap), "no pieces held: no clause");
	}

	/** A method-linked untradeable names the skill it speeds up, and the skill target for it when one is ranked. */
	@Test
	void speedsUpClauseNamesTheSkillAndItsNextTargetWhenOneExists()
	{
		KnowledgeBase bagKb = new KbBuilder()
			.milestone("milestone:coal-bag", MilestoneCategory.GEAR, "Coal bag", 7)
			.ownedIf("Coal bag", 12019)
			.speedsUp(Skill.MINING)
			.build();
		GoalStatus status = status("milestone:coal-bag", GoalCategory.MILESTONE, List.of(), true, false);

		assertEquals("Ready now; speeds up Mining (your next Mining target)", whyBuilder.why(rank(status), bagKb, snap, Set.of(Skill.MINING)));
		assertEquals("Ready now; speeds up Mining", whyBuilder.why(rank(status), bagKb, snap, Set.of(Skill.HERBLORE)));
	}

	/** A prerequisite gap counts as one requirement away and is named in the Missing line. */
	@Test
	void prerequisiteGapIsOneRequirementAwayAndNamedAsMissing()
	{
		GoalStatus status = status("poh:portal-nexus", GoalCategory.MILESTONE, List.of(new PrerequisiteGap("poh:portal-chamber", "Portal chamber")), false, false);

		assertEquals("1 requirement away", whyBuilder.why(rank(status), kb, snap));
		assertEquals(List.of("Missing: Portal chamber first"), whyBuilder.explain(rank(status), kb, snap, 2));
	}

	private static GoalStatus status(String id, GoalCategory category, List<Gap> gaps, boolean ready, boolean bankUnknown)
	{
		Goal goal = new Goal(id, category, id, "https://x", 5, 1);
		return new GoalStatus(goal, gaps, ready, bankUnknown, List.of());
	}

	private static RankedGoal rank(GoalStatus status)
	{
		return new RankedGoal(status, 1.0, false, false);
	}
}

package com.signpost.engine;

import com.google.gson.Gson;
import com.signpost.engine.model.Advice;
import com.signpost.engine.model.GoalObjective;
import com.signpost.engine.model.RewardTarget;
import com.signpost.kb.RewardValue;
import com.signpost.engine.model.Goal;
import com.signpost.engine.model.GoalCategory;
import com.signpost.engine.model.GoalStatus;
import com.signpost.kb.BossReward;
import com.signpost.kb.KnowledgeBase;
import com.signpost.kb.MilestoneCategory;
import com.signpost.snapshot.BossProgress;
import com.signpost.snapshot.CombatAchievementTask;
import com.signpost.snapshot.Snapshot;
import com.signpost.store.AccountData;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class BossProgressionTest
{
	private static final String MOONS = "boss:moons-of-peril";
	private static final Instant NOW = Instant.parse("2026-09-09T12:00:00Z");
	private final Engine engine = new Engine(new BoostTable());

	@Test
	void meaningfulGainsOutrankMarginalGrindsWithoutDroppingUsefulUnlocks()
	{
		var oldObjective = new GoalObjective(List.of(new RewardTarget("Alternative weapon", "A niche option", RewardValue.SITUATIONAL, false)), List.of(), false, false, false);
		var nextObjective = new GoalObjective(List.of(new RewardTarget("Major upgrade", "Fills a combat gap", RewardValue.MAJOR, false)), List.of(), false, false, false);
		var oldGoal = new Goal("old", GoalCategory.BOSS, "Older boss", "", 10, 2);
		var nextGoal = new Goal("next", GoalCategory.BOSS, "Current boss", "", 5, 4);
		var unlockGoal = new Goal("unlock", GoalCategory.MILESTONE, "Useful unlock", "", 9, 2);
		var old = new GoalStatus(oldGoal, List.of(), true, false, List.of(), List.of(), List.of(), null, 0, List.of(), oldObjective);
		var next = new GoalStatus(nextGoal, List.of(new com.signpost.engine.model.CombatLevelGap(100, 110, false)), false, false,
			List.of(), List.of(), List.of(), null, 0, List.of(), nextObjective);
		var unlock = new GoalStatus(unlockGoal, List.of(), true, false, List.of());
		var ranked = new Ranker().rank(List.of(old, next, unlock), Set.of(), List.of(), 4);
		assertEquals(List.of("unlock", "next", "old"), ranked.stream().map(r -> r.getStatus().getGoal().getId())
			.collect(Collectors.toList()));
	}

	@Test
	void greenLogWithNoRemainingTasksRetiresBossEvenWhenPinnedAndItemsAreNoLongerHeld()
	{
		KnowledgeBase kb = moons();
		Snapshot snapshot = observed(new BossProgress(true, true, List.of()));
		AccountData prefs = AccountData.empty();
		prefs.getPins().add(MOONS);
		Advice advice = engine.run(snapshot, kb, prefs, NOW);
		assertTrue(advice.getRanked().stream().noneMatch(r -> r.getStatus().getGoal().getId().equals(MOONS)));
		assertNull(advice.getFocus());
	}

	@Test
	void greenLogReturnsOnlyForNamedUnfinishedAchievementAndRetiresWhenItCompletes()
	{
		CombatAchievementTask task = new CombatAchievementTask(550, "No mistakes", "Defeat the boss without taking avoidable damage.", 3);
		Snapshot snapshot = observed(new BossProgress(true, true, List.of(task)));
		AccountData prefs = AccountData.empty();
		prefs.setFocusGoalId(MOONS);
		Advice before = engine.run(snapshot, moons(), prefs, NOW);
		GoalObjective objective = before.getFocus().getStatus().getObjective();
		assertEquals(List.of(task), objective.getTasks());
		assertTrue(before.getWhys().get(MOONS).contains(task.getName()));
		assertTrue(before.getExplanations().get(MOONS).contains(task.getDescription()));
		assertTrue(before.getExplanations().get(MOONS).stream().anyMatch(s -> s.contains("3 points")));
		assertFalse(before.getWhys().get(MOONS).contains("Blood moon"));
		assertFalse(before.getReasons().containsKey(MOONS), "static drop advertising must not override the personal reason");

		Advice after = engine.run(observed(new BossProgress(true, true, List.of())), moons(), prefs, NOW.plusSeconds(1), before);
		assertTrue(after.getPicked().isEmpty());
		assertNull(after.getFocus());
		assertEquals(List.of(MOONS), after.getCompletedSinceLast().stream().map(g -> g.getId()).collect(java.util.stream.Collectors.toList()));
	}

	@Test
	void unknownAchievementsDoNotInventAReasonToReturnToAGreenLog()
	{
		Advice advice = engine.run(observed(new BossProgress(true, false, List.of())), moons());
		assertTrue(advice.getPicked().isEmpty());
	}

	@Test
	void unavailableAchievementDataDoesNotReportThePreviousObjectiveAsCompleted()
	{
		CombatAchievementTask task = new CombatAchievementTask(550, "No mistakes", "Avoid all special attacks.", 3);
		Advice before = engine.run(observed(new BossProgress(true, true, List.of(task))), moons());
		Advice after = engine.run(observed(new BossProgress(true, false, List.of())), moons(), AccountData.empty(), NOW, before);
		assertTrue(after.getCompletedSinceLast().isEmpty());
	}

	@Test
	void sharedAndSuperiorGearRemoveOnlyTheirMatchingRewardReasons()
	{
		KnowledgeBase kb = new KbBuilder().milestone("boss:test", MilestoneCategory.BOSS, "Boss", 8)
			.bossReward(new BossReward("Blood moon chestplate", List.of(29022), List.of(11832), null, RewardValue.USEFUL, "Progress toward " + "Blood moon chestplate", List.of()))
			.bossReward("Osmumten's fang", 26219).bossReward("Lightbearer", 25975).build();
		Snapshot snapshot = new SnapshotBuilder().bankItem(11832, "Bandos chestplate", 1)
			.groupStorageItem(26219, "Osmumten's fang", 1).build();
		Advice advice = engine.run(snapshot, kb);
		assertEquals(List.of("Lightbearer"), advice.getPicked().get(0).getStatus().getObjective().getRewards()
			.stream().map(RewardTarget::getName).collect(Collectors.toList()));
		assertFalse(advice.getWhys().get("boss:test").contains("fang"));
	}

	@Test
	void consumedPrayerScrollIsNotMissingAndExhaustedRewardsRetireTheBoss()
	{
		KnowledgeBase kb = new KbBuilder().milestone("boss:cox", MilestoneCategory.BOSS, "Chambers", 8)
			.bossReward(new BossReward("Rigour", List.of(21034), List.of(), "rigour", RewardValue.USEFUL, "Progress toward " + "Rigour", List.of())).build();
		Snapshot snapshot = new SnapshotBuilder().build().toBuilder().rigour(true)
			.bossProgress(Map.of("boss:cox", new BossProgress(false, true, List.of()))).build();
		assertTrue(engine.run(snapshot, kb).getPicked().isEmpty());
		assertEquals(List.of("Rigour"), engine.run(snapshot.toBuilder().rigour(false).build(), kb)
			.getPicked().get(0).getStatus().getObjective().getRewards().stream().map(RewardTarget::getName).collect(Collectors.toList()));
	}

	@Test
	void unknownBankDoesNotClaimMissingRewardsAreCertain()
	{
		Advice advice = engine.run(new SnapshotBuilder().bankUnknown().build(), moons());
		GoalStatus status = advice.getRanked().get(0).getStatus();
		assertTrue(status.getObjective().isBankUnknown());
		assertTrue(advice.getPicked().isEmpty(), "unseen rewards are not confirmed needs");
	}

	@Test
	void greenLogAlsoRetiresGearGoalsThatWouldSendPlayerBackForItsDrops()
	{
		KnowledgeBase kb = new KbBuilder().milestone(MOONS, MilestoneCategory.BOSS, "Moons", 8)
			.bossReward("Blood moon chestplate", 29022)
			.milestone("gear:blood", MilestoneCategory.GEAR, "Blood moon chestplate", 8)
			.ownedIf("Blood moon chestplate", 29022).obtainedFrom(MOONS).build();
		Advice advice = engine.run(observed(new BossProgress(true, true, List.of())), kb);
		assertTrue(advice.getStatuses().isEmpty());
	}

	@Test
	void fullMoonsArmourAndWeaponsRemoveMoonsWithoutPretendingToKnowCollectionCompletion()
	{
		KnowledgeBase kb = KnowledgeBase.load(new Gson());
		Map<Integer,Integer> items = new java.util.HashMap<>();
		kb.milestoneById(MOONS).getBossRewards().forEach(reward -> items.put(reward.getIds().get(0), 1));
		Snapshot snapshot = new SnapshotBuilder().build().toBuilder().bank(items).build();
		assertTrue(engine.run(snapshot, kb).getRanked().stream().noneMatch(r -> r.getStatus().getGoal().getId().equals(MOONS)));
		assertTrue(snapshot.getBossProgress().isEmpty(), "current item ownership is not historical green-log evidence");
	}

	@Test
	void outclassedGearGoalsRetireWithoutACollectionLogButOtherStylesRemainRelevant()
	{
		KnowledgeBase kb = new KbBuilder().milestone(MOONS, MilestoneCategory.BOSS, "Moons", 8)
			.bossReward(new BossReward("Blood moon chestplate", List.of(29022), List.of(11832), null, RewardValue.USEFUL, "Progress toward " + "Blood moon chestplate", List.of()))
			.bossReward(new BossReward("Blood moon tassets", List.of(29025), List.of(11834), null, RewardValue.USEFUL, "Progress toward " + "Blood moon tassets", List.of()))
			.bossReward("Blue moon chestplate", 29013)
			.milestone("gear:blood", MilestoneCategory.GEAR, "Blood moon armour", 8)
			.ownedIf("Blood moon chestplate", 29022).ownedIf("Blood moon tassets", 29025)
			.ownedIfMin(2).obtainedFrom(MOONS).build();
		SnapshotBuilder inventory = new SnapshotBuilder().bankItem(11832, "Bandos chestplate", 1);
		Advice partial = engine.run(inventory.build(), kb);
		assertTrue(partial.getStatuses().stream().anyMatch(s -> s.getGoal().getId().equals("gear:blood")));

		Snapshot bandos = inventory.groupStorageItem(11834, "Bandos tassets", 1).build();
		Advice upgraded = engine.run(bandos, kb);
		assertFalse(upgraded.getStatuses().stream().anyMatch(s -> s.getGoal().getId().equals("gear:blood")),
			"an uncollected set is not an upgrade when its slots are already outclassed");
		assertEquals(List.of("Blue moon chestplate"), upgraded.getStatuses().stream()
			.filter(s -> s.getGoal().getId().equals(MOONS)).findFirst().orElseThrow().getObjective().getRewards()
			.stream().map(RewardTarget::getName).collect(Collectors.toList()));
	}

	@Test
	void owningADropComponentStopsTheBossGrindButNotTheUnmadeGearGoal()
	{
		KnowledgeBase kb = new KbBuilder().milestone("boss:source", MilestoneCategory.BOSS, "Source", 8)
			.bossReward(new BossReward("Upgraded defender", List.of(2, 3), List.of(), null, RewardValue.MAJOR,
				"Upgrade the defender slot", List.of()))
			.milestone("gear:assembled", MilestoneCategory.GEAR, "Upgraded defender", 8)
			.ownedIf("Upgraded defender", 3).obtainedFrom("boss:source").build();
		Advice advice = engine.run(new SnapshotBuilder().bankItem(2, "Defender hilt", 1).build(), kb);
		assertTrue(advice.getStatuses().stream().noneMatch(s -> s.getGoal().getId().equals("boss:source")));
		assertTrue(advice.getStatuses().stream().anyMatch(s -> s.getGoal().getId().equals("gear:assembled")));
	}

	private static KnowledgeBase moons()
	{
		return new KbBuilder().milestone(MOONS, MilestoneCategory.BOSS, "Moons of Peril", 8)
			.bossReward("Blood moon chestplate", 29022).build();
	}

	private static Snapshot observed(BossProgress progress)
	{
		return new SnapshotBuilder().build().toBuilder().bossProgress(Map.of(MOONS, progress)).build();
	}
}

package com.signpost.engine;

import com.signpost.engine.model.Advice;
import com.signpost.engine.model.FocusDetail;
import com.signpost.engine.model.NextStepType;
import com.signpost.engine.model.PrerequisiteGap;
import com.signpost.engine.model.SkillPlan;
import com.signpost.kb.KnowledgeBase;
import com.signpost.kb.MilestoneCategory;
import com.signpost.snapshot.DiaryTier;
import com.signpost.snapshot.Snapshot;
import com.signpost.store.AccountData;
import com.signpost.store.AccountDataMutations;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.stream.Collectors;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** {@link Engine#run} computes {@link Advice#getFocus()} for the goal detail view. */
class EngineFocusTest
{
	private final Engine engine = new Engine(new BoostTable());
	private final Instant now = Instant.parse("2026-09-07T12:00:00Z");

	@Test
	void focusIsNullWithoutAFocusGoalId()
	{
		KnowledgeBase kb = new KbBuilder().quest(0, "Animal Magnetism").skill(Skill.WOODCUTTING, 10).build();
		Snapshot snapshot = new SnapshotBuilder().build();

		Advice advice = engine.run(snapshot, kb, AccountData.empty(), now);

		assertNull(advice.getFocus());
	}

	@Test
	void focusedQuestWithAHerbloreGapAndABankFixtureGetsASkillStepWithANonEmptyRoute()
	{
		KnowledgeBase kb = new KbBuilder()
			.quest(0, "Song of the Elves").skill(Skill.HERBLORE, 10)
			.method(Skill.HERBLORE, "Prayer potion(3)", 1, 100)
			.material(10, 1)
			.build();
		Snapshot snapshot = new SnapshotBuilder().bankItem(10, "Ranarr potion (unf)", 10_000).build();
		AccountData data = focusOn("quest:0");

		Advice advice = engine.run(snapshot, kb, data, now);

		FocusDetail focus = advice.getFocus();
		assertNotNull(focus);
		assertEquals("quest:0", focus.getStatus().getGoal().getId());
		assertEquals(NextStepType.SKILL, focus.getNext().getType());
		assertEquals(Skill.HERBLORE, focus.getNext().getSkillGap().getSkill());
		assertNotNull(focus.getRoute());
		assertFalse(focus.getRoute().getSteps().isEmpty());
		assertSame(focus.getRoute(), focus.getNext().getRoute(), "FocusDetail.route must be the same object NextStepPicker computed, not a second computation");
		assertEquals(0, focus.getRoute().getUncoveredXp());
		assertNull(focus.getShortfall(), "route fully covers the xp delta, so there is no shortfall");
		assertEquals(1, focus.getFromLevel());
		assertEquals(10, focus.getToLevel());
	}

	@Test
	void focusedGoalAbsentFromStatusesIsNull()
	{
		// "quest:999" isn't in the kb at all, so it can never appear among the evaluated statuses.
		KnowledgeBase kb = new KbBuilder().quest(0, "Animal Magnetism").skill(Skill.WOODCUTTING, 10).build();
		Snapshot snapshot = new SnapshotBuilder().build();
		AccountData data = focusOn("quest:999");

		Advice advice = engine.run(snapshot, kb, data, now);

		assertNull(advice.getFocus());
	}

	@Test
	void blockedDependantRemainsFocusableWhenItsPrerequisiteIsHidden()
	{
		KnowledgeBase kb = new KbBuilder()
			.milestone("room", MilestoneCategory.POH, "Room", 5).item("Coins", 995, 200000)
			.milestone("box", MilestoneCategory.POH, "Box", 7).prerequisite("room")
			.build();
		AccountData data = AccountDataMutations.ignore(focusOn("box"), "room");

		Advice advice = engine.run(new SnapshotBuilder().build(), kb, data, now);

		assertTrue(advice.getPicked().isEmpty(), "hiding the room must not cause an automatic box suggestion");
		assertEquals(List.of("box"), advice.getRanked().stream().map(r -> r.getStatus().getGoal().getId()).collect(Collectors.toList()));
		assertNotNull(advice.getFocus());
		assertEquals("box", advice.getFocus().getStatus().getGoal().getId());
		assertFalse(advice.getFocus().getStatus().isReady());
		assertTrue(advice.getFocus().getStatus().getGaps().stream().anyMatch(g -> g instanceof PrerequisiteGap));
	}

	private static final int BIOHAZARD_ID = 9;    // Quest.BIOHAZARD
	private static final int CLOCK_TOWER_ID = 14; // Quest.CLOCK_TOWER

	/** {@link Advice#getFocus()} computing one {@link SkillPlan} per distinct skill gap of the focused goal. */
	@Test
	void focusedGoalWithThreeSkillGapsProducesThreeSkillPlansSortedByXpDeltaAscending()
	{
		// Declared out of target-level order to prove the result is sorted, not insertion order.
		KnowledgeBase kb = new KbBuilder()
			.quest(0, "Test Quest").skill(Skill.MINING, 20).skill(Skill.HERBLORE, 10).skill(Skill.WOODCUTTING, 5)
			.build();
		Snapshot snapshot = new SnapshotBuilder().build();
		AccountData data = focusOn("quest:0");

		Advice advice = engine.run(snapshot, kb, data, now);

		FocusDetail focus = advice.getFocus();
		assertNotNull(focus);
		List<SkillPlan> plans = focus.getSkillPlans();
		assertEquals(3, plans.size());
		assertEquals(Skill.WOODCUTTING, plans.get(0).getSkill());
		assertEquals(5, plans.get(0).getToLevel());
		assertEquals(Skill.HERBLORE, plans.get(1).getSkill());
		assertEquals(10, plans.get(1).getToLevel());
		assertEquals(Skill.MINING, plans.get(2).getSkill());
		assertEquals(20, plans.get(2).getToLevel());
	}

	@Test
	void pickedSkillsSkillPlanRouteIsTheSameObjectAsNextRoute()
	{
		KnowledgeBase kb = new KbBuilder()
			.quest(0, "Test Quest").skill(Skill.HERBLORE, 10).skill(Skill.WOODCUTTING, 5)
			.method(Skill.HERBLORE, "Prayer potion(3)", 1, 100)
			.material(10, 1)
			.build();
		// Only Herblore's route is bank-covered; Woodcutting has no methods at all, so it can never
		// be "covered" and NextStepPicker branch B must pick Herblore despite its larger xpDelta.
		Snapshot snapshot = new SnapshotBuilder().bankItem(10, "Ranarr potion (unf)", 10_000).build();
		AccountData data = focusOn("quest:0");

		Advice advice = engine.run(snapshot, kb, data, now);

		FocusDetail focus = advice.getFocus();
		assertNotNull(focus);
		assertEquals(NextStepType.SKILL, focus.getNext().getType());
		assertEquals(Skill.HERBLORE, focus.getNext().getSkillGap().getSkill());
		assertNotNull(focus.getNextSkillPlan());
		assertEquals(Skill.HERBLORE, focus.getNextSkillPlan().getSkill());
		assertSame(focus.getNext().getRoute(), focus.getNextSkillPlan().getRoute(),
			"the next skill's SkillPlan.route must be the same object NextStepPicker already computed, not a second computation");
		assertSame(focus.getRoute(), focus.getNextSkillPlan().getRoute());
	}

	@Test
	void duplicateSkillGapAtTwoLevelsKeepsTheHigherTargetLevel()
	{
		// A boss milestone's hard skill requirement and its recommended profile both name Herblore,
		// at different levels - both land as separate SkillLevelGaps in the same GoalStatus.
		KnowledgeBase kb = new KbBuilder()
			.milestone("boss:test", MilestoneCategory.BOSS, "Test Boss", 1)
			.skill(Skill.HERBLORE, 30)
			.recommendedSkill(Skill.HERBLORE, 50)
			.build();
		Snapshot snapshot = new SnapshotBuilder().build();
		AccountData data = focusOn("boss:test");

		Advice advice = engine.run(snapshot, kb, data, now);

		FocusDetail focus = advice.getFocus();
		assertNotNull(focus);
		List<SkillPlan> herblorePlans = focus.getSkillPlans().stream()
			.filter(p -> p.getSkill() == Skill.HERBLORE)
			.collect(Collectors.toList());
		assertEquals(1, herblorePlans.size(), "the two Herblore gaps must collapse into one SkillPlan");
		assertEquals(50, herblorePlans.get(0).getToLevel(), "the higher of the two target levels must win");
	}

	@Test
	void diaryTaskInnerSkillGapGetsDiaryTaskSourceWithOrdinal()
	{
		KnowledgeBase kb = new KbBuilder()
			.diary(DiaryTier.VARROCK_EASY).task(3, "Mine some tin").skill(Skill.MINING, 10)
			.build();
		Snapshot snapshot = new SnapshotBuilder().build();
		AccountData data = focusOn("diary:VARROCK_EASY");

		Advice advice = engine.run(snapshot, kb, data, now);

		FocusDetail focus = advice.getFocus();
		assertNotNull(focus);
		assertEquals(1, focus.getSkillPlans().size());
		SkillPlan plan = focus.getSkillPlans().get(0);
		assertEquals(Skill.MINING, plan.getSkill());
		assertEquals("diary task 3", plan.getSource());
	}

	@Test
	void skillPlansFlagCoveredWhenTheRouteReachesTargetAndUncoveredOtherwise()
	{
		KnowledgeBase kb = new KbBuilder()
			.quest(0, "Test Quest").skill(Skill.HERBLORE, 10).skill(Skill.WOODCUTTING, 5)
			.method(Skill.HERBLORE, "H", 1, 100)
			.material(1, 1)
			.build();
		Snapshot snapshot = new SnapshotBuilder().bankItem(1, "H material", 100_000).build();
		AccountData data = focusOn("quest:0");

		Advice advice = engine.run(snapshot, kb, data, now);

		FocusDetail focus = advice.getFocus();
		assertNotNull(focus);
		SkillPlan herblore = planFor(focus, Skill.HERBLORE);
		SkillPlan woodcutting = planFor(focus, Skill.WOODCUTTING);

		assertTrue(herblore.isCovered());
		assertNull(herblore.getShortfall(), "a covered plan carries no shortfall");
		assertFalse(woodcutting.isCovered());
		assertNotNull(woodcutting.getShortfall(), "an uncovered plan must have its shortfall resolved");
	}

	@Test
	void nextSkillPlanIsNullWhenTheNextStepIsAQuest()
	{
		KnowledgeBase kb = new KbBuilder()
			.quest(CLOCK_TOWER_ID, "Clock Tower").prereq("Biohazard").skill(Skill.MINING, 20)
			.quest(BIOHAZARD_ID, "Biohazard")
			.build();
		Snapshot snapshot = new SnapshotBuilder().quest(Quest.BIOHAZARD, QuestState.NOT_STARTED).build();
		AccountData data = focusOn("quest:" + CLOCK_TOWER_ID);

		Advice advice = engine.run(snapshot, kb, data, now);

		FocusDetail focus = advice.getFocus();
		assertNotNull(focus);
		assertEquals(NextStepType.QUEST, focus.getNext().getType());
		assertNull(focus.getNextSkillPlan());
		assertFalse(focus.getSkillPlans().isEmpty(), "the quest's own skill gap should still produce a SkillPlan even though it wasn't picked next");
	}

	private static SkillPlan planFor(FocusDetail focus, Skill skill)
	{
		return focus.getSkillPlans().stream().filter(p -> p.getSkill() == skill).findFirst()
			.orElseThrow(() -> new AssertionError("no SkillPlan for " + skill));
	}

	private static AccountData focusOn(String goalId)
	{
		return new AccountData(new HashMap<>(), null, new HashMap<>(), new HashSet<>(), new ArrayList<>(), goalId, new HashSet<>());
	}
}

package com.signpost.engine;

import com.signpost.kb.KnowledgeBase;
import com.signpost.snapshot.DiaryTier;
import com.signpost.snapshot.Snapshot;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

class DiaryProgressTest
{
	@Test
	void countsCompletedTasksFromTaskCompletionBits()
	{
		KnowledgeBase kb = new KbBuilder().diaryTier(DiaryTier.VARROCK_EASY, 1176, 4).build();
		// bits 0 and 2 set -> tasks 1 and 3 complete, 2 and 4 not.
		Snapshot snapshot = new SnapshotBuilder().diaryVarp(1176, 0b0101).build();

		Map<DiaryTier, DiaryTierProgress> progress = DiaryProgress.compute(snapshot, kb);
		DiaryTierProgress varrockEasy = progress.get(DiaryTier.VARROCK_EASY);

		assertEquals(2, varrockEasy.getCompleted());
		assertEquals(4, varrockEasy.getTotal());
		assertEquals(List.of(1, 3), varrockEasy.getCompletedOrdinals());
	}

	@Test
	void mismatchIsTrueWhenGameCountDiffersFromComputedCount()
	{
		KnowledgeBase kb = new KbBuilder().diaryTier(DiaryTier.VARROCK_EASY, 1176, 4).build();
		Snapshot snapshot = new SnapshotBuilder()
			.diaryVarp(1176, 0b0101)
			.diaryCountVarbit(DiaryProgress.COUNT_VARBITS.get(DiaryTier.VARROCK_EASY), 3)
			.build();

		DiaryTierProgress varrockEasy = DiaryProgress.compute(snapshot, kb).get(DiaryTier.VARROCK_EASY);

		assertEquals(2, varrockEasy.getCompleted());
		assertEquals(3, varrockEasy.getGameCount());
		assertTrue(varrockEasy.isMismatch());
	}

	@Test
	void mismatchIsFalseWhenGameCountMatches()
	{
		KnowledgeBase kb = new KbBuilder().diaryTier(DiaryTier.VARROCK_EASY, 1176, 4).build();
		Snapshot snapshot = new SnapshotBuilder()
			.diaryVarp(1176, 0b0101)
			.diaryCountVarbit(DiaryProgress.COUNT_VARBITS.get(DiaryTier.VARROCK_EASY), 2)
			.build();

		DiaryTierProgress varrockEasy = DiaryProgress.compute(snapshot, kb).get(DiaryTier.VARROCK_EASY);

		assertFalse(varrockEasy.isMismatch());
	}

	@Test
	void gameCountAndMismatchAreAbsentWhenSnapshotHasNoCountVarbitData()
	{
		KnowledgeBase kb = new KbBuilder().diaryTier(DiaryTier.VARROCK_EASY, 1176, 4).build();
		Snapshot snapshot = new SnapshotBuilder().diaryVarp(1176, 0b0101).build();

		DiaryTierProgress varrockEasy = DiaryProgress.compute(snapshot, kb).get(DiaryTier.VARROCK_EASY);

		assertNull(varrockEasy.getGameCount());
		assertFalse(varrockEasy.isMismatch());
	}
}

