	@Test
	void owningTwoStageFourGearMilestonesAloneReachesStageFour()
	{
		KnowledgeBase kb = new KbBuilder()
			.milestone("g:1", MilestoneCategory.GEAR, "Gear One", 5).ownedIf("Item One", 101).stage(4)
			.milestone("g:2", MilestoneCategory.GEAR, "Gear Two", 5).ownedIf("Item Two", 102).stage(4)
			.build();
		Snapshot snapshot = new SnapshotBuilder().inventoryItem(101, "Item One", 1).inventoryItem(102, "Item Two", 1).build();

		assertEquals(4, StageEstimator.estimate(snapshot, kb));
	}

	/** A manually-marked-owned stage-4 gear milestone counts towards the stage-4 gear count, same as one held in a container. */
	@Test
	void manuallyOwnedStageFourGearMilestonesReachStageFour()
	{
		KnowledgeBase kb = new KbBuilder()
			.milestone("g:1", MilestoneCategory.GEAR, "Gear One", 5).ownedIf("Item One", 101).stage(4)
			.milestone("g:2", MilestoneCategory.GEAR, "Gear Two", 5).ownedIf("Item Two", 102).stage(4)
			.build();
		Snapshot snapshot = new SnapshotBuilder().build();

		assertEquals(4, StageEstimator.estimate(snapshot, kb, Set.of("g:1", "g:2")));
	}

	@Test
	void combatOneTwentyAndTwoOwnedStageThreeGearMilestonesReachesStageFour()
	{
		KnowledgeBase kb = new KbBuilder()
			.milestone("g:1", MilestoneCategory.GEAR, "Gear One", 5).ownedIf("Item One", 101).stage(3)
			.milestone("g:2", MilestoneCategory.GEAR, "Gear Two", 5).ownedIf("Item Two", 102).stage(3)
			.build();
		SnapshotBuilder builder = new SnapshotBuilder().inventoryItem(101, "Item One", 1).inventoryItem(102, "Item Two", 1);
		setCombatSkills(builder, 95); // combat level 121 >= 120
		Snapshot snapshot = builder.build();

		assertEquals(4, StageEstimator.estimate(snapshot, kb));
	}

	@Test
	void combatOneTwentyAloneWithoutTwoOwnedStageThreeGearStaysBelowStageFour()
	{
		SnapshotBuilder builder = new SnapshotBuilder();
		setCombatSkills(builder, 95); // combat level 121 >= 120, but no owned stage-3 gear at all.
		Snapshot snapshot = builder.build();
		KnowledgeBase kb = new KbBuilder().build();

		// Falls through to the stage-2 combat>=85 branch, not stage 4.
		assertEquals(2, StageEstimator.estimate(snapshot, kb));
	}

	/** Mid-game profile: combat ~105, total ~1600s, 150 quests, no raid gear -> stage 2. */
	@Test
	void midGameProfileWithoutRaidGearIsStageTwo()
	{
		SnapshotBuilder builder = new SnapshotBuilder();
		setCombatSkills(builder, 83); // combat level 105
		for (Skill skill : Skill.values())
		{
			if (!isCombatSkill(skill))
			{
				builder.skill(skill, 66);
			}
		}
		Quest[] quests = Quest.values();
		for (int i = 0; i < 150; i++)
		{
			builder.quest(quests[i], QuestState.FINISHED);
		}
		Snapshot snapshot = builder.build();
		KnowledgeBase kb = new KbBuilder()
			.milestone("boss:tob", MilestoneCategory.BOSS, "Theatre of Blood", 5)
			.milestone("boss:cox", MilestoneCategory.BOSS, "Chambers of Xeric", 5)
			.build();

		assertEquals(2, StageEstimator.estimate(snapshot, kb));
	}

	/**
	 * A group-ironman account's shared bank contains a single Masori mask, which must not
	 * establish stage 4 by itself. Bundled
	 * KB, real item ids: Masori mask (stage 4), Armadyl chainskirt (stage 3), toxic blowpipe, imbued
	 * slayer helmet (both stage 2), fighter torso, dragon defender, graceful outfit (all stage 1).
	 */
	@Test
	void usersLiveDiagnosticsProfileWithOnlyOneStageFourGearPieceStaysAtStageTwo()
	{
		SnapshotBuilder builder = new SnapshotBuilder();
		setCombatSkills(builder, 83); // combat level 105
		for (Skill skill : Skill.values())
		{
			if (!isCombatSkill(skill))
			{
				builder.skill(skill, 66); // total level ~1637, matching the diagnostics profile's ~1643.
			}
		}
		Quest[] quests = Quest.values();
		for (int i = 0; i < 150; i++)
		{
			builder.quest(quests[i], QuestState.FINISHED);
		}
		builder
			.inventoryItem(27226, "Masori mask", 1)
			.inventoryItem(11830, "Armadyl chainskirt", 1)
			.inventoryItem(12926, "Toxic blowpipe", 1)
			.inventoryItem(11865, "Slayer helmet (i)", 1)
			.inventoryItem(10551, "Fighter torso", 1)
			.inventoryItem(12954, "Dragon defender", 1)
			.inventoryItem(11850, "Graceful hood", 1);
		Snapshot snapshot = builder.build();
		KnowledgeBase kb = KnowledgeBase.load(new Gson());

		assertEquals(2, StageEstimator.estimate(snapshot, kb));
	}

	private static void setCombatSkills(SnapshotBuilder builder, int level)
	{
		for (Skill skill : COMBAT_SKILLS)
		{
			builder.skill(skill, level);
		}
	}

	private static boolean isCombatSkill(Skill skill)
	{
		for (Skill combatSkill : COMBAT_SKILLS)
		{
			if (combatSkill == skill)
			{
				return true;
			}
		}
		return false;
	}
}

package com.signpost.engine;

import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import java.util.stream.Collectors;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

class EngineRunnerTest
{
	@Test
	void staleResultIsDiscardedWhenNewerWorkWasSubmitted() throws InterruptedException
	{
		EngineRunner runner = new EngineRunner();
		CountDownLatch firstStarted = new CountDownLatch(1);
		CountDownLatch releaseFirst = new CountDownLatch(1);
		AtomicReference<String> delivered = new AtomicReference<>();
		AtomicInteger deliveries = new AtomicInteger();

		runner.submit(() ->
		{
			firstStarted.countDown();
			await(releaseFirst);
			return "first";
		}, result ->
		{
			delivered.set(result);
			deliveries.incrementAndGet();
		});

		assertTrue(firstStarted.await(5, TimeUnit.SECONDS), "first work did not start");

		// The executor is single-threaded, so this queues behind the still-blocked first task
		// rather than running immediately - that's fine, we only need it submitted before release.
		CountDownLatch secondDelivered = new CountDownLatch(1);
		runner.submit(() -> "second", result ->
		{
			delivered.set(result);
			deliveries.incrementAndGet();
			secondDelivered.countDown();
		});

		releaseFirst.countDown();

		assertTrue(secondDelivered.await(5, TimeUnit.SECONDS), "second result was not delivered");
		assertEquals("second", delivered.get());
		assertEquals(1, deliveries.get(), "stale first result must not be delivered");

		runner.shutdown();
	}

	@Test
	void onResultIsNotCalledAfterShutdown() throws InterruptedException
	{
		EngineRunner runner = new EngineRunner();
		CountDownLatch workStarted = new CountDownLatch(1);
		CountDownLatch releaseWork = new CountDownLatch(1);
		AtomicReference<String> delivered = new AtomicReference<>();

		runner.submit(() ->
		{
			workStarted.countDown();
			await(releaseWork);
			return "result";
		}, delivered::set);

		assertTrue(workStarted.await(5, TimeUnit.SECONDS), "work did not start");
		runner.shutdown();
		releaseWork.countDown();

		Thread.sleep(200);

		assertNull(delivered.get(), "onResult must not be called after shutdown");
	}

	@Test
	void aThrowingTaskIsReportedAndDoesNotStopTheNextSubmission() throws InterruptedException
	{
		List<Throwable> reported = new CopyOnWriteArrayList<>();
		CountDownLatch twoReported = new CountDownLatch(2);
		EngineRunner runner = new EngineRunner(e ->
		{
			reported.add(e);
			twoReported.countDown();
		});
		CountDownLatch delivered = new CountDownLatch(1);
		AtomicReference<String> result = new AtomicReference<>();

		runner.submit(() ->
		{
			throw new IllegalStateException("work boom");
		}, r -> result.set("must not be delivered"));
		runner.submit(() -> "ok", r ->
		{
			throw new IllegalStateException("onResult boom");
		});
		// Wait for both failures before the next submit, which would otherwise supersede the
		// second task's generation and legitimately skip its onResult.
		assertTrue(twoReported.await(5, TimeUnit.SECONDS), "both failures must be reported");
		runner.submit(() -> "second", r ->
		{
			result.set(r);
			delivered.countDown();
		});

		assertTrue(delivered.await(5, TimeUnit.SECONDS), "the submission after a failure must still deliver");
		assertEquals("second", result.get());
		assertEquals(List.of("work boom", "onResult boom"), reported.stream().map(Throwable::getMessage).collect(Collectors.toList()));

		runner.shutdown();
	}

	@Test
	void executeRunsEvenWhenANewerSubmitLandsBeforeIt() throws InterruptedException
	{
		EngineRunner runner = new EngineRunner();
		CountDownLatch firstStarted = new CountDownLatch(1);
		CountDownLatch releaseFirst = new CountDownLatch(1);
		CountDownLatch executed = new CountDownLatch(1);
		AtomicInteger deliveries = new AtomicInteger();

		runner.submit(() ->
		{
			firstStarted.countDown();
			await(releaseFirst);
			return "blocker";
		}, r -> deliveries.incrementAndGet());
		assertTrue(firstStarted.await(5, TimeUnit.SECONDS));

		runner.execute(executed::countDown);
		runner.submit(() -> "newer", r -> deliveries.incrementAndGet());
		releaseFirst.countDown();

		assertTrue(executed.await(5, TimeUnit.SECONDS), "execute must run regardless of the generation race");
		runner.shutdown();
	}

	private static void await(CountDownLatch latch)
	{
		try
		{
			latch.await(5, TimeUnit.SECONDS);
		}
		catch (InterruptedException e)
		{
			Thread.currentThread().interrupt();
		}
	}
}

package com.signpost.engine;

import com.signpost.engine.model.GoalCategory;
import com.signpost.engine.model.GoalRef;
import com.signpost.engine.model.GoalStatus;
import com.signpost.engine.model.QuestXp;
import com.signpost.engine.model.SkillLevelGap;
import com.signpost.kb.KnowledgeBase;
import com.signpost.kb.MilestoneCategory;
import com.signpost.snapshot.DiaryTier;
import com.signpost.snapshot.Snapshot;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.Experience;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** {@link SkillTargetSynthesiser} turns the skill gaps of upcoming goals into "&lt;level&gt; &lt;Skill&gt;" goals. */
class SkillTargetSynthesiserTest
{
	private final GapEngine gapEngine = new GapEngine(new BoostTable());

	@Test
	void lowestUnmetLevelWinsWithPriorityAndStageFromTheParentsNeedingThatLevelAndEveryParentListed()
	{
		// quest:0 priority 9 (stage 3) needs Herblore 78; quest:9 priority 7 (stage 2) and quest:14
		// priority 3 (stage 1) need Herblore 70. The best-scoring 70-parent (quest:9) lends its
		// priority, stage and score; quest:0 is still listed as a parent.
		KnowledgeBase kb = new KbBuilder()
			.quest(0, "Animal Magnetism").skill(Skill.HERBLORE, 78)
			.quest(9, "Biohazard").skill(Skill.HERBLORE, 70)
			.quest(14, "Clock Tower").skill(Skill.HERBLORE, 70)
			.priorityOverride("quest:0", 9)
			.priorityOverride("quest:9", 7)
			.priorityOverride("quest:14", 3)
			.build();
		Snapshot snapshot = new SnapshotBuilder().skill(Skill.HERBLORE, 61).build();

		List<GoalStatus> targets = SkillTargetSynthesiser.synthesise(gapEngine.evaluate(snapshot, kb), Set.of(), 4, snapshot, kb);

		assertEquals(1, targets.size(), ids(targets).toString());
		GoalStatus target = targets.get(0);
		assertEquals("skill:HERBLORE:70", target.getGoal().getId());
		assertEquals("70 Herblore", target.getGoal().getName());
		assertEquals(GoalCategory.SKILL_TARGET, target.getGoal().getCategory());
		assertEquals("https://oldschool.runescape.wiki/w/Herblore_training", target.getGoal().getWikiUrl());
		assertEquals(7, target.getGoal().getPriority(), "priority of the best parent needing level 70");
		assertEquals(2, target.getGoal().getStage(), "stage of the best parent needing level 70");
		GoalStatus biohazard = gapEngine.evaluate(snapshot, kb).stream().filter(s -> s.getGoal().getId().equals("quest:9")).findFirst().orElseThrow();
		assertEquals(Ranker.score(biohazard), target.getParentScore(), 1e-9, "score cap = the best parent's score");
		assertFalse(target.isReady(), "training is never ready now");
		assertEquals(List.of(new GoalRef("quest:9", "Biohazard", 70), new GoalRef("quest:14", "Clock Tower", 70),
			new GoalRef("quest:0", "Animal Magnetism", 78)), target.getParents());

		assertEquals(1, target.getGaps().size());
		SkillLevelGap gap = (SkillLevelGap) target.getGaps().get(0);
		assertEquals(Skill.HERBLORE, gap.getSkill());
		assertEquals(61, gap.getHave());
		assertEquals(70, gap.getNeed());
		assertEquals(Experience.getXpForLevel(70) - Experience.getXpForLevel(61), gap.getXpDelta());
	}

	@Test
	void hiddenAndLaterParentsAreExcludedAndNoTargetWhenNoSkillGaps()
	{
		KnowledgeBase kb = new KbBuilder()
			.quest(0, "Animal Magnetism").skill(Skill.HERBLORE, 70)
			.quest(9, "Biohazard").skill(Skill.MINING, 50).item("Rope", 1)
			.milestone("boss:late", MilestoneCategory.BOSS, "Late Boss", 10).stage(4).skill(Skill.PRAYER, 77)
			.build();
		Snapshot snapshot = new SnapshotBuilder().bankItem(954, "Rope", 1).build();

		// Account stage 1: the stage-4 boss is "later"; quest:0 is hidden.
		List<GoalStatus> targets = SkillTargetSynthesiser.synthesise(gapEngine.evaluate(snapshot, kb), Set.of("quest:0"), 1, snapshot, kb);

		assertEquals(List.of("skill:MINING:50"), ids(targets));
	}

	@Test
	void diaryTaskAndRecommendedSkillGapsCountAsParents()
	{
		KnowledgeBase kb = new KbBuilder()
			.diary(DiaryTier.VARROCK_EASY).task(1, "Mine some iron").skill(Skill.MINING, 15)
			.milestone("boss:test", MilestoneCategory.BOSS, "Test Boss", 8).recommendedSkill(Skill.RANGED, 75)
			.build();
		Snapshot snapshot = new SnapshotBuilder().build();

		List<GoalStatus> targets = SkillTargetSynthesiser.synthesise(gapEngine.evaluate(snapshot, kb), Set.of(), 4, snapshot, kb);

		// Targets come out in Skill enum order (Ranged precedes Mining).
		assertEquals(List.of("skill:RANGED:75", "skill:MINING:15"), ids(targets));
		assertEquals(List.of(new GoalRef("boss:test", "Test Boss", 75)), targets.get(0).getParents());
		assertEquals(List.of(new GoalRef("diary:VARROCK_EASY", "Varrock Easy Diary", 15)), targets.get(1).getParents());
	}

	@Test
	void bankCoveredWhenTheRouteFromTheBankReachesTheTarget()
	{
		KnowledgeBase kb = new KbBuilder()
			.quest(0, "Animal Magnetism").skill(Skill.HERBLORE, 3)
			.method(Skill.HERBLORE, "Prayer potion(3)", 1, 5).material(10, 1)
			.build();
		Snapshot rich = new SnapshotBuilder().bankItem(10, "Ranarr weed", 10_000).build();
		Snapshot poor = new SnapshotBuilder().bankItem(10, "Ranarr weed", 3).build();

		GoalStatus covered = SkillTargetSynthesiser.synthesise(gapEngine.evaluate(rich, kb), Set.of(), 4, rich, kb).get(0);
		GoalStatus uncovered = SkillTargetSynthesiser.synthesise(gapEngine.evaluate(poor, kb), Set.of(), 4, poor, kb).get(0);

		assertTrue(covered.isBankCovered());
		assertNotNull(covered.getBankRoute());
		assertEquals(0, covered.getBankRoute().getUncoveredXp());
		assertFalse(uncovered.isBankCovered());
		assertEquals(Experience.getXpForLevel(3) - 15, uncovered.getBankRoute().getUncoveredXp(), "3 potions at 5 xp each");
	}

	// --- quest reward xp covers skill targets. ---

	@Test
	void targetFullyCoveredByReadyQuestXpIsNotSynthesisedAndTheQuestUnblocksItsParents()
	{
		// 1 xp short of 40 Attack; Waterfall Quest (no requirements, so ready) gives 13,750 Attack xp.
		KnowledgeBase kb = new KbBuilder()
			.quest(158, "Waterfall Quest").rewardXp(Skill.ATTACK, 13_750)
			.quest(0, "Animal Magnetism").skill(Skill.ATTACK, 40)
			.build();
		Snapshot snapshot = new SnapshotBuilder().xp(Skill.ATTACK, Experience.getXpForLevel(40) - 1).build();

		SkillTargetSynthesiser.Synthesis synthesis = SkillTargetSynthesiser.run(gapEngine.evaluate(snapshot, kb), Set.of(), 4, snapshot, kb);

		assertEquals(List.of(), ids(synthesis.getTargets()), "covered by a quest you can do now: no grind target");
		assertEquals(Map.of("quest:158", Set.of("quest:0")), synthesis.getQuestUnblocks());
	}

	@Test
	void partialCoverageReducesTheGapAndListsTheQuestsLargestFirstWithQuestStepsLeadingTheRoute()
	{
		KnowledgeBase kb = new KbBuilder()
			.quest(150, "Tree Gnome Village").rewardXp(Skill.ATTACK, 11_450)
			.quest(158, "Waterfall Quest").rewardXp(Skill.ATTACK, 13_750).rewardXp(Skill.STRENGTH, 13_750)
			.quest(0, "Animal Magnetism").skill(Skill.ATTACK, 40)
			.build();
		Snapshot snapshot = new SnapshotBuilder().build();

		SkillTargetSynthesiser.Synthesis synthesis = SkillTargetSynthesiser.run(gapEngine.evaluate(snapshot, kb), Set.of(), 4, snapshot, kb);

		assertEquals(List.of("skill:ATTACK:40"), ids(synthesis.getTargets()));
		assertEquals(Map.of(), synthesis.getQuestUnblocks(), "partial coverage: the quests don't count as unblocking");
		GoalStatus target = synthesis.getTargets().get(0);
		long delta = Experience.getXpForLevel(40) - 13_750 - 11_450;
		assertEquals(delta, ((SkillLevelGap) target.getGaps().get(0)).getXpDelta(), "xpDelta net of quest xp");
		QuestXp waterfall = new QuestXp("quest:158", "Waterfall Quest", "https://oldschool.runescape.wiki/w/Waterfall_Quest", QuestState.NOT_STARTED, 13_750);
		QuestXp village = new QuestXp("quest:150", "Tree Gnome Village", "https://oldschool.runescape.wiki/w/Tree_Gnome_Village", QuestState.NOT_STARTED, 11_450);
		assertEquals(List.of(waterfall, village), target.getQuestXp(), "largest reward first");
		assertEquals(waterfall, target.getBankRoute().getSteps().get(0).getQuest());
		assertEquals(village, target.getBankRoute().getSteps().get(1).getQuest());
		assertEquals(delta, target.getBankRoute().getUncoveredXp(), "no methods in this KB: the rest is uncovered");
	}

	@Test
	void lampsCountOnlyForAllowedSkillsAtTheirMinimumLevelAndAreSpentOnceInParentScoreOrder()
	{
		// One 5,000 xp lamp usable in Attack or Magic; a 3,000 Attack lamp that needs level 30.
		// Magic's parent (priority 9) outscores Attack's (priority 3), so Magic takes the shared lamp.
		KnowledgeBase kb = new KbBuilder()
			.quest(158, "Waterfall Quest").lamp(5_000, 0, Skill.ATTACK, Skill.MAGIC).lamp(3_000, 30, Skill.ATTACK)
			.quest(0, "Animal Magnetism").skill(Skill.MAGIC, 5)
			.quest(9, "Biohazard").skill(Skill.ATTACK, 5)
			.priorityOverride("quest:0", 9)
			.priorityOverride("quest:9", 3)
			.build();
		Snapshot snapshot = new SnapshotBuilder().build();

		SkillTargetSynthesiser.Synthesis synthesis = SkillTargetSynthesiser.run(gapEngine.evaluate(snapshot, kb), Set.of(), 4, snapshot, kb);

		assertEquals(List.of("skill:ATTACK:5"), ids(synthesis.getTargets()), "Magic is covered by the shared lamp; Attack gets no lamp");
		assertEquals(Map.of("quest:158", Set.of("quest:0")), synthesis.getQuestUnblocks());
		GoalStatus attack = synthesis.getTargets().get(0);
		assertEquals(List.of(), attack.getQuestXp());
		assertEquals(Experience.getXpForLevel(5), ((SkillLevelGap) attack.getGaps().get(0)).getXpDelta());

		// At Attack 30 the level-30 lamp qualifies and counts towards a 40 Attack target.
		KnowledgeBase kb30 = new KbBuilder()
			.quest(158, "Waterfall Quest").lamp(3_000, 30, Skill.ATTACK)
			.quest(9, "Biohazard").skill(Skill.ATTACK, 40)
			.build();
		Snapshot at30 = new SnapshotBuilder().skill(Skill.ATTACK, 30).build();
		GoalStatus target = SkillTargetSynthesiser.run(gapEngine.evaluate(at30, kb30), Set.of(), 4, at30, kb30).getTargets().get(0);
		assertEquals(3_000, target.getQuestXp().get(0).getXp());
	}

	@Test
	void makingHistoryFixedPrayerXpUnlocksItsLevel20LampFromLevel19()
	{
		KnowledgeBase kb = new KbBuilder()
			.quest(92, "Making History").rewardXp(Skill.PRAYER, 1_000).lamp(1_000, 20, Skill.PRAYER)
			.quest(0, "Animal Magnetism").skill(Skill.PRAYER, 30)
			.build();
		Snapshot snapshot = new SnapshotBuilder().skill(Skill.PRAYER, 19).build();

		GoalStatus target = SkillTargetSynthesiser.run(
			gapEngine.evaluate(snapshot, kb), Set.of(), 4, snapshot, kb).getTargets().get(0);

		assertEquals(List.of(new QuestXp("quest:92", "Making History",
			"https://oldschool.runescape.wiki/w/Making_History", QuestState.NOT_STARTED, 2_000)), target.getQuestXp());
		long remaining = Experience.getXpForLevel(30) - Experience.getXpForLevel(19) - 2_000;
		assertEquals(remaining, ((SkillLevelGap) target.getGaps().get(0)).getXpDelta());
		assertEquals(remaining, target.getBankRoute().getUncoveredXp());
	}

	@Test
	void lampsUnlockLargerLampsWithoutReusingThemOrBypassingSkillAndLevelRestrictions()
	{
		KnowledgeBase kb = new KbBuilder()
			.quest(92, "Making History").rewardXp(Skill.PRAYER, 1_000)
				.lamp(1_000, 20, Skill.PRAYER, Skill.MAGIC)
				.lamp(3_000, 22, Skill.PRAYER, Skill.MAGIC)
				.lamp(20_000, 40, Skill.PRAYER)
				.lamp(50_000, 20, Skill.HERBLORE)
			.quest(0, "Animal Magnetism").skill(Skill.PRAYER, 30)
			.quest(9, "Biohazard").skill(Skill.MAGIC, 30)
			.priorityOverride("quest:0", 9).priorityOverride("quest:9", 3)
			.build();
		Snapshot snapshot = new SnapshotBuilder().skill(Skill.PRAYER, 19).skill(Skill.MAGIC, 22).build();

		List<GoalStatus> targets = SkillTargetSynthesiser.run(
			gapEngine.evaluate(snapshot, kb), Set.of(), 4, snapshot, kb).getTargets();

		GoalStatus prayer = targets.stream().filter(s -> s.getGoal().getId().equals("skill:PRAYER:30")).findFirst().orElseThrow();
		GoalStatus magic = targets.stream().filter(s -> s.getGoal().getId().equals("skill:MAGIC:30")).findFirst().orElseThrow();
		assertEquals(5_000, prayer.getQuestXp().stream().mapToLong(QuestXp::getXp).sum());
		assertEquals(Experience.getXpForLevel(30) - Experience.getXpForLevel(19) - 5_000,
			((SkillLevelGap) prayer.getGaps().get(0)).getXpDelta());
		assertEquals(List.of(), magic.getQuestXp(), "both shared lamps were spent on the higher-ranked Prayer target");
	}

	@Test
	void equalValuedLampsAreIndependentRewardsAcrossTargets()
	{
		KnowledgeBase kb = new KbBuilder()
			.quest(158, "Waterfall Quest").lamp(5_000, 0, Skill.ATTACK, Skill.MAGIC)
				.lamp(5_000, 0, Skill.ATTACK, Skill.MAGIC)
			.quest(150, "Tree Gnome Village").lamp(5_000, 0, Skill.ATTACK, Skill.MAGIC)
			.quest(0, "Animal Magnetism").skill(Skill.MAGIC, 5)
			.quest(9, "Biohazard").skill(Skill.ATTACK, 30)
			.priorityOverride("quest:0", 9).priorityOverride("quest:9", 3)
			.build();
		Snapshot snapshot = new SnapshotBuilder().build();
		SkillTargetSynthesiser.Synthesis result = SkillTargetSynthesiser.run(
			gapEngine.evaluate(snapshot, kb), Set.of(), 4, snapshot, kb);
		assertEquals(List.of("skill:ATTACK:30"), ids(result.getTargets()));
		assertEquals(10_000, result.getTargets().get(0).getQuestXp().stream().mapToLong(QuestXp::getXp).sum());
	}

	@Test
	void rewardCoverageDoesNotClaimToUnblockHigherLevelParents()
	{
		KnowledgeBase kb = new KbBuilder()
			.quest(158, "Waterfall Quest").rewardXp(Skill.ATTACK, 500)
			.quest(0, "Animal Magnetism").skill(Skill.ATTACK, 5)
			.quest(9, "Biohazard").skill(Skill.ATTACK, 40)
			.build();
		Snapshot snapshot = new SnapshotBuilder().build();
		SkillTargetSynthesiser.Synthesis result = SkillTargetSynthesiser.run(
			gapEngine.evaluate(snapshot, kb), Set.of(), 4, snapshot, kb);
		assertEquals(Map.of("quest:158", Set.of("quest:0")), result.getQuestUnblocks());
	}

	@Test
	void onlyUnfinishedVisibleQuestsWithTheirOwnRequirementsMetSupplyXp()
	{
		KnowledgeBase kb = new KbBuilder()
			.quest(158, "Waterfall Quest").rewardXp(Skill.ATTACK, 500)
			.quest(150, "Tree Gnome Village").rewardXp(Skill.ATTACK, 700).skill(Skill.MAGIC, 30)
			.quest(9, "Biohazard").rewardXp(Skill.ATTACK, 900)
			.quest(0, "Animal Magnetism").skill(Skill.ATTACK, 40)
			.build();
		Snapshot snapshot = new SnapshotBuilder().quest(Quest.WATERFALL_QUEST, QuestState.IN_PROGRESS)
			.quest(Quest.BIOHAZARD, QuestState.FINISHED).build();
		List<GoalStatus> statuses = gapEngine.evaluate(snapshot, kb);
		GoalStatus attack = SkillTargetSynthesiser.run(statuses, Set.of(), 4, snapshot, kb).getTargets().stream()
			.filter(s -> s.getGoal().getId().equals("skill:ATTACK:40")).findFirst().orElseThrow();
		assertEquals(List.of(new QuestXp("quest:158", "Waterfall Quest",
			"https://oldschool.runescape.wiki/w/Waterfall_Quest", QuestState.IN_PROGRESS, 500)), attack.getQuestXp());
		GoalStatus hiddenAttack = SkillTargetSynthesiser.run(statuses, Set.of("quest:158"), 4, snapshot, kb).getTargets().stream()
			.filter(s -> s.getGoal().getId().equals("skill:ATTACK:40")).findFirst().orElseThrow();
		assertEquals(List.of(), hiddenAttack.getQuestXp());
	}

	private static List<String> ids(List<GoalStatus> statuses)
	{
		return statuses.stream().map(s -> s.getGoal().getId()).collect(Collectors.toList());
	}
}

package com.signpost.engine;

import com.signpost.engine.model.Route;
import com.signpost.engine.model.RouteStep;
import com.signpost.engine.model.Shortfall;
import com.signpost.engine.model.ShortfallItem;
import com.signpost.engine.model.SkillPlan;
import com.signpost.kb.ItemQuantity;
import com.signpost.kb.MethodEntry;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

/** The group storage share per route step / shortfall line is decided by the engine, in planner order. */
class GroupStorageSharesTest
{
	private static final int UNF = 200;
	private static final int RANARR = 201;

	private static MethodEntry method(String name, int... materialIds)
	{
		List<ItemQuantity> materials = new java.util.ArrayList<>();
		for (int id : materialIds)
		{
			materials.add(new ItemQuantity("item " + id, id, 1));
		}
		return new MethodEntry(Skill.HERBLORE, name, name, 1, 10, materials, List.of(), List.of(), true, false, null, false, true);
	}

	@Test
	void stepsConsumeStorageFirstInRouteOrderAndShortfallLinesShareTheRemainderWithoutConsuming()
	{
		RouteStep craft = new RouteStep(method("make unf", RANARR), 2, 1, 1, 0L, Map.of(RANARR, 2), List.of());
		RouteStep first = new RouteStep(method("brew", UNF), 4, 1, 2, 40L, Map.of(UNF, 4), List.of(craft));
		RouteStep second = new RouteStep(method("restore", UNF), 4, 2, 3, 40L, Map.of(UNF, 4), List.of());
		Route route = new Route(List.of(first, second), 100L, 80L, Map.of(UNF, 3, RANARR, 1));
		ItemQuantity unf = new ItemQuantity("unf", UNF, 1);
		ItemQuantity ranarr = new ItemQuantity("ranarr", RANARR, 1);
		ShortfallItem child = new ShortfallItem(ranarr, 1, 10, List.of(), List.of());
		Shortfall alternative = new Shortfall(method("alt", UNF), List.of(new ShortfallItem(unf, 3, 10, List.of(), List.of())), 100L, 10);
		Shortfall shortfall = new Shortfall(method("restore", UNF), List.of(new ShortfallItem(unf, 3, 10, List.of(), List.of(child))), 100L, 10, alternative);
		SkillPlan plan = new SkillPlan(Skill.HERBLORE, 1, 3, 0L, 100L, false, route, shortfall, false, "quest");

		SkillPlan shared = GroupStorageShares.apply(plan, Map.of(UNF, 5, RANARR, 3));

		List<RouteStep> steps = shared.getRoute().getSteps();
		assertEquals(Map.of(UNF, 4), steps.get(0).getFromGroupStorage(), "first step takes 4 of the 5");
		assertEquals(Map.of(RANARR, 2), steps.get(0).getCrafts().get(0).getFromGroupStorage(), "its craft takes 2 of the 3 ranarr");
		assertEquals(Map.of(UNF, 1), steps.get(1).getFromGroupStorage(), "second step gets the last 1");
		assertEquals(0, shared.getShortfall().getItems().get(0).getInGroupStorage(), "storage is used up: have 3 is bank");
		assertEquals(1, shared.getShortfall().getItems().get(0).getCraftFrom().get(0).getInGroupStorage(), "craft-from child: min(have 1, 1 left)");
		assertEquals(0, shared.getShortfall().getAlternative().getItems().get(0).getInGroupStorage(), "alternative restates the same have");
		assertEquals(plan.getShortfall().getMethod(), shared.getShortfall().getMethod());
		assertEquals(4, steps.get(0).getCount(), "everything else is untouched");
	}

	@Test
	void shortfallItemsRepeatingAnItemAllShowTheSameShareBecauseNothingIsConsumed()
	{
		Route route = new Route(List.of(), 100L, 0L, Map.of(UNF, 4));
		ItemQuantity unf = new ItemQuantity("unf", UNF, 1);
		ShortfallItem child = new ShortfallItem(unf, 4, 10, List.of(), List.of());
		Shortfall alternative = new Shortfall(method("alt", UNF), List.of(new ShortfallItem(unf, 4, 10, List.of(), List.of())), 100L, 10);
		Shortfall shortfall = new Shortfall(method("m", UNF), List.of(new ShortfallItem(unf, 4, 10, List.of(), List.of(child))), 100L, 10, alternative);
		SkillPlan plan = new SkillPlan(Skill.HERBLORE, 1, 3, 0L, 100L, false, route, shortfall, false, "quest");

		SkillPlan shared = GroupStorageShares.apply(plan, Map.of(UNF, 3));

		assertEquals(3, shared.getShortfall().getItems().get(0).getInGroupStorage());
		assertEquals(3, shared.getShortfall().getItems().get(0).getCraftFrom().get(0).getInGroupStorage());
		assertEquals(3, shared.getShortfall().getAlternative().getItems().get(0).getInGroupStorage());
	}

	@Test
	void coveredPlanWithNoShortfallAndEmptyStorageIsUnchanged()
	{
		RouteStep step = new RouteStep(method("brew", UNF), 4, 1, 2, 40L, Map.of(UNF, 4), List.of());
		Route route = new Route(List.of(step), 0L, 80L, Map.of());
		SkillPlan plan = new SkillPlan(Skill.HERBLORE, 1, 2, 0L, 40L, false, route, null, true, "quest");

		SkillPlan shared = GroupStorageShares.apply(plan, Map.of());

		assertEquals(Map.of(), shared.getRoute().getSteps().get(0).getFromGroupStorage());
		assertEquals(null, shared.getShortfall());
	}
}

package com.signpost.engine;

import com.signpost.engine.model.GoalStatus;
import com.signpost.engine.model.Met;
import com.signpost.kb.KnowledgeBase;
import com.signpost.kb.MilestoneCategory;
import com.signpost.snapshot.DiaryTier;
import com.signpost.snapshot.Snapshot;
import java.util.List;
import java.util.stream.Collectors;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** {@link GapEngine} records met requirements alongside gaps, one {@link Met} per satisfied requirement. */
class GapEngineMetTest
{
	private final GapEngine engine = new GapEngine(new BoostTable());

	@Test
	void questRecordsMetSkillPrereqItemQuestPointsKudosAndCombat()
	{
		KnowledgeBase kb = new KbBuilder()
			.quest(9, "Biohazard")
			.quest(0, "Animal Magnetism")
			.skill(Skill.HERBLORE, 70).skill(Skill.AGILITY, 80)
			.prereq("Biohazard")
			.item("Rope", 2)
			.questPoints(30)
			.kudos(50)
			.combat(60)
			.build();
		Snapshot snapshot = new SnapshotBuilder()
			.skill(Skill.HERBLORE, 74)
			.skill(Skill.ATTACK, 70).skill(Skill.STRENGTH, 70).skill(Skill.DEFENCE, 70).skill(Skill.HITPOINTS, 70)
			.quest(Quest.BIOHAZARD, QuestState.FINISHED)
			.bankItem(954, "Rope", 3)
			.questPoints(45)
			.kudos(60)
			.build();

		GoalStatus status = find(engine.evaluate(snapshot, kb), "quest:0");

		assertEquals(List.of(
			"SKILL Herblore 70 (have 74)",
			"QUEST Biohazard",
			"ITEM Rope ×2",
			"QUEST_POINTS Quest points 30 (have 45)",
			"KUDOS Kudos 50 (have 60)",
			"COMBAT Combat 60 (have " + snapshot.combatLevel() + ")"), labels(status));
		assertEquals(1, status.getGaps().size(), "Agility 80 is still a gap: " + status.getGaps());
	}

	@Test
	void diaryTierRecordsTasksDoneCount()
	{
		KnowledgeBase kb = new KbBuilder()
			.diary(DiaryTier.VARROCK_EASY)
			.task(1, "one").completion(1176, 0)
			.task(2, "two").completion(1176, 1)
			.task(3, "three").completion(1176, 2)
			.build();
		Snapshot snapshot = new SnapshotBuilder().diaryVarp(1176, 0b011).build();

		GoalStatus status = find(engine.evaluate(snapshot, kb), "diary:VARROCK_EASY");

		assertEquals(1, status.getMet().size(), labels(status).toString());
		Met met = status.getMet().get(0);
		assertEquals(Met.Kind.DIARY, met.getKind());
		assertEquals("2 of 3 tasks done", met.getLabel());
		assertEquals(2, met.getCount());
		assertEquals(3, met.getRequired());
	}


	private static List<String> labels(GoalStatus status)
	{
		return status.getMet().stream().map(m -> m.getKind() + " " + m.getLabel()).collect(Collectors.toList());
	}

	private static GoalStatus find(List<GoalStatus> statuses, String id)
	{
		return statuses.stream().filter(s -> s.getGoal().getId().equals(id)).findFirst().orElseThrow();
	}
}

package com.signpost.engine;

import com.google.gson.Gson;
import com.signpost.engine.model.Advice;
import com.signpost.engine.model.GoalStatus;
import com.signpost.engine.model.PrayerUnlockGap;
import com.signpost.engine.model.SlayerPointsGap;
import com.signpost.kb.KnowledgeBase;
import com.signpost.kb.MilestoneCategory;
import com.signpost.snapshot.PrayerUnlock;
import com.signpost.snapshot.SlayerReward;
import com.signpost.snapshot.SlayerState;
import com.signpost.snapshot.Snapshot;
import com.signpost.snapshot.Spellbook;
import com.signpost.store.AccountData;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class AccountUnlockEngineTest
{
	private final GapEngine engine = new GapEngine(new BoostTable());

	@Test
	void aRewardBecomesAffordableAtItsCostButOnlyTheUnlockRemovesIt()
	{
		KnowledgeBase kb = KnowledgeBase.load(new Gson());
		Snapshot base = new SnapshotBuilder().build();
		Snapshot shortByOne = base.toBuilder().slayer(slayer(49, Set.of())).build();
		GoalStatus missing = status(engine.evaluate(shortByOne, kb), "slayer:bigger-and-badder");
		assertFalse(missing.isReady());
		assertTrue(missing.getGaps().contains(new SlayerPointsGap(49, 50)));
		Snapshot affordable = base.toBuilder().slayer(slayer(50, Set.of())).build();
		assertTrue(status(engine.evaluate(affordable, kb), "slayer:bigger-and-badder").isReady());
		Snapshot purchased = base.toBuilder().slayer(slayer(0, Set.of(SlayerReward.BIGGER_AND_BADDER))).build();
		assertFalse(hasGoal(engine.evaluate(purchased, kb), "slayer:bigger-and-badder"));
	}

	@Test
	void anImbuedCosmeticHelmetCompletesBothHelmetStagesWithoutRequiringAnotherBlackMask()
	{
		KnowledgeBase kb = KnowledgeBase.load(new Gson());
		Snapshot snapshot = new SnapshotBuilder().inventoryItem(26675, "Black slayer helmet (i)", 1).build();
		List<GoalStatus> statuses = engine.evaluate(snapshot, kb);
		assertFalse(hasGoal(statuses, "milestone:slayer-helmet"));
		assertFalse(hasGoal(statuses, "milestone:slayer-helmet-imbued"));
	}

	@Test
	void unlockedPrayersDoNotRequireTheConsumedScrollAndABankedScrollDoesNotImplyAnUnlock()
	{
		KnowledgeBase kb = KnowledgeBase.load(new Gson());
		Snapshot locked = new SnapshotBuilder().skill(Skill.PRAYER, 99).skill(Skill.DEFENCE, 99)
			.bankItem(21034, "Dexterous prayer scroll", 1).bankItem(21079, "Arcane prayer scroll", 1)
			.bankItem(21047, "Torn prayer scroll", 1).build();
		assertTrue(hasGoal(engine.evaluate(locked, kb), "milestone:rigour"));
		assertTrue(hasGoal(engine.evaluate(locked, kb), "milestone:augury"));
		Snapshot unlocked = new SnapshotBuilder().build().toBuilder().rigour(true).augury(true).preserve(true).build();
		List<GoalStatus> statuses = engine.evaluate(unlocked, kb);
		assertFalse(hasGoal(statuses, "milestone:rigour"));
		assertFalse(hasGoal(statuses, "milestone:augury"));
		assertFalse(hasGoal(statuses, "milestone:preserve"));
	}

	@Test
	void aBossPrayerGapLinksToItsUnlockAndDisappearsOnlyAfterReadingThatFlag()
	{
		KnowledgeBase kb = new KbBuilder().milestone("boss:test", MilestoneCategory.BOSS, "Test boss", 5)
			.recommendedPrayer(PrayerUnlock.RIGOUR).build();
		Snapshot locked = new SnapshotBuilder().build();
		GoalStatus before = status(engine.evaluate(locked, kb), "boss:test");
		assertFalse(before.isReady());
		PrayerUnlockGap gap = (PrayerUnlockGap) before.getGaps().get(0);
		assertEquals("milestone:rigour", gap.getPrayer().getMilestoneId());
		assertTrue(status(engine.evaluate(locked.toBuilder().rigour(true).build(), kb), "boss:test").isReady());
	}

	@Test
	void lunarAccessIsKnownFromEitherTheSelectedSpellbookOrTheCompletedQuest()
	{
		KnowledgeBase kb = KnowledgeBase.load(new Gson());
		Snapshot base = new SnapshotBuilder().build();
		assertTrue(hasGoal(engine.evaluate(base, kb), "milestone:lunar-spellbook"));
		assertFalse(hasGoal(engine.evaluate(base.toBuilder().spellbook(Spellbook.LUNAR).build(), kb), "milestone:lunar-spellbook"));
		Snapshot finished = new SnapshotBuilder().quest(Quest.LUNAR_DIPLOMACY, QuestState.FINISHED).build();
		assertFalse(hasGoal(engine.evaluate(finished, kb), "milestone:lunar-spellbook"));
	}

	@Test
	void runesCarriedInAPouchCoverTrainingInsteadOfProducingAGatheringShortfall()
	{
		KnowledgeBase kb = new KbBuilder().quest(0, "Magic training goal").skill(Skill.MAGIC, 2)
			.method(Skill.MAGIC, "Spell", 1, 10).material(561, 1).build();
		AccountData prefs = new AccountData(Map.of(), null, Map.of(), Set.of(), List.of(), "quest:0", Set.of());
		Engine full = new Engine(new BoostTable());
		Snapshot base = new SnapshotBuilder().build();
		Advice empty = full.run(base, kb, prefs, Instant.EPOCH);
		Advice carried = full.run(base.toBuilder().runePouch(Map.of(561, 9)).build(), kb, prefs, Instant.EPOCH);
		assertTrue(empty.getFocus().getRoute().getUncoveredXp() > 0);
		assertEquals(0, carried.getFocus().getRoute().getUncoveredXp());
		assertEquals(9, carried.getFocus().getRoute().getSteps().get(0).getCount());
	}

	private static SlayerState slayer(int points, Set<SlayerReward> unlocks)
	{
		return new SlayerState(null, 0, 5, "Duradel", 0, points, unlocks);
	}

	private static boolean hasGoal(List<GoalStatus> statuses, String id)
	{
		return statuses.stream().anyMatch(status -> status.getGoal().getId().equals(id));
	}

	private static GoalStatus status(List<GoalStatus> statuses, String id)
	{
		return statuses.stream().filter(status -> status.getGoal().getId().equals(id)).findFirst()
			.orElseThrow(() -> new AssertionError("Missing goal " + id));
	}
}

package com.signpost.engine;

import com.google.gson.Gson;
import com.signpost.engine.model.DiaryTierGap;
import com.signpost.engine.model.Gap;
import com.signpost.engine.model.GoalStatus;
import com.signpost.engine.model.ItemGap;
import com.signpost.engine.model.PrerequisiteGap;
import com.signpost.engine.model.RankedGoal;
import com.signpost.engine.model.SkillLevelGap;
import com.signpost.kb.KnowledgeBase;
import com.signpost.kb.MilestoneCategory;
import com.signpost.snapshot.AccountType;
import com.signpost.snapshot.DiaryTier;
import com.signpost.snapshot.Snapshot;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.Skill;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * milestone goals (gear/unlock/prayer/spellbook/slayer_target/boss) produced by
 * {@link GapEngine} from {@code milestones.json} entries.
 */
class MilestoneGapTest
{
	private final GapEngine engine = new GapEngine(new BoostTable());

	@Test
	void gearMilestoneDoneWhenEitherOwnedIfIdIsHeld()
	{
		KnowledgeBase kb = new KbBuilder()
			.milestone("milestone:test-gear", MilestoneCategory.GEAR, "Test Gear", 5)
			.ownedIf("Item A", 100)
			.ownedIf("Item B", 200)
			.build();
		Snapshot snapshot = new SnapshotBuilder().inventoryItem(200, "Item B", 1).build();

		List<GoalStatus> statuses = engine.evaluate(snapshot, kb);

		assertFalse(hasGoal(statuses, "milestone:test-gear"), "owned gear milestone should not be emitted: " + statuses);
	}

	@Test
	void gearMilestoneDoneWhenOwnedViaAWikiVariantIdNotThePrimaryId()
	{
		// Real bug: Dragon defender's ownedIf carried only id 12954, so a player holding the
		// trimmed variant (27008) was told to go get one they already owned.
		KnowledgeBase kb = new KbBuilder()
			.milestone("milestone:dragon-defender", MilestoneCategory.GEAR, "Dragon defender", 5)
			.ownedIf("Dragon defender", 12954, 19722, 20463, 24143, 27008)
			.build();
		Snapshot snapshot = new SnapshotBuilder().inventoryItem(27008, "Dragon defender (t)", 1).build();

		List<GoalStatus> statuses = engine.evaluate(snapshot, kb);

		assertFalse(hasGoal(statuses, "milestone:dragon-defender"),
			"owning a variant id should count as owning the gear milestone: " + statuses);
	}

	@Test
	void unknownTargetOwnershipDoesNotMakeKnownAcquisitionRequirementsUnknown()
	{
		KnowledgeBase kb = new KbBuilder()
			.milestone("milestone:test-gear", MilestoneCategory.GEAR, "Test Gear", 5)
			.ownedIf("Item A", 100)
			.build();
		Snapshot snapshot = new SnapshotBuilder().bankUnknown().build();

		GoalStatus status = goalFor(engine.evaluate(snapshot, kb), "milestone:test-gear");

		assertTrue(status.isReady());
		assertFalse(status.isBankUnknown(), "target ownership is separate from requirement readiness");
	}

	/** Gear held only in the group ironman shared storage counts as owned. */
	@Test
	void gearMilestoneDoneWhenOwnedIfIdIsHeldOnlyInGroupStorage()
	{
		KnowledgeBase kb = new KbBuilder()
			.milestone("milestone:test-gear", MilestoneCategory.GEAR, "Test Gear", 5)
			.ownedIf("Item A", 100)
			.build();
		Snapshot snapshot = new SnapshotBuilder().accountType(AccountType.GROUP).groupStorageItem(100, "Item A", 1).build();

		assertFalse(hasGoal(engine.evaluate(snapshot, kb), "milestone:test-gear"), "gear in group storage is owned");
	}

	/** "Ready now" flips from false to true when recommended gear moves from nowhere into group storage. */
	@Test
	void bossReadyFlipsTrueWhenRecommendedGearAppearsInGroupStorage()
	{
		KnowledgeBase kb = new KbBuilder()
			.milestone("milestone:test-boss", MilestoneCategory.BOSS, "Test Boss", 5)
			.recommendedGearGroup("tool", new com.signpost.kb.OwnedItem("Item A", 100))
			.build();
		Snapshot without = new SnapshotBuilder().accountType(AccountType.GROUP).groupStorageKnown().build();
		Snapshot with = new SnapshotBuilder().accountType(AccountType.GROUP).groupStorageItem(100, "Item A", 1).build();

		GoalStatus before = goalFor(engine.evaluate(without, kb), "milestone:test-boss");
		GoalStatus after = goalFor(engine.evaluate(with, kb), "milestone:test-boss");

		assertFalse(before.isReady(), "nothing owned: " + before);
		assertFalse(before.isBankUnknown(), "unseen group storage is treated as empty, never as unknown");
		assertTrue(after.isReady(), "gear in group storage satisfies its required role: " + after);
	}

	/** A manual "Own it" override finishes a gear milestone even though nothing owned-if is held. */
	@Test
	void gearMilestoneDoneWhenManuallyMarkedOwnedEvenWithNoOwnedIfItemHeld()
	{
		KnowledgeBase kb = new KbBuilder()
			.milestone("milestone:test-gear", MilestoneCategory.GEAR, "Test Gear", 5)
			.ownedIf("Item A", 100)
			.build();
		Snapshot snapshot = new SnapshotBuilder().build();

		List<GoalStatus> statuses = engine.evaluate(snapshot, kb, DiaryProgress.compute(snapshot, kb), Set.of("milestone:test-gear"));

		assertFalse(hasGoal(statuses, "milestone:test-gear"), "manually-owned gear milestone should not be emitted: " + statuses);
	}

	/** An outfit milestone with {@code ownedIfMin} = set size is owned only once every piece is held. */
	@Test
	void outfitMilestoneWithOwnedIfMinIsDoneOnlyWhenEnoughDistinctPiecesAreHeld()
	{
		KnowledgeBase kb = new KbBuilder()
