		currentTask.bit = bit;
		return this;
	}

	KnowledgeBase build()
	{
		List<QuestEntry> quests = new ArrayList<>();
		for (QuestSpec s : questSpecs)
		{
			quests.add(new QuestEntry(s.id, s.name, s.wikiTitle != null ? s.wikiTitle : s.name, List.copyOf(s.skills), List.copyOf(s.prereqs),
				List.copyOf(s.prereqsStarted), List.copyOf(s.prereqNotes), List.copyOf(s.items), 1, "test", s.questPointsRequired,
				s.kudosRequired, s.combatLevelRequired, s.rewardXp, s.lamps));
		}

		List<DiaryEntry> diaries = new ArrayList<>(legacyDiaries);
		for (DiarySpec d : diarySpecs)
		{
			List<DiaryTask> tasks = new ArrayList<>();
			for (TaskSpec t : d.tasks)
			{
				TaskCompletion completion = new TaskCompletion(t.varp, t.bit, null, null);
				tasks.add(new DiaryTask(t.ordinal, t.text, List.copyOf(t.skills), List.copyOf(t.quests), List.copyOf(t.items),
					List.copyOf(t.notes), completion, t.combatLevelRequired));
			}
			diaries.add(new DiaryEntry(d.tier, 0, tasks));
		}

		List<MilestoneEntry> milestones = new ArrayList<>();
		for (MilestoneSpec m : milestoneSpecs)
		{
			List<DiaryRef> diaryRefs = new ArrayList<>();
			for (DiaryTier tier : m.diaries)
			{
				diaryRefs.add(new DiaryRef(tier));
			}
			RecommendedProfile recommended = m.recommendedSkills.isEmpty() && m.recommendedCombatLevel == null
				&& m.recommendedGear.isEmpty() && m.recommendedPrayers.isEmpty()
				? null
				: new RecommendedProfile(List.copyOf(m.recommendedSkills), m.recommendedCombatLevel,
					List.copyOf(m.recommendedGear), List.copyOf(m.recommendedPrayers));
			milestones.add(new MilestoneEntry(m.id, m.category, m.subcategory, m.name, m.name, m.priority, "test", List.copyOf(m.unlocks),
				List.copyOf(m.skills), List.copyOf(m.quests), diaryRefs, null, null, List.copyOf(m.items), List.copyOf(m.ownedIf),
				m.gearTier, List.of(), m.stage, recommended, m.obtainedFrom, m.ownedIfMin, m.speedsUp,
				m.prerequisite, List.copyOf(m.notes), null, null, null, List.copyOf(m.bossRewards)));
		}

		Map<Integer, String> materialNames = new LinkedHashMap<>();
		for (MaterialSpec s : materialSpecs)
		{
			if (s.id != null)
			{
				materialNames.put(s.id, s.name);
			}
		}

		List<MethodEntry> methods = new ArrayList<>();
		for (MethodSpec m : methodSpecs)
		{
			List<ItemQuantity> materials = toItemQuantities(m.materials, materialNames);
			List<ItemQuantity> outputs = toItemQuantities(m.outputs, materialNames);
			methods.add(new MethodEntry(m.skill, m.name, m.name, m.levelReq, m.xpPerAction, materials, outputs, List.copyOf(m.types),
				true, false, null, m.intermediate, true));
		}

		List<MaterialEntry> materials = new ArrayList<>();
		for (MaterialSpec s : materialSpecs)
		{
			// generic exactly when there is no id - the kb-build invariant materials.json is checked against.
			materials.add(new MaterialEntry(s.name, s.id, s.id == null, WikiUrls.forTitle(s.name), List.copyOf(s.sources)));
		}

		List<GatheringPlan> gatheringPlans = new ArrayList<>();
		for (GatheringPlanSpec s : gatheringPlanSpecs)
		{
			GatheringRequires requires = new GatheringRequires(List.copyOf(s.skills), null, List.of(), List.of(), null);
			List<GatheringStep> steps = s.steps.isEmpty()
				? List.of(new GatheringStep("Go gather " + s.item + ".", NO_REQUIRES))
				: List.copyOf(s.steps);
			gatheringPlans.add(new GatheringPlan(s.item, s.id, "Gather " + s.item, requires, null, steps, List.of(), WikiUrls.forTitle(s.item)));
		}

		return KnowledgeBase.of("test", "test", quests, diaries, milestones, priorityOverrides, priorityReasons, methods, materials,
			gatheringPlans);
	}

	private static List<ItemQuantity> toItemQuantities(List<ItemQtyRef> refs, Map<Integer, String> materialNames)
	{
		List<ItemQuantity> result = new ArrayList<>();
		for (ItemQtyRef r : refs)
		{
			result.add(new ItemQuantity(materialNames.getOrDefault(r.id, "item " + r.id), r.id, r.quantity));
		}
		return result;
	}

	private static final class QuestSpec
	{
