import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import net.runelite.api.Experience;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * The bundled {@link KnowledgeBase} on a near-maxed account must not
 * exceed the engine's 1s budget, and the Herblore 61-&gt;70 route from a realistic bank
 * must cover some of the gap using the bank's Ranarr weed.
 */
class PerfTest
{
	private static final int RANARR_WEED_ID = 257;
	private static final int VIAL_OF_WATER_ID = 227;
	private static final int SNAPE_GRASS_ID = 231;

	@Test
	void engineAndNextStepStayUnderOneSecondOnAMaxedAccountAndTheHerbloreRouteUsesRanarr()
	{
		KnowledgeBase kb = KnowledgeBase.load(new Gson());
		GapEngine gapEngine = new GapEngine(new BoostTable());
		NextStepPicker picker = new NextStepPicker();
		Snapshot snapshot = maxedSnapshotWithHerbloreSixtyOne();

		// Warm up (JIT, class loading) - only the second run is measured.
		List<GoalStatus> warmStatuses = gapEngine.evaluate(snapshot, kb);
		picker.next(songOfTheElves(warmStatuses), snapshot, kb);

		long start = System.nanoTime();
		List<GoalStatus> statuses = gapEngine.evaluate(snapshot, kb);
		NextStep step = picker.next(songOfTheElves(statuses), snapshot, kb);
		long elapsedMs = (System.nanoTime() - start) / 1_000_000;

		assertTrue(elapsedMs < 1000, "GapEngine.evaluate + NextStepPicker.next took " + elapsedMs + "ms, budget is 1000ms");
		System.out.println("PerfTest: GapEngine.evaluate + NextStepPicker.next took " + elapsedMs + "ms (next step type: " + step.getType() + ")");

		Route route = RoutePlanner.route(Skill.HERBLORE, Experience.getXpForLevel(61), Experience.getXpForLevel(70), bankAll(snapshot), kb);

		System.out.println("PerfTest: Herblore 61->70 route from bank (412 Ranarr weed, 1200 Vial of water, 14 Snape grass):");
		for (RouteStep routeStep : route.getSteps())
		{
			System.out.println("  " + routeStep.getMethod().getName() + " x" + routeStep.getCount()
				+ " (level " + routeStep.getFromLevel() + " -> " + routeStep.getToLevel() + ", " + routeStep.getXpGained() + " xp)");
		}
		System.out.println("  uncoveredXp=" + route.getUncoveredXp() + " finalXp=" + route.getFinalXp());

		assertFalse(route.getSteps().isEmpty(), "expected at least one route step from the bank");
		boolean usesRanarr = route.getSteps().stream().anyMatch(s -> s.getMaterialsUsed().containsKey(RANARR_WEED_ID))
			|| route.getSteps().stream().flatMap(s -> s.getCrafts().stream()).anyMatch(s -> s.getMaterialsUsed().containsKey(RANARR_WEED_ID));
		assertTrue(usesRanarr, "expected the route to use some of the bank's Ranarr weed (id " + RANARR_WEED_ID + ")");
	}

	/**
	 * a fresh account focused on Song of the Elves has 8 skill gaps (Agility, Construction,
	 * Farming, Herblore, Hunter, Mining, Smithing, Woodcutting all req level 70) - {@link Engine#run}
	 * must compute a {@link SkillPlan} (route + shortfall) for every one of them, once, and still
	 * stay under the same 1s budget as the rest of the engine.
	 */
	@Test
	void focusedSongOfTheElvesWithEightSkillGapsStaysUnderOneSecondBudget()
	{
		KnowledgeBase kb = KnowledgeBase.load(new Gson());
		Engine engine = new Engine(new BoostTable());
		Snapshot snapshot = new SnapshotBuilder().build();
		AccountData data = focusOn("quest:" + Quest.SONG_OF_THE_ELVES.getId());

		// Warm up (JIT, class loading) - only the second run is measured.
		engine.run(snapshot, kb, data, Instant.now());

		long start = System.nanoTime();
		Advice advice = engine.run(snapshot, kb, data, Instant.now());
		long elapsedMs = (System.nanoTime() - start) / 1_000_000;

		assertTrue(elapsedMs < 1000, "Engine.run (focused Song of the Elves) took " + elapsedMs + "ms, budget is 1000ms");
		System.out.println("PerfTest: Engine.run with a focused Song of the Elves (8 skill gaps) took " + elapsedMs + "ms");

		FocusDetail focus = advice.getFocus();
		assertNotNull(focus, "expected a focus detail for the focused Song of the Elves goal");
		assertEquals(8, focus.getSkillPlans().size(), "expected one SkillPlan per Song of the Elves skill requirement");
	}

	private static AccountData focusOn(String goalId)
	{
		return new AccountData(new HashMap<>(), null, new HashMap<>(), new HashSet<>(), new ArrayList<>(), goalId, new HashSet<>());
	}

	private static GoalStatus songOfTheElves(List<GoalStatus> statuses)
	{
		String id = "quest:" + Quest.SONG_OF_THE_ELVES.getId();
		return statuses.stream().filter(s -> s.getGoal().getId().equals(id)).findFirst()
			.orElseThrow(() -> new AssertionError("no GoalStatus for Song of the Elves"));
	}

	private static Snapshot maxedSnapshotWithHerbloreSixtyOne()
	{
		SnapshotBuilder builder = new SnapshotBuilder();
		for (Skill skill : Skill.values())
		{
			builder.skill(skill, 99);
		}
		builder.skill(Skill.HERBLORE, 61);
		// The bank includes Ranarr weed, Vials of water, and Snape grass. Farming seeds have no
		// materials.json entry in the bundled kb (grown herbs aren't modelled as a farming seed
		// material there). Snape grass is the bundled Prayer potion(3) recipe's second
		// ingredient.
		builder.bankItem(RANARR_WEED_ID, "Ranarr weed", 412);
		builder.bankItem(VIAL_OF_WATER_ID, "Vial of water", 1200);
		builder.bankItem(SNAPE_GRASS_ID, "Snape grass", 14);
		return builder.build();
	}

	private static Map<Integer, Integer> bankAll(Snapshot snapshot)
	{
		Map<Integer, Integer> result = new HashMap<>(snapshot.getBank());
		snapshot.getInventory().forEach((id, qty) -> result.merge(id, qty, Integer::sum));
		snapshot.getEquipment().forEach((id, qty) -> result.merge(id, qty, Integer::sum));
		return result;
	}
}

package com.signpost.engine;

import com.signpost.snapshot.AccountType;
import com.signpost.snapshot.DiaryTier;
import com.signpost.snapshot.SkillState;
import com.signpost.snapshot.Snapshot;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Experience;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/**
 * Fluent builder for a {@link Snapshot} fixture. Defaults: {@link AccountType#NORMAL}, every
 * skill level 1 / 0 xp, every quest {@link QuestState#NOT_STARTED}, bank known and empty, every
 * diary tier incomplete, 0 quest points, 0 kudos. Shared by every engine test so fixtures aren't
 * hand-rolled per test.
 */
final class SnapshotBuilder
{
	private long accountHash = 1L;
	private AccountType accountType = AccountType.NORMAL;
	private final Map<Skill, SkillState> skills = new EnumMap<>(Skill.class);
	private final Map<Quest, QuestState> quests = new EnumMap<>(Quest.class);
	private final Map<Integer, Integer> bank = new HashMap<>();
	private final Map<Integer, Integer> inventory = new HashMap<>();
	private final Map<Integer, Integer> equipment = new HashMap<>();
	private final Map<Integer, String> itemNames = new HashMap<>();
	private final Map<DiaryTier, Boolean> diaryTiers = new EnumMap<>(DiaryTier.class);
	private final Map<Integer, Integer> diaryVarps = new HashMap<>();
	private final Map<Integer, Integer> karamjaVarbits = new HashMap<>();
	private final Map<Integer, Integer> diaryCountVarbits = new HashMap<>();
	private final Map<Integer, Boolean> combatAchievementTiers = new HashMap<>();
	private final Map<Integer, Integer> groupStorage = new HashMap<>();
	private boolean bankKnown = true;
	private boolean groupStorageKnown;
	private boolean groupStorageEnabled = true;
	private int questPoints;
	private int kudos;

	SnapshotBuilder()
	{
		for (Skill skill : Skill.values())
		{
			skills.put(skill, new SkillState(1, 0));
		}
		for (Quest quest : Quest.values())
		{
			quests.put(quest, QuestState.NOT_STARTED);
		}
		for (DiaryTier tier : DiaryTier.values())
		{
			diaryTiers.put(tier, false);
		}
	}

	SnapshotBuilder accountType(AccountType type)
	{
		this.accountType = type;
		return this;
	}

	SnapshotBuilder iron()
	{
		return accountType(AccountType.IRONMAN);
	}

	SnapshotBuilder skill(Skill skill, int level)
	{
		skills.put(skill, new SkillState(level, Experience.getXpForLevel(level)));
		return this;
	}

	SnapshotBuilder xp(Skill skill, long xp)
	{
		skills.put(skill, new SkillState(Experience.getLevelForXp((int) xp), (int) xp));
		return this;
	}

	SnapshotBuilder quest(Quest quest, QuestState state)
	{
		quests.put(quest, state);
		return this;
	}

	SnapshotBuilder bankItem(int id, String name, int qty)
	{
		bank.merge(id, qty, Integer::sum);
		itemNames.put(id, name);
		return this;
	}

	SnapshotBuilder inventoryItem(int id, String name, int qty)
	{
		inventory.merge(id, qty, Integer::sum);
		itemNames.put(id, name);
		return this;
	}

	SnapshotBuilder equipmentItem(int id, String name, int qty)
	{
		equipment.merge(id, qty, Integer::sum);
		itemNames.put(id, name);
		return this;
	}

	/** An item in the group ironman shared storage; marks the storage as seen. */
	SnapshotBuilder groupStorageItem(int id, String name, int qty)
	{
		groupStorage.merge(id, qty, Integer::sum);
		itemNames.put(id, name);
		groupStorageKnown = true;
		return this;
	}

	SnapshotBuilder groupStorageKnown()
	{
		groupStorageKnown = true;
		return this;
	}

	/** The "Count group storage" toggle is off. */
	SnapshotBuilder groupStorageOff()
	{
		groupStorageEnabled = false;
		return this;
	}

	SnapshotBuilder bankUnknown()
	{
		bankKnown = false;
		return this;
	}

	SnapshotBuilder diaryTier(DiaryTier tier, boolean complete)
	{
		diaryTiers.put(tier, complete);
		return this;
	}

	SnapshotBuilder diaryVarp(int varp, int value)
	{
		diaryVarps.put(varp, value);
		return this;
	}

	SnapshotBuilder karamjaVarbit(int id, int value)
	{
		karamjaVarbits.put(id, value);
		return this;
	}

	SnapshotBuilder diaryCountVarbit(int id, int value)
	{
		diaryCountVarbits.put(id, value);
		return this;
	}

	SnapshotBuilder combatAchievementTier(int varbit, boolean done)
	{
		combatAchievementTiers.put(varbit, done);
		return this;
	}

	SnapshotBuilder questPoints(int n)
	{
		this.questPoints = n;
		return this;
	}

	SnapshotBuilder kudos(int n)
	{
		this.kudos = n;
		return this;
	}

	Snapshot build()
	{
		return Snapshot.builder()
			.accountHash(accountHash)
			.accountType(accountType)
			.skills(skills)
			.quests(quests)
			.bank(bank)
			.inventory(inventory)
			.equipment(equipment)
			.itemNames(itemNames)
			.diaryTiers(diaryTiers)
			.diaryVarps(diaryVarps)
			.karamjaVarbits(karamjaVarbits)
			.diaryCountVarbits(diaryCountVarbits)
			.combatAchievementTiers(combatAchievementTiers)
			.bankKnown(bankKnown)
			.groupStorage(groupStorage)
			.groupStorageKnown(groupStorageKnown)
			.groupStorageEnabled(groupStorageEnabled)
			.questPoints(questPoints)
			.kudos(kudos)
			.build();
	}
}

package com.signpost;

import java.time.Duration;
import java.time.Instant;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** The per-skill xp sample ring and when its rate counts as ready. */
class XpRateTrackerTest
{
	private final Instant t0 = Instant.parse("2026-09-08T12:00:00Z");
	private final XpRateTracker tracker = new XpRateTracker();

	@Test
	void rateNeedsFiveMinutesOfTrainingAndTwoSamplesWithXpGained()
	{
		// the login baseline is not training time: the window starts at the first gain (t=3)
		tracker.record(Skill.HERBLORE, 100_000, t0);
		tracker.record(Skill.HERBLORE, 103_000, t0.plus(Duration.ofMinutes(3)));
		tracker.record(Skill.HERBLORE, 106_000, t0.plus(Duration.ofMinutes(6)));
		assertFalse(tracker.rates(t0.plus(Duration.ofMinutes(6))).containsKey(Skill.HERBLORE), "3 min of training is not ready");

		tracker.record(Skill.MINING, 500, t0);
		tracker.record(Skill.MINING, 500, t0.plus(Duration.ofMinutes(6)));
		assertFalse(tracker.rates(t0.plus(Duration.ofMinutes(6))).containsKey(Skill.MINING), "no xp gained: not ready");

		tracker.record(Skill.HERBLORE, 108_000, t0.plus(Duration.ofMinutes(8)));
		Map<Skill, Long> rates = tracker.rates(t0.plus(Duration.ofMinutes(8)));
		assertEquals(60_000L, rates.get(Skill.HERBLORE), "5,000 xp over the 5 training minutes is 60k/h");
	}

	@Test
	void samplesOlderThanThirtyMinutesFallOutOfTheWindow()
	{
		tracker.record(Skill.MINING, 0, t0);
		tracker.record(Skill.MINING, 500, t0.plus(Duration.ofMinutes(5)));
		tracker.record(Skill.MINING, 1_000, t0.plus(Duration.ofMinutes(10)));
		tracker.record(Skill.MINING, 2_000, t0.plus(Duration.ofMinutes(20)));
		assertEquals(6_000L, tracker.rates(t0.plus(Duration.ofMinutes(20))).get(Skill.MINING), "1,500 xp over 15 training minutes");

		// 36 min later only the t=10 and t=20 samples remain, and the older one is now the baseline: no rate
		assertTrue(tracker.rates(t0.plus(Duration.ofMinutes(36))).isEmpty());
		// 55 min later the window is empty
		assertTrue(tracker.rates(t0.plus(Duration.ofMinutes(55))).isEmpty());
	}

	@Test
	void leadingIdleSamplesDoNotDiluteTheRate()
	{
		// login baseline, 20 idle minutes, then 5 minutes of training: the rate is the training span only
		tracker.record(Skill.HERBLORE, 100_000, t0);
		tracker.record(Skill.HERBLORE, 100_000, t0.plus(Duration.ofMinutes(10)));
		assertFalse(tracker.record(Skill.HERBLORE, 101_000, t0.plus(Duration.ofMinutes(20))), "first gain: not ready yet");
		assertFalse(tracker.record(Skill.HERBLORE, 103_000, t0.plus(Duration.ofMinutes(23))), "3 min of training: not ready yet");
		assertTrue(tracker.record(Skill.HERBLORE, 105_000, t0.plus(Duration.ofMinutes(25))), "5 min of training: just became ready");
		assertEquals(48_000L, tracker.rates(t0.plus(Duration.ofMinutes(25))).get(Skill.HERBLORE), "4,000 xp over the 5 training minutes");
		assertFalse(tracker.record(Skill.HERBLORE, 106_000, t0.plus(Duration.ofMinutes(26))), "already ready: no second flip");
	}

	@Test
	void clearForgetsEverySkill()
	{
		tracker.record(Skill.MINING, 0, t0);
		tracker.record(Skill.MINING, 100, t0.plus(Duration.ofMinutes(1)));
		tracker.record(Skill.MINING, 2_000, t0.plus(Duration.ofMinutes(6)));
		assertFalse(tracker.rates(t0.plus(Duration.ofMinutes(6))).isEmpty());
		tracker.clear();
		assertTrue(tracker.rates(t0.plus(Duration.ofMinutes(6))).isEmpty());
	}
}

package com.signpost.store;

import com.signpost.snapshot.CachedBank;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * The per-account data persisted by {@link AccountStore}: the last-known bank plus user prefs
 * (snoozes, ignores, pins, focus goal) that survive between client sessions. {@code version} is
 * the file format: 1 (implicit, no field) predates group storage; 2 adds
 * {@code groupStorage}/{@code groupStorageAsOf}, the group ironman shared storage cached like the bank.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class AccountData
{
	public static final int CURRENT_VERSION = 2;

	private Map<Integer, Integer> bank;
	private Instant bankAsOf;
	private Map<String, Snooze> snoozes;
	private Set<String> ignores;
	private List<String> pins;
	private String focusGoalId;
	/** Goal ids marked "owned" by hand: the account has it but it lives somewhere the client can't see (a house cape rack; group storage only while "Count group storage" is off). */
	private Set<String> ownedManually;
	private Map<Integer, Integer> groupStorage;
	private Instant groupStorageAsOf;
	private int version;

	/** Version-1 shape (no group storage): kept for the many fixtures that build prefs by hand. */
	public AccountData(Map<Integer, Integer> bank, Instant bankAsOf, Map<String, Snooze> snoozes, Set<String> ignores, List<String> pins,
		String focusGoalId, Set<String> ownedManually)
	{
		this(bank, bankAsOf, snoozes, ignores, pins, focusGoalId, ownedManually, new HashMap<>(), null, CURRENT_VERSION);
	}

	public static AccountData empty()
	{
		return new AccountData(new HashMap<>(), null, new HashMap<>(), new HashSet<>(), new ArrayList<>(), null, new HashSet<>());
	}

	public CachedBank toCachedBank()
	{
		return toCached(bank, bankAsOf);
	}

	public CachedBank toCachedGroupStorage()
	{
		return toCached(groupStorage, groupStorageAsOf);
	}

	private static CachedBank toCached(Map<Integer, Integer> items, Instant asOf)
	{
		boolean known = items != null && asOf != null;
		return known ? new CachedBank(items, asOf, true) : CachedBank.unknown();
	}

	/**
	 * A snapshot independent of this instance: later mutating (or replacing) any of this
	 * instance's fields does not affect the returned copy. Used to hand a stable value to a
	 * background thread while the live instance keeps being updated on the client thread.
	 */
	public AccountData copy()
	{
		return new AccountData(
			new HashMap<>(bank),
			bankAsOf,
			new HashMap<>(snoozes),
			new HashSet<>(ignores),
			new ArrayList<>(pins),
			focusGoalId,
			new HashSet<>(ownedManually),
			new HashMap<>(groupStorage),
			groupStorageAsOf,
			version);
	}
}

