package com.signpost.snapshot;

import java.time.Instant;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import lombok.Builder;
import lombok.Value;
import net.runelite.api.Experience;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/**
 * Immutable point-in-time read of the account's state, as produced by {@link SnapshotCollector}.
 * All map fields are defensively copied and unmodifiable.
 */
@Value
public class Snapshot
{
	long accountHash;
	AccountType accountType;
	Map<Skill, SkillState> skills;
	Map<Quest, QuestState> quests;
	Map<Integer, Integer> bank;
	Map<Integer, Integer> inventory;
	Map<Integer, Integer> equipment;
	Map<Integer, Integer> runePouch;
	SlayerState slayer;
	boolean rigour;
	boolean augury;
	boolean preserve;
	Spellbook spellbook;
	Map<Integer, String> itemNames;
	Map<DiaryTier, Boolean> diaryTiers;
	Map<Integer, Integer> diaryVarps;
	Map<Integer, Integer> karamjaVarbits;
	Map<Integer, Integer> diaryCountVarbits;
	Map<Integer, Boolean> combatAchievementTiers;
	Map<String, BossProgress> bossProgress;
	boolean bankKnown;
	/** Explicitly confirmed absences for partial/offline snapshots; unobserved items otherwise remain unknown. */
	Set<Integer> confirmedAbsentItems;
	Instant bankAsOf;
	/** The group ironman shared storage, cached like the bank; empty (and not known) on any other account type or when the "Count group storage" toggle is off. */
	Map<Integer, Integer> groupStorage;
	boolean groupStorageKnown;
	Instant groupStorageAsOf;
	/** False when the "Count group storage" toggle is off - the header then says "off" rather than "not seen". */
	boolean groupStorageEnabled;
	int questPoints;
	int kudos;

	@Builder(toBuilder = true)
	private Snapshot(
		long accountHash,
		AccountType accountType,
		Map<Skill, SkillState> skills,
		Map<Quest, QuestState> quests,
		Map<Integer, Integer> bank,
		Map<Integer, Integer> inventory,
		Map<Integer, Integer> equipment,
		Map<Integer, Integer> runePouch,
		SlayerState slayer,
		boolean rigour,
		boolean augury,
		boolean preserve,
		Spellbook spellbook,
		Map<Integer, String> itemNames,
		Map<DiaryTier, Boolean> diaryTiers,
		Map<Integer, Integer> diaryVarps,
		Map<Integer, Integer> karamjaVarbits,
		Map<Integer, Integer> diaryCountVarbits,
		Map<Integer, Boolean> combatAchievementTiers,
		Map<String, BossProgress> bossProgress,
		boolean bankKnown,
		Set<Integer> confirmedAbsentItems,
		Instant bankAsOf,
		Map<Integer, Integer> groupStorage,
		boolean groupStorageKnown,
		Instant groupStorageAsOf,
		boolean groupStorageEnabled,
		int questPoints,
		int kudos)
	{
		this.accountHash = accountHash;
		this.accountType = accountType;
		this.skills = copyOf(skills);
		this.quests = copyOf(quests);
		this.bank = copyOf(bank);
		this.inventory = copyOf(inventory);
		this.equipment = copyOf(equipment);
		this.runePouch = copyOf(runePouch);
		this.slayer = slayer == null ? SlayerState.empty() : slayer;
		this.rigour = rigour;
		this.augury = augury;
		this.preserve = preserve;
		this.spellbook = spellbook == null ? Spellbook.STANDARD : spellbook;
		this.itemNames = copyOf(itemNames);
		this.diaryTiers = copyOf(diaryTiers);
		this.diaryVarps = copyOf(diaryVarps);
		this.karamjaVarbits = copyOf(karamjaVarbits);
		this.diaryCountVarbits = copyOf(diaryCountVarbits);
		this.combatAchievementTiers = copyOf(combatAchievementTiers);
		this.bossProgress = copyOf(bossProgress);
		this.bankKnown = bankKnown;
		this.confirmedAbsentItems = confirmedAbsentItems == null ? Set.of() : Set.copyOf(confirmedAbsentItems);
		this.bankAsOf = bankAsOf;
		this.groupStorage = copyOf(groupStorage);
		this.groupStorageKnown = groupStorageKnown;
		this.groupStorageAsOf = groupStorageAsOf;
		this.groupStorageEnabled = groupStorageEnabled;
		this.questPoints = questPoints;
		this.kudos = kudos;
	}

	private static <K, V> Map<K, V> copyOf(Map<K, V> map)
	{
		return map == null ? Map.of() : Collections.unmodifiableMap(new LinkedHashMap<>(map));
	}

	/**
	 * Returns a copy of this snapshot with the bank fields replaced from {@code cachedBank}.
	 */
	public Snapshot withBank(CachedBank cachedBank)
	{
		return toBuilder()
			.bank(cachedBank.getItems())
			.bankKnown(cachedBank.isKnown())
			.bankAsOf(cachedBank.getAsOf())
			.build();
	}

	/** Returns a copy of this snapshot with the group storage fields replaced from {@code cached}. */
	public Snapshot withGroupStorage(CachedBank cached)
	{
		return toBuilder()
			.groupStorage(cached.getItems())
			.groupStorageKnown(cached.isKnown())
			.groupStorageAsOf(cached.getAsOf())
			.build();
	}

	/**
	 * Combat level derived from {@link #skills}, via {@link Experience#getCombatLevel}. A skill
	 * missing from the map (e.g. an empty test snapshot) is treated as level 1.
	 */
	public int combatLevel()
	{
		return Experience.getCombatLevel(
			levelOf(Skill.ATTACK), levelOf(Skill.STRENGTH), levelOf(Skill.DEFENCE), levelOf(Skill.HITPOINTS),
			levelOf(Skill.MAGIC), levelOf(Skill.RANGED), levelOf(Skill.PRAYER));
	}

	private int levelOf(Skill skill)
	{
		SkillState state = skills.get(skill);
		return state == null ? 1 : state.getLevel();
	}
}

package com.signpost.snapshot;

public enum Spellbook
{
	STANDARD, ANCIENT, LUNAR, ARCEUUS, UNKNOWN;

	public static Spellbook fromVarbit(int value)
	{
		switch (value)
		{
			case 0: return STANDARD;
			case 1: return ANCIENT;
			case 2: return LUNAR;
			case 3: return ARCEUUS;
			default: return UNKNOWN;
		}
	}
}

package com.signpost.snapshot;

