package com.signpost.snapshot;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.GameState;
import net.runelite.api.StructComposition;
import net.runelite.api.VarbitComposition;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/** Client-thread reader. Only account-independent cache metadata survives between reads. */
@Slf4j
public final class BossProgressReader
{
	private static final int BOSS_NAMES_ENUM = 3971;
	private static final int FIRST_TIER_ENUM = 3981;
	private static final int TASK_ID = 1306;
	private static final int TASK_NAME = 1308;
	private static final int TASK_DESCRIPTION = 1309;
	private static final int TASK_BOSS = 1312;
	// These words are not contiguous varps. New tasks beyond the supported words stay unknown.
	private static final int[] TASK_WORDS = {
		VarPlayerID.CA_TASK_COMPLETED_0, VarPlayerID.CA_TASK_COMPLETED_1,
		VarPlayerID.CA_TASK_COMPLETED_2, VarPlayerID.CA_TASK_COMPLETED_3,
		VarPlayerID.CA_TASK_COMPLETED_4, VarPlayerID.CA_TASK_COMPLETED_5,
		VarPlayerID.CA_TASK_COMPLETED_6, VarPlayerID.CA_TASK_COMPLETED_7,
		VarPlayerID.CA_TASK_COMPLETED_8, VarPlayerID.CA_TASK_COMPLETED_9,
		VarPlayerID.CA_TASK_COMPLETED_10, VarPlayerID.CA_TASK_COMPLETED_11,
		VarPlayerID.CA_TASK_COMPLETED_12, VarPlayerID.CA_TASK_COMPLETED_13,
		VarPlayerID.CA_TASK_COMPLETED_14, VarPlayerID.CA_TASK_COMPLETED_15,
		VarPlayerID.CA_TASK_COMPLETED_16, VarPlayerID.CA_TASK_COMPLETED_17,
		VarPlayerID.CA_TASK_COMPLETED_18, VarPlayerID.CA_TASK_COMPLETED_19,
		VarPlayerID.CA_TASK_COMPLETED_20
	};
	private static final Map<String, List<Integer>> COLLECTIONS = collections();
	private static final Set<Integer> COLLECTION_VARBITS = collectionVarbits();
	private static final BossProgress UNKNOWN = new BossProgress(null, false, List.of());

	private boolean metadataLoaded;
	private Map<String, List<CombatAchievementTask>> tasks = Map.of();
	private Map<Integer, Integer> collectionParents = Map.of();

	public Map<String, BossProgress> read(Client client)
	{
		checkThread(client);
		Map<String, BossProgress> result = new LinkedHashMap<>();
		int[] varps = client.getVarps();
		if (client.getGameState() != GameState.LOGGED_IN || varps == null)
		{
			COLLECTIONS.keySet().forEach(id -> result.put(id, UNKNOWN));
			return Collections.unmodifiableMap(result);
		}
		loadMetadata(client);
		for (Map.Entry<String, List<Integer>> entry : COLLECTIONS.entrySet())
		{
			List<CombatAchievementTask> bossTasks = tasks.get(entry.getKey());
			boolean known = bossTasks != null;
			List<CombatAchievementTask> remaining = new ArrayList<>();
			if (known)
			{
				for (CombatAchievementTask task : bossTasks)
				{
					int word = TASK_WORDS[task.getId() / 32];
					if (word >= varps.length)
					{
						known = false;
						remaining.clear();
						break;
					}
					if ((varps[word] & (1 << (task.getId() % 32))) == 0)
					{
						remaining.add(task);
					}
				}
			}
			result.put(entry.getKey(), new BossProgress(greenLogged(client, varps, entry.getValue()), known, remaining));
		}
		return Collections.unmodifiableMap(result);
	}

	/** VarbitChanged carries either a varbit or its parent varp, depending on the update source. */
	public boolean isProgressChange(Client client, int varp, int varbit)
	{
		checkThread(client);
		if (COLLECTION_VARBITS.contains(varbit)) return true;
		if (varp < 0 && varbit >= 0 && client.getGameState() == GameState.LOGGED_IN)
		{
			VarbitComposition definition = client.getVarbit(varbit);
			if (definition != null) varp = definition.getIndex();
		}
		for (int word : TASK_WORDS)
		{
			if (word == varp) return true;
		}
		if (client.getGameState() == GameState.LOGGED_IN && client.getVarps() != null)
		{
			loadMetadata(client);
		}
		return collectionParents.containsValue(varp);
	}

	private Boolean greenLogged(Client client, int[] varps, List<Integer> varbits)
	{
		boolean complete = true;
		for (int varbit : varbits)
		{
			Integer parent = collectionParents.get(varbit);
			if (parent == null || parent >= varps.length) return null;
			int value = client.getVarbitValue(varbit);
			if (value != 0 && value != 1) return null;
			complete &= value == 1;
		}
		return complete;
	}

	private void loadMetadata(Client client)
	{
		if (metadataLoaded) return;
		metadataLoaded = true;
		Map<Integer, Integer> parents = new HashMap<>();
		for (int varbit : COLLECTION_VARBITS)
		{
			try
			{
				VarbitComposition definition = client.getVarbit(varbit);
				if (definition == null || definition.getIndex() < 0
					|| definition.getLeastSignificantBit() < 0 || definition.getMostSignificantBit() > 31
					|| definition.getLeastSignificantBit() != definition.getMostSignificantBit())
				{
					throw new IllegalStateException("Missing or invalid boolean varbit " + varbit);
				}
				parents.put(varbit, definition.getIndex());
			}
			catch (RuntimeException exception)
			{
				log.warn("Cannot read boss collection metadata for varbit {}", varbit, exception);
			}
		}
		collectionParents = Map.copyOf(parents);
		try
		{
			tasks = loadTasks(client);
		}
		catch (RuntimeException exception)
		{
			// Never publish a partial enumeration as a complete list of remaining tasks.
			log.warn("Cannot read complete combat achievement metadata; boss tasks remain unknown", exception);
		}
	}

	private static Map<String, List<CombatAchievementTask>> loadTasks(Client client)
	{
		EnumComposition bossEnum = client.getEnum(BOSS_NAMES_ENUM);
		if (bossEnum == null || bossEnum.getKeys() == null || bossEnum.getStringVals() == null
			|| bossEnum.size() == 0 || bossEnum.getKeys().length != bossEnum.size()
			|| bossEnum.getStringVals().length != bossEnum.size())
		{
			throw new IllegalStateException("Missing or incomplete boss-name enum " + BOSS_NAMES_ENUM);
		}
		Map<Integer, String> bossNames = new HashMap<>();
		for (int i = 0; i < bossEnum.size(); i++)
		{
			String name = bossEnum.getStringVals()[i];
			if (!validText(name) || bossNames.put(bossEnum.getKeys()[i], name) != null)
			{
				throw new IllegalStateException("Invalid boss-name enum entry " + i);
			}
		}
		Map<String, List<CombatAchievementTask>> result = new LinkedHashMap<>();
		Set<Integer> taskIds = new HashSet<>();
		Set<String> mappedNames = new HashSet<>();
		for (int tier = 1; tier <= 6; tier++)
		{
			int enumId = FIRST_TIER_ENUM + tier - 1;
			EnumComposition tierEnum = client.getEnum(enumId);
			if (tierEnum == null || tierEnum.getIntVals() == null || tierEnum.size() == 0
				|| tierEnum.getIntVals().length != tierEnum.size())
			{
				throw new IllegalStateException("Missing or incomplete combat tier enum " + enumId);
			}
			for (int structId : tierEnum.getIntVals())
			{
				StructComposition struct = client.getStructComposition(structId);
				if (struct == null) throw new IllegalStateException("Missing combat task struct " + structId);
				int id = struct.getIntValue(TASK_ID);
				String name = struct.getStringValue(TASK_NAME);
				String description = struct.getStringValue(TASK_DESCRIPTION);
				String bossName = bossNames.get(struct.getIntValue(TASK_BOSS));
				if (id < 0 || id / 32 >= TASK_WORDS.length || !taskIds.add(id)
					|| !validText(name) || !validText(description) || bossName == null)
				{
					throw new IllegalStateException("Invalid combat task metadata or unsupported completion word: struct " + structId);
				}
				String boss = modeledBoss(bossName);
				if (boss != null)
				{
					mappedNames.add(normalize(bossName));
					result.computeIfAbsent(boss, ignored -> new ArrayList<>())
						.add(new CombatAchievementTask(id, name, description, tier));
				}
			}
		}
		// The aggregate must not silently become "complete" if a component boss disappeared.
		if (!mappedNames.containsAll(Set.of("general graardor", "commander zilyana", "kree'arra", "k'ril tsutsaroth")))
		{
			result.remove("boss:god-wars-dungeon");
		}
		if (!mappedNames.contains("dagannoth kings")
			&& !mappedNames.containsAll(Set.of("dagannoth rex", "dagannoth prime", "dagannoth supreme")))
		{
			result.remove("boss:dagannoth-kings");
		}
		for (String boss : COLLECTIONS.keySet())
		{
			if (!result.containsKey(boss)) log.warn("No complete combat achievement metadata mapped for {}", boss);
		}
		result.replaceAll((boss, list) -> List.copyOf(list));
		return Collections.unmodifiableMap(result);
	}

	private static boolean validText(String text)
	{
		return text != null && !text.isBlank() && !text.equalsIgnoreCase("null");
	}

	private static String normalize(String name)
	{
		return name.toLowerCase(Locale.ROOT).replace('\u2019', '\'').trim();
	}

	private static String modeledBoss(String name)
	{
		String normalized = normalize(name);
		if (raidName(normalized, "chambers of xeric")) return "boss:chambers-of-xeric";
		if (raidName(normalized, "theatre of blood")) return "boss:theatre-of-blood";
		if (raidName(normalized, "tombs of amascut")) return "boss:tombs-of-amascut";
		switch (normalized)
		{
			case "barrows": return "boss:barrows";
			case "perilous moons":
			case "moons of peril": return "boss:moons-of-peril";
			case "zulrah": return "boss:zulrah";
			case "vorkath": return "boss:vorkath";
			case "general graardor":
			case "commander zilyana":
			case "kree'arra":
			case "k'ril tsutsaroth": return "boss:god-wars-dungeon";
			case "dagannoth kings":
			case "dagannoth rex":
			case "dagannoth prime":
			case "dagannoth supreme": return "boss:dagannoth-kings";
			case "the gauntlet":
			case "gauntlet": return "boss:gauntlet";
			case "the corrupted gauntlet":
			case "corrupted gauntlet": return "boss:corrupted-gauntlet";
			case "phantom muspah": return "boss:phantom-muspah";
			case "nex": return "boss:nex";
			case "duke sucellus": return "boss:duke-sucellus";
			case "the whisperer":
			case "whisperer": return "boss:the-whisperer";
			case "vardorvis": return "boss:vardorvis";
			case "the leviathan":
			case "leviathan": return "boss:the-leviathan";
			case "zalcano": return "boss:zalcano";
			default: return null;
		}
	}

	private static boolean raidName(String name, String base)
	{
		return name.equals(base) || name.startsWith(base + ":") || name.startsWith(base + " (");
	}

	private static Map<String, List<Integer>> collections()
	{
		Map<String, List<Integer>> result = new LinkedHashMap<>();
		result.put("boss:barrows", List.of(VarbitID.COLLECTION_BOSSES_BARROWS_COMPLETED));
		result.put("boss:moons-of-peril", List.of(VarbitID.COLLECTION_BOSSES_PERILOUS_MOONS_COMPLETED));
		result.put("boss:zulrah", List.of(VarbitID.COLLECTION_BOSSES_ZULRAH_COMPLETED));
		result.put("boss:vorkath", List.of(VarbitID.COLLECTION_BOSSES_VORKATH_COMPLETED));
		result.put("boss:god-wars-dungeon", List.of(VarbitID.COLLECTION_BOSSES_BANDOS_COMPLETED,
			VarbitID.COLLECTION_BOSSES_SARADOMIN_COMPLETED, VarbitID.COLLECTION_BOSSES_ARMADYL_COMPLETED,
			VarbitID.COLLECTION_BOSSES_ZAMORAK_COMPLETED));
		result.put("boss:dagannoth-kings", List.of(VarbitID.COLLECTION_BOSSES_DAGANNOTH_COMPLETED));
		result.put("boss:gauntlet", List.of(VarbitID.COLLECTION_BOSSES_GAUNTLET_COMPLETED));
		result.put("boss:corrupted-gauntlet", List.of(VarbitID.COLLECTION_BOSSES_GAUNTLET_COMPLETED));
		result.put("boss:phantom-muspah", List.of(VarbitID.COLLECTION_BOSSES_MUSPAH_COMPLETED));
		result.put("boss:nex", List.of(VarbitID.COLLECTION_BOSSES_NEX_COMPLETED));
		result.put("boss:duke-sucellus", List.of(VarbitID.COLLECTION_BOSSES_DUKE_COMPLETED));
		result.put("boss:the-whisperer", List.of(VarbitID.COLLECTION_BOSSES_WHISPERER_COMPLETED));
		result.put("boss:vardorvis", List.of(VarbitID.COLLECTION_BOSSES_VARDORVIS_COMPLETED));
		result.put("boss:the-leviathan", List.of(VarbitID.COLLECTION_BOSSES_LEVIATHAN_COMPLETED));
		result.put("boss:zalcano", List.of(VarbitID.COLLECTION_BOSSES_ZALCANO_COMPLETED));
		result.put("boss:chambers-of-xeric", List.of(VarbitID.COLLECTION_RAIDS_COX_COMPLETED));
		result.put("boss:theatre-of-blood", List.of(VarbitID.COLLECTION_RAIDS_TOB_COMPLETED));
		result.put("boss:tombs-of-amascut", List.of(VarbitID.COLLECTION_RAIDS_TOA_COMPLETED));
		return Collections.unmodifiableMap(result);
	}

	private static Set<Integer> collectionVarbits()
	{
		Set<Integer> result = new HashSet<>();
		COLLECTIONS.values().forEach(result::addAll);
		return Set.copyOf(result);
	}

	private static void checkThread(Client client)
	{
		if (!client.isClientThread()) throw new IllegalStateException("BossProgressReader must run on the client thread");
	}
}

package com.signpost.engine;

import com.signpost.engine.model.DiaryTaskGap;
import com.signpost.engine.model.Gap;
import com.signpost.engine.model.GoalCategory;
import com.signpost.engine.model.GoalRef;
import com.signpost.engine.model.GoalStatus;
import com.signpost.engine.model.PrerequisiteGap;
import com.signpost.engine.model.QuestPrereqGap;
import com.signpost.engine.model.RankedGoal;
import com.signpost.kb.RewardValue;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * Orders {@link GoalStatus}es into {@link RankedGoal}s: pinned goals first (in
 * pin order), then goals that are ready right now, then everything else by
 * {@code priority × closeness} descending. Pure: no {@link net.runelite.api.Client}, no I/O
 * (global constraint: engine code is pure).
 */
public final class Ranker
{
	private static final double XP_SCALE = 250_000.0;
	/** A goal more than one stage above the account's is scored down, not excluded. */
	private static final double LATER_PENALTY = 0.05;
	/** Each distinct goal a quest unblocks adds this to its priority, up to {@link #FAN_OUT_CAP}. */
	private static final double FAN_OUT_PER_DEPENDENT = 0.5;
	private static final double FAN_OUT_CAP = 2.0;

	private static Comparator<RankedGoal> byScoreThenProgression(int accountStage)
	{
		return Comparator.comparingDouble(RankedGoal::getScore).reversed()
			// Uncovered targets never outrank the parent they serve at the same score.
			.thenComparing((RankedGoal r) -> r.getStatus().isUncoveredTarget() ? 1 : 0)
			// Prefer the account's current progression stage, not the oldest accessible content.
			.thenComparingInt(r -> Math.abs(accountStage - r.getStatus().getGoal().getStage()))
			.thenComparing((RankedGoal r) -> r.getStatus().getGoal().getPriority(), Comparator.reverseOrder())
			.thenComparing(r -> r.getStatus().getGoal().getName())
			.thenComparing(r -> r.getStatus().getGoal().getId());
	}

	private static int progressionGroup(RankedGoal ranked, int accountStage)
	{
		GoalStatus status = ranked.getStatus();
		return status.isBankCovered() || status.getGoal().getStage() <= accountStage ? 0 : 1;
	}

	/**
	 * As {@link #rank(List, Set, List, int)} with {@code accountStage} high enough that no goal is
	 * ever "later" (stage 4 is the max) - kept for callers that don't have a stage yet.
	 */
	public List<RankedGoal> rank(List<GoalStatus> statuses, Set<String> hidden, List<String> pins)
	{
		return rank(statuses, hidden, pins, 4);
	}

	/**
	 * {@code accountStage} is the account's estimated progression stage
	 * ({@link StageEstimator}). A non-pinned goal with {@code stage > accountStage + 1} has its
	 * score multiplied by {@link #LATER_PENALTY} and {@link RankedGoal#isLater()} set - a pinned
	 * goal is never marked later, since a pin is an explicit user override.
	 */
	public List<RankedGoal> rank(List<GoalStatus> statuses, Set<String> hidden, List<String> pins, int accountStage)
	{
		return rank(statuses, hidden, pins, accountStage, Map.of());
	}

	/**
	 * A quest's {@code dependents} is the number of distinct non-hidden goals whose
	 * gap tree contains it; its priority is raised by {@code min(2, dependents x 0.5)} before the
	 * closeness multiplier, and the resulting {@link RankedGoal#getUnblocks()} names those goals in
	 * rank order. {@code extraDependents} (quest goal id to goal ids) adds dependents the gap trees
	 * don't show - the goals a ready quest's reward xp covers a skill target for.
	 */
	public List<RankedGoal> rank(List<GoalStatus> statuses, Set<String> hidden, List<String> pins, int accountStage,
		Map<String, Set<String>> extraDependents)
	{
		Map<String, GoalStatus> byId = new LinkedHashMap<>();
		for (GoalStatus status : statuses)
		{
			if (!hidden.contains(status.getGoal().getId()))
			{
				byId.put(status.getGoal().getId(), status);
			}
		}
		Map<String, Set<String>> dependents = dependents(byId, extraDependents);

		List<RankedGoal> pinned = new ArrayList<>();
		Set<String> used = new LinkedHashSet<>();
		for (String id : pins)
		{
			GoalStatus status = byId.get(id);
			if (status == null || !used.add(id))
			{
				continue;
			}
			pinned.add(new RankedGoal(status, score(status, dependentCount(dependents, id)), true, false));
		}

		List<RankedGoal> ready = new ArrayList<>();
		List<RankedGoal> rest = new ArrayList<>();
		List<RankedGoal> later = new ArrayList<>();
		for (GoalStatus status : byId.values())
		{
			if (used.contains(status.getGoal().getId()))
			{
				continue;
			}
			boolean isLater = status.getGoal().getStage() > accountStage + 1;
			double base = score(status, dependentCount(dependents, status.getGoal().getId()));
			double score = isLater ? base * LATER_PENALTY : base;
			RankedGoal ranked = new RankedGoal(status, score, false, isLater);
			// A later goal never enters the ready tier, regardless of its own gaps: readiness within
			// the account's own stage range must always outrank a stage-inappropriate goal.
			(isLater ? later : (isReadyNow(status) ? ready : rest)).add(ranked);
		}
		// Ready primary progression comes first; mere readiness must not promote a situational grind.
		// Within the remaining tiers, score the actual gain rather than the age of its source.
		Comparator<RankedGoal> byScore = byScoreThenProgression(accountStage);
		Comparator<RankedGoal> byStageThenScore = Comparator
			.<RankedGoal>comparingInt(r -> progressionGroup(r, accountStage))
			.thenComparing(byScore);
		ready.sort(byStageThenScore);
		rest.sort(byStageThenScore);
		later.sort(byScore);

		List<RankedGoal> result = new ArrayList<>(pinned.size() + ready.size() + rest.size() + later.size());
		result.addAll(pinned);
		result.addAll(ready);
		result.addAll(rest);
		result.addAll(later);
		return withUnblocks(prerequisiteFirst(result), dependents, byId);
	}

	/**
	 * Stable topological ordering, choosing the earliest otherwise-ranked goal whenever
	 * its visible prerequisites have been emitted. Scores are unchanged; a pairwise comparator
	 * cannot express dependency order transitively. Pins remain explicit overrides in pin order,
	 * and hidden/completed prerequisites are never reinserted into the visible list.
	 */
	private static List<RankedGoal> prerequisiteFirst(List<RankedGoal> ranked)
	{
		Map<String, Integer> index = new LinkedHashMap<>();
		for (int i = 0; i < ranked.size(); i++)
		{
			index.put(ranked.get(i).getStatus().getGoal().getId(), i);
		}
		int[] unmet = new int[ranked.size()];
		Map<Integer, List<Integer>> dependants = new LinkedHashMap<>();
		for (int i = 0; i < ranked.size(); i++)
		{
			RankedGoal goal = ranked.get(i);
			if (goal.isPinned())
			{
				continue;
			}
			for (Gap gap : goal.getStatus().getGaps())
			{
				if (gap instanceof PrerequisiteGap)
				{
					Integer prerequisite = index.get(((PrerequisiteGap) gap).getGoalId());
					if (prerequisite != null)
					{
						unmet[i]++;
						dependants.computeIfAbsent(prerequisite, ignored -> new ArrayList<>()).add(i);
					}
				}
			}
		}
		PriorityQueue<Integer> available = new PriorityQueue<>();
		for (int i = 0; i < ranked.size(); i++)
		{
			if (unmet[i] == 0)
			{
				available.add(i);
			}
		}
		List<RankedGoal> ordered = new ArrayList<>(ranked.size());
		while (!available.isEmpty())
		{
			int next = available.remove();
			ordered.add(ranked.get(next));
			for (int dependant : dependants.getOrDefault(next, List.of()))
			{
				if (--unmet[dependant] == 0)
				{
					available.add(dependant);
				}
			}
		}
		if (ordered.size() != ranked.size())
		{
			throw new IllegalArgumentException("Cycle in milestone prerequisite gaps");
		}
		return ordered;
	}

	/** Quest goal id to the distinct non-hidden goal ids whose gap tree (top level or inside a diary task) needs that quest. */
	private static Map<String, Set<String>> dependents(Map<String, GoalStatus> byId, Map<String, Set<String>> extraDependents)
	{
		Map<String, Set<String>> dependents = new HashMap<>();
		for (GoalStatus status : byId.values())
		{
			if (status.getGoal().getCategory() == GoalCategory.SKILL_TARGET)
			{
				for (GoalRef parent : status.getParents())
				{
					if (byId.containsKey(parent.getId()))
					{
						collectQuestIds(status.getGaps(), parent.getId(), dependents);
					}
				}
			}
			else
			{
				collectQuestIds(status.getGaps(), status.getGoal().getId(), dependents);
			}
		}
		extraDependents.forEach((questId, ids) -> ids.stream().filter(byId::containsKey).filter(id -> !id.equals(questId))
			.forEach(id -> dependents.computeIfAbsent(questId, k -> new LinkedHashSet<>()).add(id)));
		return dependents;
	}

	private static void collectQuestIds(List<Gap> gaps, String dependentId, Map<String, Set<String>> dependents)
	{
		for (Gap gap : gaps)
		{
			if (gap instanceof QuestPrereqGap)
			{
				String questId = "quest:" + ((QuestPrereqGap) gap).getQuest().getId();
				if (!questId.equals(dependentId))
				{
					dependents.computeIfAbsent(questId, k -> new LinkedHashSet<>()).add(dependentId);
				}
			}
			else if (gap instanceof DiaryTaskGap)
			{
				collectQuestIds(((DiaryTaskGap) gap).getGaps(), dependentId, dependents);
			}
		}
	}

	private static int dependentCount(Map<String, Set<String>> dependents, String goalId)
	{
		return dependents.getOrDefault(goalId, Set.of()).size();
	}

	/** Re-creates each ranked quest with dependents so it names them in rank order. */
	private static List<RankedGoal> withUnblocks(List<RankedGoal> ranked, Map<String, Set<String>> dependents, Map<String, GoalStatus> byId)
	{
		Map<String, Integer> position = new HashMap<>();
		for (int i = 0; i < ranked.size(); i++)
		{
			position.put(ranked.get(i).getStatus().getGoal().getId(), i);
		}
		List<RankedGoal> result = new ArrayList<>(ranked.size());
		for (RankedGoal r : ranked)
		{
			Set<String> ids = dependents.get(r.getStatus().getGoal().getId());
			if (ids == null || ids.isEmpty())
			{
				result.add(r);
				continue;
			}
			List<String> names = ids.stream()
				.sorted(Comparator.comparingInt(id -> position.getOrDefault(id, Integer.MAX_VALUE)))
				.map(id -> byId.get(id).getGoal().getName())
				.collect(Collectors.toList());
			result.add(new RankedGoal(r.getStatus(), r.getScore(), r.isPinned(), r.isLater(), names));
		}
		return result;
	}

	/** A status with an unseen bank is never "Ready now", even with no gaps. */
	private static boolean isReadyNow(GoalStatus status)
	{
		RewardValue value = status.getObjective() == null ? RewardValue.USEFUL : status.getObjective().getValue();
		return status.isReady() && !status.isBankUnknown() && value.ordinal() <= RewardValue.USEFUL.ordinal();
	}

	/**
	 * {@code score = priority × closeness × progression value}, {@code closeness = 1 / (1 + unmet + xpDelta / 250000)}.
	 * A skill target whose route the bank covers has closeness 1.0 -
	 * the materials are in hand, so it is as close as a ready goal.
	 */
	static double score(GoalStatus status)
	{
		return score(status, 0);
	}

	/** As {@link #score(GoalStatus)}, with the fan-out bonus of {@code min(2, dependents x 0.5)} added to the priority. */
	static double score(GoalStatus status, int dependents)
	{
		if (status.isBankCovered())
		{
			return status.getGoal().getPriority();
		}
		if (status.isUncoveredTarget())
		{
			// Never above the goal it serves.
			return status.getParentScore();
		}
		int unmet = GoalMetrics.unmetCount(status.getGaps());
		long xpDelta = GoalMetrics.xpDeltaSum(status.getGaps());
		double closeness = 1.0 / (1 + unmet + xpDelta / XP_SCALE);
		double bonus = Math.min(FAN_OUT_CAP, dependents * FAN_OUT_PER_DEPENDENT);
		return (status.getGoal().getPriority() + bonus) * closeness * progressionValue(status);
	}

	private static double progressionValue(GoalStatus status)
	{
		if (status.getObjective() == null) return 1.0;
		switch (status.getObjective().getValue())
		{
			case MAJOR: return 1.5;
			case USEFUL: return 1.0;
			case SITUATIONAL: return 0.2;
			case COLLECTION: return 0.0;
			default: throw new IllegalStateException("Unknown progression value");
		}
	}
}

package com.signpost.engine;

import com.signpost.engine.model.Gap;
import com.signpost.engine.model.GoalCategory;
import com.signpost.engine.model.PrerequisiteGap;
import com.signpost.engine.model.RankedGoal;
import com.signpost.kb.KnowledgeBase;
import com.signpost.kb.MilestoneEntry;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * Picks the panel's "Pick one" three suggestions from an already-{@link Ranker}-ordered list:
 * pins fill slots first (up to three, regardless of category), then
 * the ranked order fills what's left. Category diversity breaks equally valuable choices,
 * never replacing a stronger progression goal with a marginal grind. A goal marked
 * {@code later}
 * is never picked - it can still appear in {@link #rest}. A non-pinned candidate is also
 * skipped when it would pair a boss with one of its own drops (either order) already picked - see
 * {@link #pairsWithAlreadyPicked}. Pure: no {@link net.runelite.api.Client}, no I/O.
 */
public final class SuggestSelector
{
	private static final int SLOTS = 3;

	/** As {@link #pick3(List, KnowledgeBase)} with no boss/drop dedupe - for callers with no {@link KnowledgeBase} on hand. */
	public List<RankedGoal> pick3(List<RankedGoal> ranked)
	{
		return pick3(ranked, null);
	}

	/** {@code kb} may be {@code null} to skip the boss/drop pairing rule entirely. */
	public List<RankedGoal> pick3(List<RankedGoal> ranked, KnowledgeBase kb)
	{
		if (ranked.isEmpty())
		{
			return List.of();
		}
		// Gear uses provider readiness/rank, not invented GE prices. Reserve a style only after picking it.
		Set<String> ladderProviders = kb == null ? Set.of() : kb.getGearLadders().stream()
			.flatMap(l -> l.getRungs().stream()).map(r -> r.getProvider()).collect(Collectors.toSet());
		ranked = ranked.stream().filter(r -> {
			MilestoneEntry entry = kb == null ? null : kb.milestoneById(id(r));
			return r.isPinned() || entry == null || entry.getCategory() != com.signpost.kb.MilestoneCategory.GEAR
				|| !ladderProviders.contains(id(r));
		}).collect(Collectors.toList());

		List<RankedGoal> picked = new ArrayList<>();
		Set<String> used = new LinkedHashSet<>();

		// Pinned entries sit at the front of `ranked` (Ranker's contract): take up to three of them
		// first, before any category or pairing consideration - a pin is an explicit user override.
		for (RankedGoal r : ranked)
		{
			if (picked.size() >= SLOTS || !r.isPinned())
			{
				break;
			}
			if (sameUpgradeStyle(r, picked))
			{
				continue;
			}
			picked.add(r);
			used.add(id(r));
		}

		// Fill up to slot 2 from the ranked order (pins, if any, already occupy the front of it).
		for (RankedGoal r : ranked)
		{
			if (picked.size() >= 2)
			{
				break;
			}
			if (eligible(r, used) && !used.contains(id(r)) && !pairsWithAlreadyPicked(r, kb, picked))
			{
				picked.add(r);
				used.add(id(r));
			}
		}

		if (picked.isEmpty())
		{
			// Every ranked goal is "later" (or paired away): nothing to suggest, and no slot-1
			// category to compare against.
			return List.of();
		}

		if (picked.size() < SLOTS)
		{
			GoalCategory first = category(picked.get(0));
			GoalCategory second = picked.size() > 1 ? category(picked.get(1)) : null;

			RankedGoal third = nextUnused(ranked, used, kb, picked);
			RankedGoal diverse = second != null && first == second ? nextOfDifferentCategory(ranked, used, first, kb, picked) : null;
			if (third != null && diverse != null && Double.compare(diverse.getScore(), third.getScore()) == 0
				&& diverse.getStatus().isReady() == third.getStatus().isReady()
				&& diverse.getStatus().isBankUnknown() == third.getStatus().isBankUnknown())
			{
				third = diverse;
			}
			if (third != null)
			{
				picked.add(third);
			}
		}

		return List.copyOf(picked);
	}

	/** {@code ranked} minus {@code picked}, order preserved - the "next 10 / show more" list. */
	public List<RankedGoal> rest(List<RankedGoal> ranked, List<RankedGoal> picked)
	{
		Set<String> pickedIds = picked.stream().map(SuggestSelector::id).collect(Collectors.toCollection(LinkedHashSet::new));
		return ranked.stream().filter(r -> !pickedIds.contains(id(r))).collect(Collectors.toUnmodifiableList());
	}

	/**
	 * True when picking {@code r} would put a boss milestone in the same "Pick one" three as one of
	 * its own drops (e.g. God Wars Dungeon alongside Bandos armour). Checks both
	 * directions: {@code r} a gear entry whose {@link MilestoneEntry#getObtainedFrom()} boss is
	 * already in {@code used}, or {@code r} a boss whose id is some already-{@code used} entry's
	 * {@code obtainedFrom}. {@code kb == null} always returns false (no lookup possible).
	 */
	private static boolean pairsWithAlreadyPicked(RankedGoal r, KnowledgeBase kb, List<RankedGoal> picked)
	{
		if (sameUpgradeStyle(r, picked)) return true;
		if (kb == null) return false;
		String source = providerId(r);
		MilestoneEntry entry = kb.milestoneById(source);
		for (RankedGoal other : picked)
		{
			String otherSource = providerId(other);
			MilestoneEntry otherEntry = kb.milestoneById(otherSource);
			if (source.equals(otherSource)
				|| entry != null && otherSource.equals(entry.getObtainedFrom())
				|| otherEntry != null && source.equals(otherEntry.getObtainedFrom()))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean sameUpgradeStyle(RankedGoal candidate, List<RankedGoal> picked)
	{
		var upgrade = candidate.getStatus().getGoal().getUpgrade();
		if (upgrade == null) return false;
		for (RankedGoal other : picked)
		{
			var existing = other.getStatus().getGoal().getUpgrade();
			if (existing != null && existing.getStyle().equals(upgrade.getStyle())) return true;
		}
		return false;
	}

	private static String providerId(RankedGoal r)
	{
		return r.getStatus().getGoal().getUpgrade() == null ? id(r)
			: r.getStatus().getGoal().getUpgrade().getTarget().getProvider();
	}

	private static RankedGoal nextOfDifferentCategory(List<RankedGoal> ranked, Set<String> used, GoalCategory exclude, KnowledgeBase kb, List<RankedGoal> picked)
	{
		for (RankedGoal r : ranked)
		{
			if (eligible(r, used) && !used.contains(id(r)) && category(r) != exclude && !pairsWithAlreadyPicked(r, kb, picked))
			{
				return r;
			}
		}
		return null;
	}

	private static RankedGoal nextUnused(List<RankedGoal> ranked, Set<String> used, KnowledgeBase kb, List<RankedGoal> picked)
	{
		for (RankedGoal r : ranked)
		{
			if (eligible(r, used) && !used.contains(id(r)) && !pairsWithAlreadyPicked(r, kb, picked))
			{
				return r;
			}
		}
		return null;
	}

	/**
	 * Automatic picks must follow their unmet prerequisites even when category diversity, hiding,
	 * or the later/pairing filters skip a prerequisite. Pins bypass this check; blocked goals remain
	 * in the ranked/rest list and can still be focused explicitly.
	 */
	private static boolean eligible(RankedGoal r, Set<String> used)
	{
		if (r.isLater() || r.getStatus().isUncoveredTarget())
		{
			return false;
		}
		// An unseen item is not a confirmed upgrade objective. Explicit pins can request a check.
		if (r.getStatus().getObjective() != null && !r.getStatus().getObjective().hasConfirmedReason()) return false;
		for (Gap gap : r.getStatus().getGaps())
		{
			if (gap instanceof PrerequisiteGap && !used.contains(((PrerequisiteGap) gap).getGoalId()))
			{
				return false;
			}
		}
		return true;
	}

	private static GoalCategory category(RankedGoal r)
	{
		GoalCategory category = r.getStatus().getGoal().getCategory();
		return category == GoalCategory.GEAR_UPGRADE ? GoalCategory.MILESTONE : category;
	}

	private static String id(RankedGoal r)
	{
		return r.getStatus().getGoal().getId();
	}
}

package com.signpost.engine;

import com.signpost.engine.model.QuestXp;
import com.signpost.engine.model.Route;
import com.signpost.engine.model.RouteStep;
import com.signpost.kb.ItemQuantity;
import com.signpost.kb.KnowledgeBase;
import com.signpost.kb.MethodEntry;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Experience;
import net.runelite.api.Skill;

/**
 * Pure function {@code (skill, fromXp, toXp, bank, kb) -> Route}: simulates training a skill from
 * a bank. No {@link net.runelite.api.Client}, no I/O.
 *
 * <p>XP is tracked internally as an exact {@code double} (bundled {@code xpPerAction} values like
 * 87.5 aren't integral); every {@code long}/{@code int} xp or level exposed on {@link Route}/
 * {@link RouteStep} is derived from that double via {@link Math#floor} and
 * {@link Experience#getLevelForXp}, never accumulated as a rounded value itself, so results stay
 * exact regardless of how many steps a route takes.
 */
public final class RoutePlanner
{
	private static final String BARBARIAN_MIX_TYPE = "Barbarian Mix";

	private RoutePlanner()
	{
	}

	public static Route route(Skill skill, long fromXp, long toXp, Map<Integer, Integer> bank, KnowledgeBase kb)
	{
		return route(skill, fromXp, toXp, bank, kb, List.of());
	}

	/** As {@link #route(Skill, long, long, Map, KnowledgeBase)}, first crediting each of {@code quests} as its own step. */
	public static Route route(Skill skill, long fromXp, long toXp, Map<Integer, Integer> bank, KnowledgeBase kb, List<QuestXp> quests)
	{
		Map<Integer, Integer> simBank = new LinkedHashMap<>(bank);
		double simXp = fromXp;
		List<RouteStep> steps = new ArrayList<>();

		for (QuestXp quest : quests)
		{
			int fromLevel = capLevel(simXp);
			simXp += quest.getXp();
			steps.add(new RouteStep(null, 1, fromLevel, capLevel(simXp), quest.getXp(), Map.of(), List.of(), quest));
		}

		while (simXp < toXp)
		{
			int simLevel = capLevel(simXp);
			MethodEntry best = null;
			for (MethodEntry candidate : candidatesAt(skill, simLevel, kb))
			{
				if (affordable(candidate, skill, simBank, kb) > 0)
				{
					best = candidate;
					break;
				}
			}
			if (best == null)
			{
				break;
			}

			int affordable = affordable(best, skill, simBank, kb);
			long unlockGap = Math.round(Experience.getXpForLevel(simLevel + 1) - simXp);
			long toTargetGap = Math.round(toXp - simXp);
			int count = (int) Math.min(affordable,
				Math.min(ceilDiv(unlockGap, best.getXpPerAction()), ceilDiv(toTargetGap, best.getXpPerAction())));
			count = Math.max(count, 1);

			List<RouteStep> crafts = new ArrayList<>();
			Map<Integer, Integer> materialsUsed = new LinkedHashMap<>();
			for (ItemQuantity material : best.getMaterials())
			{
				int need = (int) Math.ceil(count * material.getQuantity());
				materialsUsed.merge(material.getId(), need, Integer::sum);
				int haveDirect = simBank.getOrDefault(material.getId(), 0);
				if (haveDirect < need)
				{
					int shortfall = need - haveDirect;
					RouteStep craft = craftShortfall(material.getId(), shortfall, skill, simBank, kb, simXp);
					if (craft != null)
					{
						simXp += craft.getXpGained();
						crafts.add(craft);
					}
				}
				simBank.merge(material.getId(), -need, Integer::sum);
				assertNonNegative(simBank, material.getId(), best);
			}
			for (ItemQuantity output : best.getOutputs())
			{
				if (output.getId() == null)
				{
					// Unresolved (generic) output: not tracked in the simulated bank, but the method
					// stays usable as long as its own materials (inputs) all resolve.
					continue;
				}
				int produced = (int) Math.floor(count * output.getQuantity());
				simBank.merge(output.getId(), produced, Integer::sum);
			}

			// fromLevel is taken AFTER crediting any craft sub-step xp above: crafting is a real
			// action performed before the method's own action this iteration.
			int fromLevel = capLevel(simXp);
			simXp += count * best.getXpPerAction();
			int toLevel = capLevel(simXp);
			long xpGained = (long) Math.floor(count * best.getXpPerAction());

			// A method the route comes back to (after a better one ran dry) merges into its
			// FIRST step, wherever that is, so the reader sees each method once with its total.
			int existing = indexOfMethod(steps, best);
			if (existing >= 0)
			{
				RouteStep previous = steps.get(existing);
				Map<Integer, Integer> mergedMaterials = new LinkedHashMap<>(previous.getMaterialsUsed());
				materialsUsed.forEach((id, qty) -> mergedMaterials.merge(id, qty, Integer::sum));
				List<RouteStep> mergedCrafts = new ArrayList<>(previous.getCrafts());
				mergedCrafts.addAll(crafts);
				steps.set(existing, new RouteStep(best, previous.getCount() + count, previous.getFromLevel(),
					Math.max(previous.getToLevel(), toLevel), previous.getXpGained() + xpGained, Map.copyOf(mergedMaterials),
					List.copyOf(mergedCrafts)));
			}
			else
			{
				steps.add(new RouteStep(best, count, fromLevel, toLevel, xpGained, Map.copyOf(materialsUsed), List.copyOf(crafts)));
			}
		}

		long uncoveredXp = Math.max(0, (long) Math.ceil(toXp - simXp));
		long finalXp = (long) Math.floor(simXp);
		return new Route(List.copyOf(steps), uncoveredXp, finalXp, Map.copyOf(simBank));
	}

	private static int indexOfMethod(List<RouteStep> steps, MethodEntry method)
	{
		for (int i = 0; i < steps.size(); i++)
		{
			if (method.equals(steps.get(i).getMethod()))
			{
				return i;
			}
		}
		return -1;
	}

	/**
	 * Crafts (from {@code simBank} alone, one intermediate action-batch, no further recursion) as
	 * much of {@code shortfall} units of {@code itemId} as {@link #maxCraftable} allows, consuming
	 * the intermediate's materials and adding its output into {@code simBank}. Returns {@code null}
	 * when no intermediate produces {@code itemId} (the outer material stays short; the caller
	 * already excluded this method from candidates unless the direct bank covered it). Every
	 * bundled intermediate is 0-xp today, but a craft can award xp (e.g. herb
	 * cleaning), so the craft's own xp is credited here too - {@code xpAtStart} is the running
	 * {@code simXp} at the moment this craft runs, used only to report the craft's from/to level.
	 */
	private static RouteStep craftShortfall(int itemId, int shortfall, Skill skill, Map<Integer, Integer> simBank, KnowledgeBase kb,
		double xpAtStart)
	{
		MethodEntry intermediate = bestIntermediateFor(itemId, skill, simBank, kb);
		if (intermediate == null)
		{
			return null;
		}
		double outputQty = outputQuantity(intermediate, itemId);
		int craftCount = (int) Math.ceil(shortfall / outputQty);

		Map<Integer, Integer> materialsUsed = new LinkedHashMap<>();
		for (ItemQuantity material : intermediate.getMaterials())
		{
			int need = (int) Math.ceil(craftCount * material.getQuantity());
			materialsUsed.merge(material.getId(), need, Integer::sum);
			simBank.merge(material.getId(), -need, Integer::sum);
			assertNonNegative(simBank, material.getId(), intermediate);
		}
		int produced = (int) Math.floor(craftCount * outputQty);
		simBank.merge(itemId, produced, Integer::sum);

		long craftXpGained = (long) Math.floor(craftCount * intermediate.getXpPerAction());
		int fromLevel = capLevel(xpAtStart);
		int toLevel = capLevel(xpAtStart + craftXpGained);
		return new RouteStep(intermediate, craftCount, fromLevel, toLevel, craftXpGained, Map.copyOf(materialsUsed), List.of());
	}

	/** Fail loud (never silently let a simulated bank entry go negative) rather than produce a route that spends items it doesn't have. */
	private static void assertNonNegative(Map<Integer, Integer> bank, int itemId, MethodEntry method)
	{
		Integer qty = bank.get(itemId);
		if (qty != null && qty < 0)
		{
			throw new IllegalStateException(
				"Route simulation drove item " + itemId + " negative (" + qty + ") consuming materials for \"" + method.getName() + "\"");
		}
	}

	/**
	 * The affordable action count for {@code method} from {@code simBank}, where a short material
	 * may be topped up by {@link #maxCraftable} - one level of intermediate crafting, no deeper
	 * recursion. Two materials whose intermediates draw on the same raw ingredient (or that overlap
	 * with the method's own other material) can't both be checked independently against the same
	 * undecremented bank - that double-counts the shared stock and can drive {@code simBank}
	 * negative once actions actually run. So this binary-searches the true count: {@link #feasible}
	 * simulates {@code count} actions (materials + crafts) against a scratch copy of the bank and
	 * reports whether every entry stays non-negative, which is monotonic in {@code count} (higher
	 * count only needs more, never less), so binary search converges on the exact answer.
	 * {@code independentUpperBound} - the old per-material calculation - only bounds the search.
	 */
	private static int affordable(MethodEntry method, Skill skill, Map<Integer, Integer> simBank, KnowledgeBase kb)
	{
		int upperBound = independentUpperBound(method, skill, simBank, kb);
		if (upperBound <= 0)
		{
			return 0;
		}
		int low = 0;
		int high = upperBound;
		while (low < high)
		{
			int mid = low + (high - low + 1) / 2;
			if (feasible(method, mid, skill, simBank, kb))
			{
				low = mid;
			}
			else
			{
				high = mid - 1;
			}
		}
		return low;
	}

	private static int independentUpperBound(MethodEntry method, Skill skill, Map<Integer, Integer> simBank, KnowledgeBase kb)
	{
		int min = Integer.MAX_VALUE;
		for (ItemQuantity material : method.getMaterials())
		{
			int have = simBank.getOrDefault(material.getId(), 0) + maxCraftable(material.getId(), skill, simBank, kb);
			int afford = (int) Math.floor(have / material.getQuantity());
			min = Math.min(min, afford);
		}
		return min == Integer.MAX_VALUE ? 0 : min;
	}

	/** Whether {@code count} actions of {@code method} are jointly affordable: simulated against a scratch copy of
	 * {@code bank}, crafting each short material (one level, from whatever the scratch bank has left at that point)
	 * and failing as soon as a material can't be fully covered. */
	private static boolean feasible(MethodEntry method, int count, Skill skill, Map<Integer, Integer> bank, KnowledgeBase kb)
	{
		Map<Integer, Integer> scratch = new HashMap<>(bank);
		for (ItemQuantity material : method.getMaterials())
		{
			int need = (int) Math.ceil(count * material.getQuantity());
			int have = scratch.getOrDefault(material.getId(), 0);
			if (have < need && !craftIntoScratch(material.getId(), need - have, skill, scratch, kb))
			{
				return false;
			}
			scratch.merge(material.getId(), -need, Integer::sum);
		}
		return true;
	}

	/** As {@link #craftShortfall}, but on a throwaway scratch bank and reporting success/failure instead of
	 * recording a {@link RouteStep} - used only by {@link #feasible} to probe a candidate count. */
	private static boolean craftIntoScratch(int itemId, int shortfall, Skill skill, Map<Integer, Integer> scratch, KnowledgeBase kb)
	{
		MethodEntry intermediate = bestIntermediateFor(itemId, skill, scratch, kb);
		if (intermediate == null || producibleUnits(intermediate, itemId, scratch) < shortfall)
		{
			return false;
		}
		double outputQty = outputQuantity(intermediate, itemId);
		int craftCount = (int) Math.ceil(shortfall / outputQty);
		for (ItemQuantity material : intermediate.getMaterials())
		{
			int need = (int) Math.ceil(craftCount * material.getQuantity());
			scratch.merge(material.getId(), -need, Integer::sum);
		}
		scratch.merge(itemId, (int) Math.floor(craftCount * outputQty), Integer::sum);
		return true;
	}

	/**
	 * The largest total quantity of {@code itemId} obtainable by running the best (highest-yield,
	 * ties by name) intermediate method that outputs it, using only what's already in
	 * {@code simBank} - never a deeper recursive craft.
	 */
	private static int maxCraftable(int itemId, Skill skill, Map<Integer, Integer> simBank, KnowledgeBase kb)
	{
		MethodEntry best = bestIntermediateFor(itemId, skill, simBank, kb);
		return best == null ? 0 : producibleUnits(best, itemId, simBank);
	}

	private static MethodEntry bestIntermediateFor(int itemId, Skill skill, Map<Integer, Integer> simBank, KnowledgeBase kb)
	{
		MethodEntry best = null;
		int bestUnits = -1;
		for (MethodEntry candidate : kb.methodsFor(skill))
		{
			if (!candidate.isIntermediate() || !candidate.isUsable() || outputQuantity(candidate, itemId) <= 0)
			{
				continue;
			}
			int units = producibleUnits(candidate, itemId, simBank);
			if (units > bestUnits || (units == bestUnits && best != null && candidate.getName().compareTo(best.getName()) < 0))
			{
				best = candidate;
				bestUnits = units;
			}
		}
		return best;
	}

	private static int producibleUnits(MethodEntry intermediate, int itemId, Map<Integer, Integer> simBank)
	{
		if (intermediate.getMaterials().isEmpty())
		{
			return 0;
		}
		int maxActions = Integer.MAX_VALUE;
		for (ItemQuantity material : intermediate.getMaterials())
		{
			int have = simBank.getOrDefault(material.getId(), 0);
			maxActions = Math.min(maxActions, (int) Math.floor(have / material.getQuantity()));
		}
		return (int) Math.floor(maxActions * outputQuantity(intermediate, itemId));
	}

	private static double outputQuantity(MethodEntry method, int itemId)
	{
		for (ItemQuantity output : method.getOutputs())
		{
			if (output.getId() != null && output.getId() == itemId)
			{
				return output.getQuantity();
			}
		}
		return 0;
	}

	/** Every usable, non-intermediate, real-xp method of {@code skill} unlocked at {@code level}, excluding Barbarian
	 * Mix, ordered by preference: highest xp/action, then lowest levelReq, then name. */
	static List<MethodEntry> candidatesAt(Skill skill, int level, KnowledgeBase kb)
	{
		List<MethodEntry> candidates = new ArrayList<>();
		for (MethodEntry method : kb.methodsFor(skill))
		{
			if (method.isUsable() && !method.isIntermediate() && method.getXpPerAction() > 0 && method.getLevelReq() <= level
				&& !method.getTypes().contains(BARBARIAN_MIX_TYPE))
			{
				candidates.add(method);
			}
		}
		candidates.sort(Comparator
			.comparingDouble(MethodEntry::getXpPerAction).reversed()
			.thenComparingInt(MethodEntry::getLevelReq)
			.thenComparing(MethodEntry::getName));
		return candidates;
	}

	/** Package-visible: also used by {@link ShortfallResolver} to find the level a route stopped at. */
	static int capLevel(double xp)
	{
		return Math.min(Experience.MAX_REAL_LEVEL, Experience.getLevelForXp((int) xp));
	}

	private static long ceilDiv(long numerator, double denominator)
	{
		return (long) Math.ceil(numerator / denominator);
	}
}

package com.signpost.engine;

import com.signpost.engine.model.Goal;
import com.signpost.engine.model.GoalCategory;
import com.signpost.engine.model.GoalStatus;
import com.signpost.engine.model.GoalObjective;
import com.signpost.kb.GearLadder;
import com.signpost.kb.KnowledgeBase;
import com.signpost.kb.MilestoneEntry;
import com.signpost.kb.WikiUrls;
import com.signpost.snapshot.Snapshot;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

final class GearUpgradeSynthesiser
{
	private GearUpgradeSynthesiser() {}

	static String id(GearLadder ladder, GearLadder.Rung rung)
	{
		return "gear:" + ladder.getStyle() + ":" + ladder.getSlot() + ":" + rung.getId();
	}

	static List<GoalStatus> run(List<GearLadder> ladders, Snapshot snapshot, KnowledgeBase kb, Set<String> manual,
		GapEngine gaps, GearComparison comparison)
	{
		Map<String, GoalStatus> providers = new HashMap<>();
		List<GoalStatus> result = new ArrayList<>();
		for (GearLadder ladder : ladders)
		{
			String replaces = null;
			for (GearLadder.Rung rung : ladder.getRungs())
			{
				String coveringName = comparison.coveringName(rung.getVariants(), ladder.getStyle());
				if (coveringName != null)
				{
					replaces = coveringName;
					continue;
				}
				MilestoneEntry source = kb.milestoneById(rung.getProvider());
				if (ProgressionObjectives.providerGreenLogged(source, snapshot)) continue;
				if (snapshot.getAccountType().isIron() && rung.isGeOnly()) continue;
				GoalStatus provider = providers.computeIfAbsent(rung.getProvider(),
					key -> gaps.providerStatus(key, snapshot, kb, manual, comparison));
				Goal goal = new Goal(id(ladder, rung), GoalCategory.GEAR_UPGRADE, rung.getName(), WikiUrls.forTitle(rung.getName()),
					provider.getGoal().getPriority(), provider.getGoal().getStage(), new Goal.Upgrade(ladder.getStyle(), ladder.getSlot(), rung, replaces));
				List<String> notes = new ArrayList<>();
				notes.add("Provider: " + provider.getGoal().getName());
				notes.addAll(provider.getNotes());
				GoalObjective objective = ProgressionObjectives.upgrade(source, rung, kb, comparison);
				result.add(new GoalStatus(goal, provider.getGaps(), provider.isReady(), provider.isBankUnknown() || objective.isBankUnknown(),
					List.copyOf(notes), provider.getMet(), List.of(), null, 0, List.of(), objective));
				break;
			}
		}
		return result;
	}
}

package com.signpost.engine;

import com.signpost.engine.model.PrayerUnlockGap;
import com.signpost.engine.model.SlayerPointsGap;
import com.signpost.engine.model.SlayerUnlockGap;
import com.signpost.engine.model.CombatLevelGap;
import com.signpost.engine.model.DiaryTaskGap;
import com.signpost.engine.model.DiaryTierGap;
import com.signpost.engine.model.Gap;
import com.signpost.engine.model.GearGap;
import com.signpost.engine.model.GoalStatus;
import com.signpost.engine.model.ItemGap;
import com.signpost.engine.model.KudosGap;
import com.signpost.engine.model.PrerequisiteGap;
import com.signpost.engine.model.QuestPointsGap;
import com.signpost.engine.model.QuestPrereqGap;
import com.signpost.engine.model.SkillLevelGap;
import com.signpost.kb.OwnedItem;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;

/**
 * A stable, order-independent digest over a {@link GoalStatus}'s gap kinds and keys (not its
 * counts or estimates), used by {@link PrefsResolver} to detect when a snoozed goal's
 * requirements have changed (a changed gap ends the snooze early). Pure: no
 * {@link net.runelite.api.Client}, no I/O.
 */
public final class GapFingerprint
{
	private GapFingerprint()
	{
	}

	public static String of(GoalStatus status)
	{
		List<String> keys = new ArrayList<>();
		for (Gap gap : status.getGaps())
		{
			keys.add(keyOf(gap));
		}
		Collections.sort(keys);
		return String.join("|", keys);
	}

	private static String keyOf(Gap gap)
	{
		if (gap instanceof SlayerPointsGap)
		{
			return "slayerPoints:" + ((SlayerPointsGap) gap).getNeed();
		}
		if (gap instanceof SlayerUnlockGap)
		{
			return "slayerUnlock:" + ((SlayerUnlockGap) gap).getReward().name();
		}
		if (gap instanceof PrayerUnlockGap)
		{
			return "prayer:" + ((PrayerUnlockGap) gap).getPrayer().name();
		}
		if (gap instanceof SkillLevelGap)
		{
			SkillLevelGap g = (SkillLevelGap) gap;
			return "skill:" + g.getSkill().name() + ":" + g.getNeed();
		}
		if (gap instanceof QuestPrereqGap)
		{
			return "quest:" + ((QuestPrereqGap) gap).getQuest().name();
		}
		if (gap instanceof ItemGap)
		{
			ItemGap g = (ItemGap) gap;
			return "item:" + g.getName() + ":" + g.getNeed();
		}
		if (gap instanceof DiaryTaskGap)
		{
			DiaryTaskGap g = (DiaryTaskGap) gap;
			List<String> inner = new ArrayList<>();
			for (Gap innerGap : g.getGaps())
			{
				inner.add(keyOf(innerGap));
			}
			Collections.sort(inner);
			return "diaryTask:" + g.getOrdinal() + ":[" + String.join(",", inner) + "]";
		}
		if (gap instanceof DiaryTierGap)
		{
			return "diaryTier:" + ((DiaryTierGap) gap).getTier().name();
		}
		if (gap instanceof QuestPointsGap)
		{
			return "questPoints:" + ((QuestPointsGap) gap).getNeed();
		}
		if (gap instanceof KudosGap)
		{
			return "kudos:" + ((KudosGap) gap).getNeed();
		}
		if (gap instanceof CombatLevelGap)
		{
			return "combat:" + ((CombatLevelGap) gap).getNeed();
		}
		if (gap instanceof GearGap)
		{
			List<String> ids = ((GearGap) gap).getAcceptable().stream().map(OwnedItem::getId).map(String::valueOf).collect(Collectors.toList());
			Collections.sort(ids);
			return "gear:[" + String.join(",", ids) + "]";
		}
		if (gap instanceof PrerequisiteGap)
		{
			return "prereq:" + ((PrerequisiteGap) gap).getGoalId();
		}
		throw new IllegalStateException("Unknown gap type: " + gap.getClass());
	}
}

package com.signpost.engine;

import com.signpost.engine.model.BringItemStatus;
import com.signpost.engine.model.NextStep;
import com.signpost.engine.model.PlanOffer;
import com.signpost.engine.model.RouteStep;
import com.signpost.engine.model.Shortfall;
import com.signpost.engine.model.ShortfallItem;
import com.signpost.kb.BringItem;
import com.signpost.kb.ItemQuantity;
import com.signpost.kb.KnowledgeBase;
import com.signpost.kb.MethodEntry;
import com.signpost.kb.MethodGuidance;
import com.signpost.snapshot.Snapshot;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Pure presentation derived from the already selected route and risk-filtered offers. */
public final class NextStepGuidance
{
	private NextStepGuidance() {}

	public static List<BringItemStatus> items(List<BringItem> items, Snapshot snapshot)
	{
		Map<Integer, Integer> owned = NextStepPicker.bankAll(snapshot);
		List<BringItemStatus> result = new ArrayList<>();
		for (BringItem item : items)
		{
			result.add(new BringItemStatus(item, item.getQuantity(), owned.getOrDefault(item.getId(), 0)));
		}
		return List.copyOf(result);
	}

	public static NextStep derive(NextStep next, Shortfall shortfall, Snapshot snapshot, KnowledgeBase kb)
	{
		if (next.getRoute() != null && !next.getRoute().getSteps().isEmpty())
		{
			RouteStep step = next.getRoute().getSteps().get(0);
			while (!step.getCrafts().isEmpty())
			{
				step = step.getCrafts().get(0);
			}
			if (step.getQuest() != null) { return next; }
			NextStep training = method(next, step, snapshot, kb);
			if (training.hasGuidance()) { return training; }
		}
		if (shortfall != null)
		{
			NextStep gathering = gathering(next, shortfall.getItems());
			if (gathering.hasGuidance()) { return gathering; }
			if (shortfall.getAlternative() != null)
			{
				return gathering(next, shortfall.getAlternative().getItems());
			}
		}
		return next;
	}

	private static NextStep method(NextStep next, RouteStep step, Snapshot snapshot, KnowledgeBase kb)
	{
		MethodEntry method = step.getMethod();
		Map<Integer, Integer> owned = NextStepPicker.bankAll(snapshot);
		int count = step.getCount();
		// Merged route steps can include later batches: recommend only the batch affordable now.
		for (ItemQuantity material : method.getMaterials())
		{
			if (material.getId() == null) { return next; }
			count = Math.min(count, (int) Math.floor(owned.getOrDefault(material.getId(), 0) / material.getQuantity()));
		}
		if (count <= 0) { return next; }
		MethodGuidance guidance = kb.guidanceFor(method.getName());
		Map<Integer, BringItemStatus> bring = new LinkedHashMap<>();
		for (ItemQuantity material : method.getMaterials())
		{
			long quantity = (long) Math.ceil(material.getQuantity() * count);
			bring.put(material.getId(), new BringItemStatus(new BringItem(material.getName(), material.getId()), quantity,
				owned.getOrDefault(material.getId(), 0)));
		}
		for (BringItem tool : guidance.getBring())
		{
			bring.putIfAbsent(tool.getId(), new BringItemStatus(tool, tool.getQuantity(), owned.getOrDefault(tool.getId(), 0)));
		}
		String output = method.getOutputs().isEmpty() ? method.getName() : method.getOutputs().get(0).getName();
		long outputCount = method.getOutputs().isEmpty() ? count : (long) Math.ceil(method.getOutputs().get(0).getQuantity() * count);
		return next.withGuidance(List.copyOf(bring.values()), guidance.locationFor(method), "Make " + outputCount + " " + output);
	}

	private static NextStep gathering(NextStep next, List<ShortfallItem> items)
	{
		for (ShortfallItem item : items)
		{
			if (item.getHave() >= item.getNeed()) { continue; }
			for (PlanOffer offer : item.getPlans())
			{
				// Ingredient offers are also collected on their parent item for display.
				// Select them through craftFrom so already-owned ingredients are skipped.
				if ((item.getItem().getId() == null || offer.getPlan().getId() != item.getItem().getId())
					&& !offer.getPlan().getItem().equals(item.getItem().getName())) { continue; }
				if (offer.isMeetsRequirements() && !offer.getSteps().isEmpty())
				{
					String first = offer.getSteps().get(0);
					return next.withGuidance(offer.getItems(), firstSentence(first), first);
				}
				for (int i = 0; i < offer.getAlternativeSteps().size(); i++)
				{
					List<String> steps = offer.getAlternativeSteps().get(i);
					if (!steps.isEmpty())
					{
						String first = steps.get(0);
						return next.withGuidance(offer.getAlternativeItems().get(i), firstSentence(first), first);
					}
				}
			}
			NextStep ingredient = gathering(next, item.getCraftFrom());
			if (ingredient.hasGuidance()) { return ingredient; }
		}
		return next;
	}

	private static String firstSentence(String text)
	{
		int end = text.indexOf(". ");
		return end < 0 ? text : text.substring(0, end + 1);
	}
}

package com.signpost.engine;

import com.signpost.engine.model.Route;

/**
 * The time left to a skill target at the player's observed xp rate.
 * Pure arithmetic over data the plugin passes in ({@link com.signpost.engine.model.Advice#getXpPerHour()}).
 */
public final class Eta
{
	private Eta()
	{
	}

	/** The xp still to train: after the route's bank steps when a route exists, else the raw gap. */
	public static long remainingXp(Route route, long gapXp)
	{
		return route != null ? route.getUncoveredXp() : gapXp;
	}

	/** {@code "about 45 min at 38k/h"} (hours split out past 60 min), or {@code null} without a rate or with nothing left. */
	public static String text(long remainingXp, Long xpPerHour)
	{
		if (xpPerHour == null || xpPerHour <= 0 || remainingXp <= 0)
		{
			return null;
		}
		long minutes = (remainingXp * 60 + xpPerHour - 1) / xpPerHour;
		String time = minutes < 60 ? minutes + " min"
			: minutes % 60 == 0 ? (minutes / 60) + " h"
			: (minutes / 60) + " h " + (minutes % 60) + " min";
		String rate = xpPerHour < 1000 ? xpPerHour + "/h" : ((xpPerHour + 500) / 1000) + "k/h";
		return "about " + time + " at " + rate;
	}
}

package com.signpost.engine;

import com.signpost.kb.DiaryEntry;
import com.signpost.kb.DiaryTask;
import com.signpost.kb.KnowledgeBase;
import com.signpost.snapshot.DiaryTier;
import com.signpost.snapshot.Snapshot;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.VarbitID;

/**
 * Computes per-tier achievement diary progress from a {@link Snapshot} and {@link KnowledgeBase},
 * and cross-checks it against the game's own per-tier completed-task counter varbit as a
 * self-check that the bundled task->bit mapping is correct. Pure: no {@link net.runelite.api.Client}.
 */
public final class DiaryProgress
{
	/**
	 * The game's own "tasks completed" counter varbit for each diary tier, used only to self-check
	 * {@link #compute}'s bit-derived count. Referencing {@link VarbitID} constants by name keeps
	 * this compile-checked against the client; every one of the 48 tiers has one.
	 */
	public static final Map<DiaryTier, Integer> COUNT_VARBITS = buildCountVarbits();

	private DiaryProgress()
	{
	}

	public static Map<DiaryTier, DiaryTierProgress> compute(Snapshot snapshot, KnowledgeBase kb)
	{
		Map<DiaryTier, DiaryTierProgress> result = new EnumMap<>(DiaryTier.class);
		for (DiaryTier tier : DiaryTier.values())
		{
			DiaryEntry entry = kb.diary(tier);
			if (entry == null)
			{
				continue;
			}

			List<Integer> completedOrdinals = new ArrayList<>();
			for (DiaryTask task : entry.getTasks())
			{
				if (task.getCompletion().isComplete(snapshot))
				{
					completedOrdinals.add(task.getOrdinal());
				}
			}
			int completed = completedOrdinals.size();
			int total = entry.getTasks().size();

			Integer countVarbit = COUNT_VARBITS.get(tier);
			Integer gameCount = countVarbit == null ? null : snapshot.getDiaryCountVarbits().get(countVarbit);
			boolean mismatch = gameCount != null && gameCount != completed;

			result.put(tier, new DiaryTierProgress(completed, total, completedOrdinals, gameCount, mismatch));
		}
		return result;
	}

	private static Map<DiaryTier, Integer> buildCountVarbits()
	{
		Map<DiaryTier, Integer> m = new EnumMap<>(DiaryTier.class);
		m.put(DiaryTier.ARDOUGNE_EASY, VarbitID.ARDOUGNE_EASY_COUNT);
		m.put(DiaryTier.ARDOUGNE_MEDIUM, VarbitID.ARDOUGNE_MED_COUNT);
		m.put(DiaryTier.ARDOUGNE_HARD, VarbitID.ARDOUGNE_HARD_COUNT);
		m.put(DiaryTier.ARDOUGNE_ELITE, VarbitID.ARDOUGNE_ELITE_COUNT);
		m.put(DiaryTier.DESERT_EASY, VarbitID.DESERT_EASY_COUNT);
		m.put(DiaryTier.DESERT_MEDIUM, VarbitID.DESERT_MED_COUNT);
		m.put(DiaryTier.DESERT_HARD, VarbitID.DESERT_HARD_COUNT);
		m.put(DiaryTier.DESERT_ELITE, VarbitID.DESERT_ELITE_COUNT);
		m.put(DiaryTier.FALADOR_EASY, VarbitID.FALADOR_EASY_COUNT);
		m.put(DiaryTier.FALADOR_MEDIUM, VarbitID.FALADOR_MED_COUNT);
		m.put(DiaryTier.FALADOR_HARD, VarbitID.FALADOR_HARD_COUNT);
		m.put(DiaryTier.FALADOR_ELITE, VarbitID.FALADOR_ELITE_COUNT);
		m.put(DiaryTier.FREMENNIK_EASY, VarbitID.FREMENNIK_EASY_COUNT);
		m.put(DiaryTier.FREMENNIK_MEDIUM, VarbitID.FREMENNIK_MED_COUNT);
		m.put(DiaryTier.FREMENNIK_HARD, VarbitID.FREMENNIK_HARD_COUNT);
		m.put(DiaryTier.FREMENNIK_ELITE, VarbitID.FREMENNIK_ELITE_COUNT);
		m.put(DiaryTier.KANDARIN_EASY, VarbitID.KANDARIN_EASY_COUNT);
		m.put(DiaryTier.KANDARIN_MEDIUM, VarbitID.KANDARIN_MED_COUNT);
		m.put(DiaryTier.KANDARIN_HARD, VarbitID.KANDARIN_HARD_COUNT);
		m.put(DiaryTier.KANDARIN_ELITE, VarbitID.KANDARIN_ELITE_COUNT);
		m.put(DiaryTier.KARAMJA_EASY, VarbitID.KARAMJA_EASY_COUNT);
		m.put(DiaryTier.KARAMJA_MEDIUM, VarbitID.KARAMJA_MED_COUNT);
		m.put(DiaryTier.KARAMJA_HARD, VarbitID.KARAMJA_HARD_COUNT);
		m.put(DiaryTier.KARAMJA_ELITE, VarbitID.KARAMJA_ELITE_COUNT);
		m.put(DiaryTier.KOUREND_EASY, VarbitID.KOUREND_EASY_COUNT);
		m.put(DiaryTier.KOUREND_MEDIUM, VarbitID.KOUREND_MED_COUNT);
