package com.signpost.engine.model;

import lombok.Value;
import java.util.List;
import java.util.stream.Collectors;

/**
 * "Do this next": exactly one of the four factories below is used, matching
 * {@link #getType()}. Variant payloads are null when unused; guidance is added after selection.
 */
@Value
public class NextStep
{
	NextStepType type;
	QuestPrereqGap questGap;
	SkillLevelGap skillGap;
	Route route;
	ItemGap itemGap;
	List<BringItemStatus> bringItems;
	String where;
	String doText;

	private NextStep(NextStepType type, QuestPrereqGap questGap, SkillLevelGap skillGap, Route route, ItemGap itemGap)
	{
		this(type, questGap, skillGap, route, itemGap, List.of(), null, null);
	}

	private NextStep(NextStepType type, QuestPrereqGap questGap, SkillLevelGap skillGap, Route route, ItemGap itemGap,
		List<BringItemStatus> bringItems, String where, String doText)
	{
		this.type = type;
		this.questGap = questGap;
		this.skillGap = skillGap;
		this.route = route;
		this.itemGap = itemGap;
		this.bringItems = List.copyOf(bringItems);
		this.where = where;
		this.doText = doText;
	}

	public NextStep withGuidance(List<BringItemStatus> items, String where, String doText)
	{
		return new NextStep(type, questGap, skillGap, route, itemGap, items, where, doText);
	}

	public String getBring()
	{
		return bringItems.isEmpty() ? "Nothing extra" : bringItems.stream().map(BringItemStatus::text).collect(Collectors.joining(", "));
	}

	public boolean hasGuidance()
	{
		return where != null && doText != null;
	}

	/** An unfinished prerequisite quest whose own requirements are fully met. */
	public static NextStep quest(QuestPrereqGap gap)
	{
		return new NextStep(NextStepType.QUEST, gap, null, null, null);
	}

	/** A skill gap with its fully covering or partial route from the bank. */
	public static NextStep skill(SkillLevelGap gap, Route route)
	{
		return new NextStep(NextStepType.SKILL, null, gap, route, null);
	}

	/** The first missing item. */
	public static NextStep item(ItemGap gap)
	{
		return new NextStep(NextStepType.ITEM, null, null, null, gap);
	}

	/** Nothing left to pick: every requirement is already met. */
	public static NextStep none()
	{
		return new NextStep(NextStepType.NONE, null, null, null, null);
	}
}

package com.signpost.engine.model;

import java.util.List;
import lombok.Value;

/**
 * One {@link GoalStatus} placed by {@link com.signpost.engine.Ranker}, carrying its computed
 * {@code score} and whether it's user-pinned. {@code later} is true
 * when the goal's stage is more than one stage above the account's estimated stage; such goals have
 * already had their {@code score} multiplied down and are never picked by
 * {@link com.signpost.engine.SuggestSelector#pick3}. Never true for a pinned entry - a pin is an
 * explicit user override. {@code unblocks} names every other ranked goal whose
 * gap tree needs this quest, in rank order - empty for anything but a quest with dependents.
 */
@Value
public class RankedGoal
{
	GoalStatus status;
	double score;
	boolean pinned;
	boolean later;
	List<String> unblocks;

	public RankedGoal(GoalStatus status, double score, boolean pinned, boolean later)
	{
		this(status, score, pinned, later, List.of());
	}

	public RankedGoal(GoalStatus status, double score, boolean pinned, boolean later, List<String> unblocks)
	{
		this.status = status;
		this.score = score;
		this.pinned = pinned;
		this.later = later;
		this.unblocks = List.copyOf(unblocks);
	}

	/**
	 * The bucket {@link com.signpost.engine.Ranker} placed this goal into, derived from
	 * the fields above rather than stored separately - {@code pinned}/{@code later} directly, else
	 * "ready" iff the underlying {@link GoalStatus} is ready with a known bank (mirrors
	 * {@link com.signpost.engine.Ranker}'s own {@code isReadyNow}), else "rest".
	 */
	public Tier getTier()
	{
		if (pinned)
		{
			return Tier.PINNED;
		}
		if (later)
		{
			return Tier.LATER;
		}
		return status.isReady() && !status.isBankUnknown() ? Tier.READY : Tier.REST;
	}

	/** The four buckets {@link com.signpost.engine.Ranker} sorts a {@link RankedGoal} into. */
	public enum Tier
	{
		PINNED, READY, REST, LATER
	}
}

