/**
 * Pure function of {@link Snapshot} and {@link KnowledgeBase}: for every unfinished quest and
 * incomplete diary tier, works out exactly what's missing - and what's already
 * met, as {@link Met} entries in the same order the requirements are checked. No
 * {@link net.runelite.api.Client}, no I/O (global constraint: engine code is pure).
 */
public final class GapEngine
{
	private static final int QUEST_PRIORITY = 5;
	private static final int DIARY_PRIORITY = 4;

	/** Quest goal stage from its effective (post-override) priority: &ge;8 &rarr; 3, 5..7 &rarr; 2, else 1. */
	private static int questStage(int priority)
	{
		if (priority >= 8)
		{
			return 3;
		}
		return priority >= 5 ? 2 : 1;
	}

	/** Diary goal stage by tier: Easy 1, Medium 2, Hard 3, Elite 4. */
	private static final Map<DiaryTier, Integer> DIARY_STAGE = buildDiaryStages();

	private static Map<DiaryTier, Integer> buildDiaryStages()
	{
		Map<DiaryTier, Integer> m = new EnumMap<>(DiaryTier.class);
		for (DiaryTier tier : DiaryTier.values())
		{
			String tierName = tier.name();
			if (tierName.endsWith("_EASY"))
			{
				m.put(tier, 1);
			}
			else if (tierName.endsWith("_MEDIUM"))
			{
				m.put(tier, 2);
			}
			else if (tierName.endsWith("_HARD"))
			{
				m.put(tier, 3);
			}
			else // _ELITE
			{
				m.put(tier, 4);
			}
		}
		return Map.copyOf(m);
	}

	private static final Map<Integer, Quest> QUESTS_BY_ID = buildQuestsById();
	private static final Map<String, Quest> QUESTS_BY_NAME = buildQuestsByName();

	private final BoostTable boostTable;

	public GapEngine(BoostTable boostTable)
	{
		this.boostTable = boostTable;
	}

	/** As {@link #evaluate(Snapshot, KnowledgeBase, Map)}, computing {@link DiaryProgress} internally - for callers with no other need for it. */
	public List<GoalStatus> evaluate(Snapshot snapshot, KnowledgeBase kb)
	{
		return evaluate(snapshot, kb, DiaryProgress.compute(snapshot, kb), Set.of());
	}

	/**
	 * As {@link #evaluate(Snapshot, KnowledgeBase)}, but takes an already-computed
	 * {@link DiaryProgress#compute} result instead of
	 * computing it again - {@link Engine#run} shares one computation between this and
	 * {@link com.signpost.engine.model.Advice#getDiaryProgress()}.
	 */
	public List<GoalStatus> evaluate(Snapshot snapshot, KnowledgeBase kb, Map<DiaryTier, DiaryTierProgress> diaryProgress)
	{
		return evaluate(snapshot, kb, diaryProgress, Set.of());
	}

	/**
	 * As {@link #evaluate(Snapshot, KnowledgeBase, Map)}, but a milestone/slayer-target/boss goal
	 * whose id is in {@code ownedManually} is treated as done - never emitted here, so
	 * it can't appear ranked, later, snoozed, or ignored - and instead surfaces only via
	 * {@link Engine}'s {@code ownedManuallyNames}.
	 */
	public List<GoalStatus> evaluate(Snapshot snapshot, KnowledgeBase kb, Map<DiaryTier, DiaryTierProgress> diaryProgress, Set<String> ownedManually)
	{
		return evaluate(snapshot, kb, diaryProgress, ownedManually, new GearComparison(snapshot, kb, ownedManually));
	}

	List<GoalStatus> evaluate(Snapshot snapshot, KnowledgeBase kb, Map<DiaryTier, DiaryTierProgress> diaryProgress,
		Set<String> ownedManually, GearComparison comparison)
	{
		List<GoalStatus> result = new ArrayList<>();

		for (QuestEntry entry : kb.getQuests())
		{
			Quest quest = QUESTS_BY_ID.get(entry.getId());
			if (quest == null)
			{
				// A kb entry with no matching RuneLite Quest constant (e.g. a miniquest) - out of scope.
				continue;
			}
			QuestState state = snapshot.getQuests().getOrDefault(quest, QuestState.NOT_STARTED);
			if (state == QuestState.FINISHED)
			{
				continue;
			}
			result.add(questGoalStatus(quest, entry, snapshot, kb));
		}

		for (DiaryTier tier : DiaryTier.values())
		{
			DiaryEntry entry = kb.diary(tier);
			if (entry == null)
			{
				continue;
			}
			if (Boolean.TRUE.equals(snapshot.getDiaryTiers().get(tier)))
			{
				continue;
			}
			result.add(diaryGoalStatus(tier, entry, snapshot, kb, diaryProgress.get(tier)));
		}

		for (MilestoneEntry entry : kb.getMilestones())
		{
			if (entry.getCategory() == MilestoneCategory.GEAR && comparison.milestoneCovered(entry)) continue;
			milestoneGoalStatus(entry, snapshot, kb, ownedManually, comparison).ifPresent(result::add);
		}

		result.sort(Comparator.comparing(gs -> gs.getGoal().getId()));
		return result;
	}

	/**
	 * Drops sources with type {@code "GE"} for iron account types. Group irons have no
	 * GE either, so every iron type is filtered the same way. A normal account keeps every source.
	 */
	public static List<ItemSource> sourcesFor(List<ItemSource> sources, AccountType accountType)
	{
		if (!accountType.isIron())
		{
			return List.copyOf(sources);
		}
		return sources.stream().filter(s -> !"GE".equals(s.getType())).collect(Collectors.toUnmodifiableList());
	}

	/** True when {@code accountType} is an iron type, {@code sources} was non-empty, and filtering it left nothing. */
	public static boolean mustObtain(List<ItemSource> sources, AccountType accountType)
	{
		return accountType.isIron() && !sources.isEmpty() && sourcesFor(sources, accountType).isEmpty();
	}

	private GoalStatus questGoalStatus(Quest quest, QuestEntry entry, Snapshot snapshot, KnowledgeBase kb)
	{
		List<Gap> gaps = new ArrayList<>();
		List<Met> met = new ArrayList<>();
		boolean isIron = snapshot.getAccountType().isIron();

		for (SkillReq req : entry.getSkills())
		{
			if (req.isIronmanOnly() && !isIron)
			{
				continue;
			}
			addSkillGapIfShort(gaps, met, snapshot, req);
		}

		Map<String, QuestPrereqGap> prereqGaps = new LinkedHashMap<>();
		// Seed the recursion path with the quest's own name so a prerequisite cycle that loops back
		// to this quest is treated as "already visiting" rather than adding the quest as its own gap.
		Set<String> path = new LinkedHashSet<>();
		path.add(entry.getName());
		resolvePrereqs(entry.getPrereqs(), snapshot, kb, entry.getName(), true, prereqGaps, new ArrayList<>(), path);
		resolveStartedPrereqs(entry.getPrereqsStarted(), snapshot, kb, entry.getName(), prereqGaps);
		gaps.addAll(prereqGaps.values());
		addMetPrereqs(met, entry.getPrereqs(), snapshot, false);
		addMetPrereqs(met, entry.getPrereqsStarted(), snapshot, true);

		List<String> notes = new ArrayList<>(entry.getPrereqNotes());
		for (ItemReq req : entry.getItems())
		{
			addItemGapIfShort(gaps, met, notes, snapshot, kb, req.getName(), req.getQuantity());
		}

		if (entry.getQuestPointsRequired() != null)
		{
			addQuestPointsGapIfShort(gaps, met, snapshot, entry.getQuestPointsRequired());
		}
		if (entry.getKudosRequired() != null)
		{
			if (entry.getKudosRequired() > snapshot.getKudos())
			{
				gaps.add(new KudosGap(snapshot.getKudos(), entry.getKudosRequired()));
			}
			else
			{
				met.add(new Met(Met.Kind.KUDOS, "Kudos " + entry.getKudosRequired() + " (have " + snapshot.getKudos() + ")"));
			}
		}
		if (entry.getCombatLevelRequired() != null)
		{
			addCombatGapIfShort(gaps, met, snapshot, entry.getCombatLevelRequired(), false);
		}

		String goalId = "quest:" + entry.getId();
		int priority = kb.getPriorityOverrides().getOrDefault(goalId, QUEST_PRIORITY);
		Goal goal = new Goal(goalId, GoalCategory.QUEST, entry.getName(), WikiUrls.forTitle(entry.getWikiTitle()),
			priority, questStage(priority));
		return toGoalStatus(goal, gaps, notes, met);
	}

	/**
	 * The game's own per-tier completed-task counter varbit
	 * ({@code progress.getGameCount()}) is trusted over the bundled task-&gt;bit map when they
	 * disagree - an unmapped variable can cause a kb/game mismatch without a
	 * genuinely incomplete task. If the game reports every task done, no {@link DiaryTaskGap}s are
	 * emitted at all (the goal is "ready" - claim the reward - unless the tier varbit is already set,
	 * in which case {@link #evaluate} never calls this method for it). If the game reports more done
	 * than the kb's bit-derived count (but not all), the kb's task gaps are kept as-is (never
	 * shrunk - the specific completed task isn't known) with a note that one of them is already done.
	 */
	private GoalStatus diaryGoalStatus(DiaryTier tier, DiaryEntry entry, Snapshot snapshot, KnowledgeBase kb, DiaryTierProgress progress)
	{
		List<Gap> gaps = new ArrayList<>();
		List<String> notes = new ArrayList<>();
		Integer gameCount = progress == null ? null : progress.getGameCount();
		int total = entry.getTasks().size();

		int done = 0;
		if (gameCount == null || gameCount != total)
		{
			for (DiaryTask task : entry.getTasks())
			{
				if (task.getCompletion().isComplete(snapshot))
				{
					done++;
					continue;
				}
				gaps.add(diaryTaskGap(task, snapshot, kb));
			}
			if (gameCount != null && gameCount > progress.getCompleted())
			{
				notes.add("game reports " + gameCount + "/" + total + " done; one of these tasks is already complete");
			}
		}
		// The game's own count is trusted over the bit map whenever it's known (see above).
		int tasksDone = gameCount != null ? gameCount : done;
		List<Met> met = tasksDone == 0
			? List.of()
			: List.of(new Met(Met.Kind.DIARY, tasksDone + " of " + total + " tasks done", tasksDone, total));

		String area = diaryArea(tier);
		String tierName = diaryTierName(tier);
		String goalId = "diary:" + tier.name();
		int priority = kb.getPriorityOverrides().getOrDefault(goalId, DIARY_PRIORITY);
		Goal goal = new Goal(goalId, GoalCategory.DIARY, area + " " + tierName + " Diary",
			WikiUrls.forTitle(area + " Diary"), priority, DIARY_STAGE.get(tier));
		return toGoalStatus(goal, gaps, notes, met);
	}

	private DiaryTaskGap diaryTaskGap(DiaryTask task, Snapshot snapshot, KnowledgeBase kb)
	{
		List<Gap> inner = new ArrayList<>();
		List<Met> innerMet = new ArrayList<>(); // A task is a gap node: its own met requirements are not surfaced.
		boolean isIron = snapshot.getAccountType().isIron();

		for (SkillReq req : task.getSkills())
		{
			if (req.isIronmanOnly() && !isIron)
			{
				continue;
			}
			addSkillGapIfShort(inner, innerMet, snapshot, req);
		}

		Map<String, QuestPrereqGap> questGaps = new LinkedHashMap<>();
		List<String> extraNotes = new ArrayList<>();
		resolvePrereqs(task.getQuests(), snapshot, kb, "diary task " + task.getOrdinal(), false, questGaps, extraNotes, new LinkedHashSet<>());
		inner.addAll(questGaps.values());

		for (String itemName : task.getItems())
		{
			addItemGapIfShort(inner, innerMet, extraNotes, snapshot, kb, itemName, 1);
		}

		if (task.getCombatLevelRequired() != null)
		{
			addCombatGapIfShort(inner, innerMet, snapshot, task.getCombatLevelRequired(), false);
		}

		List<String> notes = new ArrayList<>(task.getNotes());
		notes.addAll(extraNotes);
		return new DiaryTaskGap(task.getOrdinal(), task.getText(), List.copyOf(inner), List.copyOf(notes));
	}

	/**
	 * Builds the goal status for one milestone, or empty when the milestone is already done.
	 * Completion is category-specific: {@code gear} - any
	 * {@code ownedIf} id held (bank ∪ inventory ∪ equipment, by id); {@code slayer_target} - the
	 * entry's Slayer skill requirement is met; {@code unlock}/{@code prayer}/{@code spellbook} -
	 * every requirement is met (no gaps). Bosses remain only for useful rewards or known unfinished
	 * combat achievements; green-logged bosses never offer gear progression. A house room is only
	 * completed via "Own it". A prerequisite milestone still open is a {@link PrerequisiteGap}.
	 */
	private Optional<GoalStatus> milestoneGoalStatus(MilestoneEntry entry, Snapshot snapshot, KnowledgeBase kb,
		Set<String> ownedManually, GearComparison comparison)
	{
		return milestoneGoalStatus(entry, snapshot, kb, ownedManually, comparison, false);
	}

	private Optional<GoalStatus> milestoneGoalStatus(MilestoneEntry entry, Snapshot snapshot, KnowledgeBase kb,
		Set<String> ownedManually, GearComparison comparison, boolean keepCompleted)
	{
		GoalObjective objective = ProgressionObjectives.evaluate(entry, snapshot, kb, comparison);
		if (!keepCompleted && (objective != null && !objective.hasReason()
			|| entry.getCategory() != MilestoneCategory.BOSS && ProgressionObjectives.providerGreenLogged(entry, snapshot)))
		{
			return Optional.empty();
		}
		PrayerUnlock prayer = PrayerUnlock.forMilestone(entry.getId());
		if (!keepCompleted && ((prayer != null && prayer.isUnlocked(snapshot))
			|| (entry.getSlayerReward() != null && snapshot.getSlayer().getUnlocks().contains(entry.getSlayerReward()))
			|| ("milestone:lunar-spellbook".equals(entry.getId()) && (snapshot.getSpellbook() == Spellbook.LUNAR
				|| snapshot.getQuests().get(Quest.LUNAR_DIPLOMACY) == QuestState.FINISHED))))
		{
			return Optional.empty();
		}
		List<Gap> gaps = new ArrayList<>();
		List<Met> met = new ArrayList<>();
		boolean isIron = snapshot.getAccountType().isIron();

		for (SkillReq req : entry.getSkills())
		{
			if (req.isIronmanOnly() && !isIron)
			{
				continue;
			}
			addSkillGapIfShort(gaps, met, snapshot, req);
		}

		Map<String, QuestPrereqGap> prereqGaps = new LinkedHashMap<>();
		resolvePrereqs(entry.getQuests(), snapshot, kb, entry.getName(), true, prereqGaps, new ArrayList<>(), new LinkedHashSet<>());
		gaps.addAll(prereqGaps.values());
		addMetPrereqs(met, entry.getQuests(), snapshot, false);

		for (DiaryRef diaryRef : entry.getDiaries())
		{
			if (!Boolean.TRUE.equals(snapshot.getDiaryTiers().get(diaryRef.getTier())))
			{
				gaps.add(new DiaryTierGap(diaryRef.getTier()));
			}
			else
			{
				met.add(new Met(Met.Kind.DIARY, diaryArea(diaryRef.getTier()) + " " + diaryTierName(diaryRef.getTier()) + " Diary"));
			}
		}

		if (entry.getCombatLevel() != null)
		{
			addCombatGapIfShort(gaps, met, snapshot, entry.getCombatLevel(), false);
		}
		if (entry.getQuestPoints() != null)
		{
			addQuestPointsGapIfShort(gaps, met, snapshot, entry.getQuestPoints());
		}

		for (ItemReq req : entry.getItems())
		{
			addMilestoneItemGapIfShort(gaps, met, snapshot, kb, req);
		}

		if (entry.getSlayerReward() != null)
		{
			int have = snapshot.getSlayer().getPoints();
			int need = entry.getSlayerPoints();
			if (have < need) gaps.add(new SlayerPointsGap(have, need));
			else met.add(new Met(Met.Kind.SLAYER_POINTS, "Slayer points " + have + "/" + need));
		}
		SlayerReward requiredUnlock = entry.getRequiredSlayerUnlock();
		if (requiredUnlock != null)
		{
			if (snapshot.getSlayer().getUnlocks().contains(requiredUnlock))
			{
				met.add(new Met(Met.Kind.UNLOCK, requiredUnlock.getDisplayName()));
			}
			else
			{
				String link = kb.getMilestones().stream().filter(m -> m.getSlayerReward() == requiredUnlock)
					.map(MilestoneEntry::getId).findFirst().orElse(null);
				gaps.add(new SlayerUnlockGap(requiredUnlock, link));
			}
		}

		if (entry.getRecommended() != null)
		{
			addRecommendedGaps(gaps, met, entry.getRecommended(), snapshot, comparison);
		}

		// A prerequisite milestone that is still a goal itself (not owned, not done) is a gap
		// on the dependant; the prerequisite's own status decides, so "Own it" on it counts as met.
		if (entry.getPrerequisite() != null)
		{
			MilestoneEntry prerequisite = kb.milestoneById(entry.getPrerequisite());
			boolean prerequisiteMissing = prerequisite.getCategory() == MilestoneCategory.GEAR
				? !ownedManually.contains(prerequisite.getId()) && (prerequisite.getOwnedIf().isEmpty()
					|| prerequisite.getOwnedIf().stream().filter(item -> comparison.owns(item.getIds())).count()
						< prerequisite.getOwnedIfMin())
				: milestoneGoalStatus(prerequisite, snapshot, kb, ownedManually, comparison).isPresent();
			if (prerequisiteMissing)
			{
				gaps.add(new PrerequisiteGap(prerequisite.getId(), prerequisite.getName()));
			}
			else
			{
				met.add(new Met(Met.Kind.PREREQUISITE, prerequisite.getName()));
			}
		}

		boolean gearOwned = !entry.getOwnedIf().isEmpty()
			&& entry.getOwnedIf().stream().filter(item -> comparison.owns(item.getIds())).count() >= entry.getOwnedIfMin();

		boolean done;
		switch (entry.getCategory())
		{
			case GEAR:
				done = gearOwned;
				break;
			case SLAYER_TARGET:
				done = slayerLevelMet(entry, snapshot);
				break;
			case BOSS:
			case POH: // A built room is never client-visible; only "Own it" finishes it.
				done = false;
				break;
			default: // UNLOCK, PRAYER, SPELLBOOK
				done = prayer == null && entry.getSlayerReward() == null && gaps.isEmpty();
				break;
		}
		// A manual "Own it"/"Done it" override finishes any milestone/slayer-target/boss
		// goal, whatever its category's own completion rule says - the shared ownership predicate
		// below already covers GEAR, so this only adds anything for the other three categories.
		done = done || isOwned(entry, snapshot, ownedManually);
		if (done && !keepCompleted)
		{
			return Optional.empty();
		}

		int priority = kb.getPriorityOverrides().getOrDefault(entry.getId(), entry.getPriority());
		Goal goal = new Goal(entry.getId(), mapMilestoneCategory(entry.getCategory()), entry.getName(),
			WikiUrls.forTitle(entry.getWikiTitle()), priority, entry.getStage());
		boolean bankUnknown = anyBankUnknown(gaps);
		return Optional.of(new GoalStatus(goal, List.copyOf(gaps), gaps.isEmpty(), bankUnknown, entry.getNotes(),
			List.copyOf(met), List.of(), null, 0, List.of(), objective));
	}

	/** Acquisition requirements remain useful when a broad gear milestone owns a different piece. */
	GoalStatus providerStatus(String id, Snapshot snapshot, KnowledgeBase kb, Set<String> ownedManually, GearComparison comparison)
	{
		MilestoneEntry milestone = kb.milestoneById(id);
		if (milestone != null)
		{
			return milestoneGoalStatus(milestone, snapshot, kb, ownedManually, comparison, true).orElseThrow();
		}
		QuestEntry entry = kb.getQuests().stream().filter(q -> id.equals("quest:" + q.getId())).findFirst().orElseThrow();
		Quest quest = QUESTS_BY_ID.get(entry.getId());
		if (snapshot.getQuests().get(quest) != QuestState.FINISHED)
		{
			GoalStatus requirements = questGoalStatus(quest, entry, snapshot, kb);
			List<Gap> gaps = new ArrayList<>(requirements.getGaps());
			boolean startHere = gaps.stream().noneMatch(g -> g instanceof QuestPrereqGap);
			gaps.add(new QuestPrereqGap(quest, snapshot.getQuests().getOrDefault(quest, QuestState.NOT_STARTED),
				startHere, false, requirements.getGoal().getWikiUrl()));
			return new GoalStatus(requirements.getGoal(), List.copyOf(gaps), false, requirements.isBankUnknown(),
				requirements.getNotes(), requirements.getMet(), List.of(), null, 0);
		}
		int priority = kb.getPriorityOverrides().getOrDefault(id, QUEST_PRIORITY);
		return new GoalStatus(new Goal(id, GoalCategory.QUEST, entry.getName(), WikiUrls.forTitle(entry.getWikiTitle()),
			priority, questStage(priority)), List.of(), true, false, List.of());
	}

	/**
	 * Adds gaps for a milestone's {@code recommended} profile - an "actually ready"
	 * layer on top of hard requirements, e.g. a boss's recommended combat stats and gear. A boss (or
	 * any milestone) is only {@code ready} once these are met too, since they land in the same
	 * {@code gaps} list as the hard requirements.
	 */
	private static void addRecommendedGaps(List<Gap> gaps, List<Met> met, RecommendedProfile recommended,
		Snapshot snapshot, GearComparison comparison)
	{
		for (PrayerUnlock prayer : recommended.getPrayers())
		{
			if (prayer.isUnlocked(snapshot)) met.add(new Met(Met.Kind.RECOMMENDED_PRAYER, prayer.getDisplayName()));
			else gaps.add(new PrayerUnlockGap(prayer, true));
		}
		for (RecommendedSkill req : recommended.getSkills())
		{
			SkillState state = snapshot.getSkills().get(req.getSkill());
			int have = state == null ? 1 : state.getLevel();
			if (have >= req.getLevel())
			{
				met.add(new Met(Met.Kind.RECOMMENDED_SKILL, skillLabel(req.getSkill(), req.getLevel(), have)));
				continue;
			}
			long currentXp = state == null ? 0 : state.getXp();
			long xpDelta = Experience.getXpForLevel(req.getLevel()) - currentXp;
			gaps.add(new SkillLevelGap(req.getSkill(), have, req.getLevel(), xpDelta, false, null, true));
		}

		if (recommended.getCombatLevel() != null)
		{
			addCombatGapIfShort(gaps, met, snapshot, recommended.getCombatLevel(), true);
		}

		for (GearRequirement requirement : recommended.getGear())
		{
			String role = requirement.getRole();
			String style = role.startsWith("melee-") ? "melee" : role.startsWith("ranged-") ? "ranged"
				: role.startsWith("magic-") ? "magic" : null;
			String coveringName = null;
			boolean ownershipKnown = true;
			for (OwnedItem item : requirement.getAlternatives())
			{
				coveringName = comparison.coveringName(item.getIds(), style);
				if (coveringName != null) break;
				ownershipKnown &= comparison.ownershipKnown(item.getIds());
			}
			if (coveringName != null)
			{
				met.add(new Met(Met.Kind.RECOMMENDED_GEAR, requirement.getRole() + ": " + coveringName));
			}
			else
			{
				gaps.add(new GearGap(requirement.getRole(), requirement.getAlternatives(), !ownershipKnown));
			}
		}
	}

	private static void addCombatGapIfShort(List<Gap> gaps, List<Met> met, Snapshot snapshot, int need, boolean recommended)
	{
		int have = snapshot.combatLevel();
		if (need > have)
		{
			gaps.add(new CombatLevelGap(have, need, recommended));
		}
		else
		{
			met.add(new Met(Met.Kind.COMBAT, "Combat " + need + " (have " + have + ")"));
		}
	}

	private static void addQuestPointsGapIfShort(List<Gap> gaps, List<Met> met, Snapshot snapshot, int need)
	{
		int have = snapshot.getQuestPoints();
		if (need > have)
		{
			gaps.add(new QuestPointsGap(have, need));
		}
		else
		{
			met.add(new Met(Met.Kind.QUEST_POINTS, "Quest points " + need + " (have " + have + ")"));
		}
	}

	/**
	 * Records a {@link Met.Kind#QUEST} for each of {@code names} that is finished (or, when
	 * {@code startedOnly}, merely started) - direct prerequisites only, never the transitive
	 * closure {@link #resolvePrereqs} walks for gaps. A name absent from RuneLite's quest list is
	 * skipped here; the gap side has already thrown or noted it.
	 */
	private static void addMetPrereqs(List<Met> met, List<String> names, Snapshot snapshot, boolean startedOnly)
	{
		for (String name : names)
		{
			Quest quest = QUESTS_BY_NAME.get(name);
			if (quest == null)
			{
				continue;
			}
			QuestState state = snapshot.getQuests().getOrDefault(quest, QuestState.NOT_STARTED);
			if (state == QuestState.FINISHED || (startedOnly && state != QuestState.NOT_STARTED))
			{
				met.add(new Met(Met.Kind.QUEST, name));
			}
		}
	}

	private static String skillLabel(Skill skill, int need, int have)
	{
		return skill.getName() + " " + need + " (have " + have + ")";
	}

	private static void addMilestoneItemGapIfShort(List<Gap> gaps, List<Met> met, Snapshot snapshot, KnowledgeBase kb, ItemReq req)
	{
		Integer have = sumHaveByIds(snapshot, req.getIds());
		if (have != null && have >= req.getQuantity())
		{
			met.add(new Met(Met.Kind.ITEM, itemLabel(req.getName(), req.getQuantity())));
			return;
		}
		List<ItemSource> rawSources = req.getSources().stream()
			.map(s -> new ItemSource(s, "", ""))
			.collect(Collectors.toList());
		List<ItemSource> sources = sourcesFor(rawSources, snapshot.getAccountType());
		boolean mustObtain = mustObtain(rawSources, snapshot.getAccountType());
		gaps.add(new ItemGap(req.getName(), have, req.getQuantity(), sources, mustObtain, wikiUrlFor(kb, req.getName()), req.getId()));
	}

	/** Sums bank + inventory + equipment + group storage across every id in {@code itemIds} (a requirement item's wiki-variant ids). */
	private static Integer sumHaveByIds(Snapshot snapshot, List<Integer> itemIds)
	{
		if (!snapshot.isBankKnown())
		{
			return null;
		}
		int sum = 0;
		for (int itemId : itemIds)
		{
			sum += snapshot.getBank().getOrDefault(itemId, 0)
				+ snapshot.getInventory().getOrDefault(itemId, 0)
				+ snapshot.getRunePouch().getOrDefault(itemId, 0)
				+ snapshot.getEquipment().getOrDefault(itemId, 0)
				+ snapshot.getGroupStorage().getOrDefault(itemId, 0);
		}
		return sum;
	}


	/**
	 * Shared "owns this milestone" predicate consulted by both this class's GEAR-category
	 * done-check and {@link StageEstimator}'s stage-N gear-milestone count: true when any of
	 * {@code entry.getOwnedIf()}'s variant ids is held (bank/inventory/equipment, {@link #anyIdHeld})
	 * or the player has manually marked the milestone owned (some gear - a house cape rack cosmetic,
	 * a group-ironman shared-storage item - never appears in a client-visible container).
	 */
	static boolean isOwned(MilestoneEntry entry, Snapshot snapshot, Set<String> ownedManually)
	{
		if (ownedManually.contains(entry.getId())) return true;
		int held = 0;
		for (OwnedItem item : entry.getOwnedIf())
		{
			if (anyIdHeld(item.getIds(), snapshot) || !ownedManually.isEmpty() && ownedManually.stream()
				.anyMatch(id -> id.startsWith("gear:") && item.getIds().stream().anyMatch(variant -> id.endsWith(":" + variant))))
			{
				held++;
			}
		}
		return !entry.getOwnedIf().isEmpty() && held >= entry.getOwnedIfMin();
	}

	/**
	 * How many distinct {@code ownedIf} items of {@code entry} are held (any variant id, any
	 * container) - an outfit is owned only once {@code ownedIfMin} of its pieces are, and the
	 * "2/4 pieces" why-clause shows the count.
	 */
	static int ownedIfHeld(MilestoneEntry entry, Snapshot snapshot)
	{
		int held = 0;
		for (OwnedItem owned : entry.getOwnedIf())
		{
			if (anyIdHeld(owned.getIds(), snapshot))
			{
				held++;
			}
		}
		return held;
	}

	/**
	 * Whether any of {@code itemIds} is held (bank &cup; inventory &cup; equipment &cup; group
	 * storage) in any quantity. Shared with {@link com.signpost.engine.StageEstimator}'s
	 * gear-milestone-owned check and {@link WhyBuilder}'s biggest-upgrade check, since all need the
	 * exact same "any variant id, any container" rule. Unseen group storage is simply empty:
	 * it never makes ownership unknown the way an unseen bank does.
	 */
	static boolean anyIdHeld(List<Integer> itemIds, Snapshot snapshot)
	{
		for (int itemId : itemIds)
		{
			if (snapshot.getInventory().getOrDefault(itemId, 0) > 0
				|| snapshot.getRunePouch().getOrDefault(itemId, 0) > 0
				|| snapshot.getEquipment().getOrDefault(itemId, 0) > 0
				|| (snapshot.isGroupStorageEnabled() && snapshot.getGroupStorage().getOrDefault(itemId, 0) > 0)
				|| snapshot.getBank().getOrDefault(itemId, 0) > 0)
			{
				return true;
			}
		}
		return false;
	}

	private static boolean slayerLevelMet(MilestoneEntry entry, Snapshot snapshot)
	{
		return entry.getSkills().stream()
			.filter(s -> s.getSkill() == Skill.SLAYER)
			.findFirst()
			.map(s -> skillLevel(snapshot, Skill.SLAYER) >= s.getLevel())
			.orElse(false);
	}

	private static int skillLevel(Snapshot snapshot, Skill skill)
	{
		SkillState state = snapshot.getSkills().get(skill);
		return state == null ? 1 : state.getLevel();
	}

	private static GoalCategory mapMilestoneCategory(MilestoneCategory category)
	{
		switch (category)
		{
			case SLAYER_TARGET:
				return GoalCategory.SLAYER_TARGET;
			case BOSS:
				return GoalCategory.BOSS;
			default: // GEAR, UNLOCK, PRAYER, SPELLBOOK, POH
				return GoalCategory.MILESTONE;
		}
	}

	private void addSkillGapIfShort(List<Gap> gaps, List<Met> met, Snapshot snapshot, SkillReq req)
	{
		SkillState state = snapshot.getSkills().get(req.getSkill());
		int have = state == null ? 1 : state.getLevel();
		if (have >= req.getLevel())
		{
			met.add(new Met(Met.Kind.SKILL, skillLabel(req.getSkill(), req.getLevel(), have)));
			return;
		}

		long currentXp = state == null ? 0 : state.getXp();
		long xpDelta = Experience.getXpForLevel(req.getLevel()) - currentXp;

		Integer boostableFrom = null;
		if (req.isBoostable())
		{
			int floor = req.getLevel() - boostTable.maxBoost(req.getSkill());
			if (have >= floor)
			{
				boostableFrom = floor;
			}
		}
		gaps.add(new SkillLevelGap(req.getSkill(), have, req.getLevel(), xpDelta, req.isBoostable(), boostableFrom, false));
	}

	/**
	 * A quest/diary item requirement by name. A name the knowledge base marks {@code generic}
	 * ("Pickaxe", "Combat gear", "Light source": a category or prose reference, not an in-game item
	 * name) can never be matched against the bank, so it becomes a note rather than an
	 * {@link ItemGap} - it must not keep a goal from "Ready now" or become a "Get pickaxe" next
	 * step. A name with no material entry at all is matched as before.
	 */
	private static void addItemGapIfShort(List<Gap> gaps, List<Met> met, List<String> notes, Snapshot snapshot, KnowledgeBase kb, String name, int need)
	{
		MaterialEntry material = kb.materialByName(name);
		if (material != null && material.isGeneric())
		{
			notes.add("Bring: " + itemLabel(name, need) + " (see wiki)");
			return;
		}
		Integer have = sumHave(snapshot, name);
		if (have == null || have < need)
		{
			gaps.add(new ItemGap(name, have, need, List.of(), false, material == null ? null : material.getWikiUrl(),
				material == null ? null : material.getId()));
		}
		else
		{
			met.add(new Met(Met.Kind.ITEM, itemLabel(name, need)));
		}
	}

	private static String itemLabel(String name, int need)
	{
		return name + (need > 1 ? " ×" + need : "");
	}

	private static String wikiUrlFor(KnowledgeBase kb, String itemName)
	{
		MaterialEntry material = kb.materialByName(itemName);
		return material == null ? WikiUrls.forTitle(itemName) : material.getWikiUrl();
	}

	/**
	 * Depth-first, cycle-safe resolution of prerequisite quest names into {@link QuestPrereqGap}s,
	 * deduped by name via {@code gapsByName} (each quest at most once). A name already on
	 * {@code path} (an ancestor in the current recursion) is not re-descended into, so a
	 * prerequisite cycle can't loop forever. When {@code throwOnUnknown} is false, a name absent
	 * from the knowledge base becomes a note in {@code extraNotes} instead of a failure (diary task
	 * quest text is looser than quest prerequisite data). Returns true if any of {@code names}
	 * resolved to an unfinished quest, so the caller knows whether it has an unfinished prerequisite
	 * of its own (and so is not itself {@code startHere}).
	 */
	private static boolean resolvePrereqs(List<String> names, Snapshot snapshot, KnowledgeBase kb, String forName, boolean throwOnUnknown,
		Map<String, QuestPrereqGap> gapsByName, List<String> extraNotes, Set<String> path)
	{
		boolean anyUnfinished = false;
		for (String name : names)
		{
			QuestEntry entry = kb.questByName(name);
			Quest quest = entry == null ? null : QUESTS_BY_NAME.get(name);
			if (entry == null || quest == null)
			{
				if (throwOnUnknown)
				{
					throw new IllegalStateException("Unknown prerequisite quest \"" + name + "\" for quest \"" + forName + "\"");
				}
				extraNotes.add("Quest requirement (see wiki): " + name);
				continue;
			}

			QuestState state = snapshot.getQuests().getOrDefault(quest, QuestState.NOT_STARTED);
			if (state == QuestState.FINISHED)
			{
				continue;
			}
			anyUnfinished = true;

			QuestPrereqGap existing = gapsByName.get(name);
			if ((existing != null && !existing.isStartOnly()) || !path.add(name))
			{
				continue;
			}
			boolean hasUnfinishedPrereq = resolvePrereqs(entry.getPrereqs(), snapshot, kb, name, throwOnUnknown, gapsByName, extraNotes, path);
			resolveStartedPrereqs(entry.getPrereqsStarted(), snapshot, kb, name, gapsByName);
			hasUnfinishedPrereq = hasUnfinishedPrereq || entry.getPrereqsStarted().stream()
				.anyMatch(started -> snapshot.getQuests().getOrDefault(QUESTS_BY_NAME.get(started), QuestState.NOT_STARTED) == QuestState.NOT_STARTED);
			path.remove(name);
			gapsByName.put(name, new QuestPrereqGap(quest, state, !hasUnfinishedPrereq, false, wikiUrlFor(entry)));
		}
		return anyUnfinished;
	}

	/**
	 * Resolves "must have started" prerequisite quest names (the wiki's {@code Started:} prefix)
	 * into {@link QuestPrereqGap}s, satisfied by any state other than {@code NOT_STARTED}. Never
	 * recurses into the started quest's own prerequisites - starting it is the whole requirement -
	 * so every gap produced here is unconditionally {@code startHere}. Every name has already been
	 * validated at {@link KnowledgeBase} load time to be a known quest name.
	 */
	private static void resolveStartedPrereqs(List<String> names, Snapshot snapshot, KnowledgeBase kb, String forName,
		Map<String, QuestPrereqGap> gapsByName)
	{
		for (String name : names)
		{
			Quest quest = QUESTS_BY_NAME.get(name);
			if (quest == null)
			{
				throw new IllegalStateException("Unknown started prerequisite quest \"" + name + "\" for quest \"" + forName + "\"");
			}
			if (gapsByName.containsKey(name))
			{
				continue;
			}
			QuestState state = snapshot.getQuests().getOrDefault(quest, QuestState.NOT_STARTED);
			if (state != QuestState.NOT_STARTED)
			{
				continue;
			}
			gapsByName.put(name, new QuestPrereqGap(quest, state, true, true, wikiUrlFor(kb.questByName(name))));
		}
	}

	/** Same construction {@link Goal#getWikiUrl()} uses (spaces to underscores, no other encoding) - never {@code Quest.getName()}, which 404s for a subquest whose wiki title differs (e.g. a Recipe for Disaster subquest). */
	private static String wikiUrlFor(QuestEntry entry)
	{
		return WikiUrls.forTitle(entry.getWikiTitle());
	}

	private static Integer sumHave(Snapshot snapshot, String itemName)
	{
		if (!snapshot.isBankKnown())
		{
			return null;
		}
		return sumByName(snapshot.getBank(), snapshot.getItemNames(), itemName)
			+ sumByName(snapshot.getInventory(), snapshot.getItemNames(), itemName)
			+ sumByName(snapshot.getRunePouch(), snapshot.getItemNames(), itemName)
			+ sumByName(snapshot.getEquipment(), snapshot.getItemNames(), itemName)
			+ sumByName(snapshot.getGroupStorage(), snapshot.getItemNames(), itemName);
	}

	private static int sumByName(Map<Integer, Integer> container, Map<Integer, String> itemNames, String name)
	{
		int sum = 0;
		for (Map.Entry<Integer, Integer> e : container.entrySet())
		{
			String itemName = itemNames.get(e.getKey());
			if (itemName != null && itemName.equalsIgnoreCase(name))
			{
				sum += e.getValue();
			}
		}
		return sum;
	}

	private static GoalStatus toGoalStatus(Goal goal, List<Gap> gaps, List<String> notes, List<Met> met)
	{
		return new GoalStatus(goal, List.copyOf(gaps), gaps.isEmpty(), anyBankUnknown(gaps), List.copyOf(notes), List.copyOf(met), List.of(), null, 0);
	}

	private static boolean anyBankUnknown(List<Gap> gaps)
	{
		for (Gap gap : gaps)
		{
			if (gap instanceof ItemGap && ((ItemGap) gap).getHave() == null)
			{
				return true;
			}
			if (gap instanceof GearGap && ((GearGap) gap).isBankUnknown())
			{
				return true;
			}
			if (gap instanceof DiaryTaskGap && anyBankUnknown(((DiaryTaskGap) gap).getGaps()))
			{
				return true;
			}
		}
		return false;
	}

	private static String diaryArea(DiaryTier tier)
	{
		return titleCase(tier.name().substring(0, tier.name().lastIndexOf('_')));
	}

	private static String diaryTierName(DiaryTier tier)
	{
		return titleCase(tier.name().substring(tier.name().lastIndexOf('_') + 1));
	}

	private static String titleCase(String s)
	{
		return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1).toLowerCase();
	}

	private static Map<Integer, Quest> buildQuestsById()
	{
		Map<Integer, Quest> m = new LinkedHashMap<>();
		for (Quest quest : Quest.values())
		{
			m.put(quest.getId(), quest);
		}
		return Map.copyOf(m);
	}

	/** The RuneLite {@link Quest} with exactly this name, or null - the mapping every quest name in the KB resolves through. */
	static Quest questByName(String name)
	{
		return QUESTS_BY_NAME.get(name);
	}

	private static Map<String, Quest> buildQuestsByName()
	{
		Map<String, Quest> m = new LinkedHashMap<>();
		for (Quest quest : Quest.values())
		{
			m.put(quest.getName(), quest);
		}
		return Map.copyOf(m);
	}
}

package com.signpost.engine;

import com.signpost.engine.model.DiaryTaskGap;
import com.signpost.engine.model.Gap;
import com.signpost.engine.model.GoalStatus;
import com.signpost.engine.model.ItemGap;
import com.signpost.engine.model.NextStep;
import com.signpost.engine.model.QuestPrereqGap;
import com.signpost.engine.model.Route;
import com.signpost.engine.model.SkillLevelGap;
import com.signpost.kb.KnowledgeBase;
import com.signpost.snapshot.SkillState;
import com.signpost.snapshot.Snapshot;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Experience;
import net.runelite.api.Skill;

/**
 * "Do this next": picks one unmet requirement from a {@link GoalStatus}, in order:
 * (a) a start-here quest prereq, (b) the smallest-xp-delta skill gap with a bank-covered route,
 * (c) the smallest-xp-delta skill gap overall with its partial route, (d) the first missing
 * item. {@code none()} when the goal has no gaps left. No {@link net.runelite.api.Client}, no I/O.
 */
public final class NextStepPicker
{
	public NextStep next(GoalStatus status, Snapshot snapshot, KnowledgeBase kb)
	{
		List<QuestPrereqGap> quests = new ArrayList<>();
		List<SkillLevelGap> skills = new ArrayList<>();
		List<ItemGap> items = new ArrayList<>();
		collect(status.getGaps(), quests, skills, items);

		for (QuestPrereqGap gap : quests)
		{
			if (gap.isStartHere())
			{
				return NextStep.quest(gap);
			}
		}

		Map<Integer, Integer> bankAll = bankAll(snapshot);
		Map<List<Object>, Route> cache = new HashMap<>();

		SkillLevelGap covered = null;
		Route coveredRoute = null;
		for (SkillLevelGap gap : skills)
		{
			Route route = routeFor(gap, snapshot, bankAll, kb, cache);
			if (route.getUncoveredXp() == 0 && (covered == null || gap.getXpDelta() < covered.getXpDelta()))
			{
				covered = gap;
				coveredRoute = route;
			}
		}
		if (covered != null)
		{
			return NextStep.skill(covered, coveredRoute);
		}

		SkillLevelGap smallest = null;
		Route smallestRoute = null;
		for (SkillLevelGap gap : skills)
		{
			if (smallest == null || gap.getXpDelta() < smallest.getXpDelta())
			{
				smallest = gap;
				smallestRoute = routeFor(gap, snapshot, bankAll, kb, cache);
			}
		}
		if (smallest != null)
		{
			return NextStep.skill(smallest, smallestRoute);
		}

		if (!items.isEmpty())
		{
			return NextStep.item(items.get(0));
		}

		return NextStep.none();
	}

	private static Route routeFor(SkillLevelGap gap, Snapshot snapshot, Map<Integer, Integer> bankAll, KnowledgeBase kb,
		Map<List<Object>, Route> cache)
	{
		long toXp = Experience.getXpForLevel(gap.getNeed());
		List<Object> key = List.of(gap.getSkill(), toXp);
		Route cached = cache.get(key);
		if (cached != null)
		{
			return cached;
		}
		Route route = RoutePlanner.route(gap.getSkill(), currentXp(snapshot, gap.getSkill()), toXp, bankAll, kb);
		cache.put(key, route);
		return route;
	}

	private static long currentXp(Snapshot snapshot, Skill skill)
	{
		SkillState state = snapshot.getSkills().get(skill);
		return state == null ? 0 : state.getXp();
	}

	/**
	 * Bank &cup; inventory &cup; equipment &cup; group storage by item id - the materials a
	 * {@link RoutePlanner} route may draw on (the shared storage is one pool with the bank;
	 * {@link Snapshot#groupStorageShare} gives the per-item breakdown). Shared with {@link SkillTargetSynthesiser}.
	 */
	static Map<Integer, Integer> bankAll(Snapshot snapshot)
	{
		Map<Integer, Integer> result = new LinkedHashMap<>();
		mergeInto(result, snapshot.getBank());
		mergeInto(result, snapshot.getGroupStorage());
		mergeInto(result, snapshot.getInventory());
		mergeInto(result, snapshot.getRunePouch());
		mergeInto(result, snapshot.getEquipment());
		return result;
	}

	private static void mergeInto(Map<Integer, Integer> into, Map<Integer, Integer> from)
	{
		from.forEach((id, qty) -> into.merge(id, qty, Integer::sum));
	}

	/** Recursively finds every {@link QuestPrereqGap}/{@link SkillLevelGap}/{@link ItemGap}, including inside {@link DiaryTaskGap}s. */
	private static void collect(List<Gap> gaps, List<QuestPrereqGap> quests, List<SkillLevelGap> skills, List<ItemGap> items)
	{
		for (Gap gap : gaps)
		{
			if (gap instanceof QuestPrereqGap)
			{
				quests.add((QuestPrereqGap) gap);
			}
			else if (gap instanceof SkillLevelGap)
			{
				skills.add((SkillLevelGap) gap);
			}
			else if (gap instanceof ItemGap)
			{
				items.add((ItemGap) gap);
			}
			else if (gap instanceof DiaryTaskGap)
			{
				collect(((DiaryTaskGap) gap).getGaps(), quests, skills, items);
			}
		}
	}
}

package com.signpost.engine;

import com.signpost.kb.KnowledgeBase;
import com.signpost.kb.MilestoneCategory;
import com.signpost.kb.MilestoneEntry;
import com.signpost.snapshot.Snapshot;
import java.util.Set;
import net.runelite.api.QuestState;

/**
 * Derives the account's progression stage (1 early game .. 4 endgame) from combat level, total
 * level, finished quest count, and owned gear milestones. Every threshold lives
 * here, in one place:
 *
 * <ul>
 *   <li>Stage 4: owns &ge; 2 distinct stage-4 gear milestones, or (combat &ge; 120 and owns &ge; 2
 *       stage-3 gear milestones).
 *   <li>Stage 3 (else): owns &ge; 2 stage-3 gear milestones, or (combat &ge; 110 and total level
 *       &ge; 1900), or &ge; 190 quests finished.
 *   <li>Stage 2 (else): combat &ge; 85, or total level &ge; 1400, or &ge; 120 quests finished, or
 *       owns &ge; 2 stage-2 gear milestones.
 *   <li>Stage 1 (else).
 * </ul>
 *
 * "Owns" a gear milestone means any of its {@code ownedIf} item ids is held in bank, inventory, or
 * equipment (bank checked only when {@link Snapshot#isBankKnown()}), or the milestone id is in the
 * player's manually-marked-owned set ({@link GapEngine#isOwned}). Pure: no
 * {@link net.runelite.api.Client}, no I/O.
 */
public final class StageEstimator
{
	private StageEstimator()
	{
	}

	public static int estimate(Snapshot snapshot, KnowledgeBase kb)
	{
		return estimate(snapshot, kb, Set.of());
	}

	/** As {@link #estimate(Snapshot, KnowledgeBase)}, but a manually-owned gear milestone counts as owned too. */
	public static int estimate(Snapshot snapshot, KnowledgeBase kb, Set<String> ownedManually)
	{
		int combat = snapshot.combatLevel();
		int totalLevel = totalLevel(snapshot);
		int questsFinished = questsFinished(snapshot);

		if (ownedGearMilestoneCount(kb, snapshot, 4, ownedManually) >= 2
			|| (combat >= 120 && ownedGearMilestoneCount(kb, snapshot, 3, ownedManually) >= 2))
		{
			return 4;
		}
		if (ownedGearMilestoneCount(kb, snapshot, 3, ownedManually) >= 2 || (combat >= 110 && totalLevel >= 1900) || questsFinished >= 190)
		{
			return 3;
		}
		if (combat >= 85 || totalLevel >= 1400 || questsFinished >= 120 || ownedGearMilestoneCount(kb, snapshot, 2, ownedManually) >= 2)
		{
			return 2;
		}
		return 1;
	}

	private static int totalLevel(Snapshot snapshot)
	{
		return snapshot.getSkills().values().stream().mapToInt(s -> s.getLevel()).sum();
	}

	private static int questsFinished(Snapshot snapshot)
	{
		return (int) snapshot.getQuests().values().stream().filter(state -> state == QuestState.FINISHED).count();
	}

	private static int ownedGearMilestoneCount(KnowledgeBase kb, Snapshot snapshot, int stage, Set<String> ownedManually)
	{
		int count = 0;
		for (MilestoneEntry entry : kb.getMilestones())
		{
			if (entry.getCategory() == MilestoneCategory.GEAR && entry.getStage() == stage && GapEngine.isOwned(entry, snapshot, ownedManually))
			{
				count++;
			}
		}
		return count;
	}
}

package com.signpost.engine;

import com.signpost.engine.model.GoalObjective;
import com.signpost.engine.model.RewardTarget;
import com.signpost.kb.BossReward;
import com.signpost.kb.GearLadder;
import com.signpost.kb.KnowledgeBase;
import com.signpost.kb.MilestoneCategory;
import com.signpost.kb.MilestoneEntry;
import com.signpost.kb.OwnedItem;
import com.signpost.kb.RewardValue;
import com.signpost.snapshot.BossProgress;
import com.signpost.snapshot.CombatAchievementTask;
import com.signpost.snapshot.Snapshot;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/** Remaining gains are evaluated against the account, independently of entry readiness. */
final class ProgressionObjectives
{
	private static final Comparator<RewardTarget> TARGET_ORDER = Comparator.comparing(RewardTarget::isOwnershipUnknown)
		.thenComparing(RewardTarget::getValue);
	private static final Comparator<CombatAchievementTask> TASK_ORDER = Comparator.comparingInt(CombatAchievementTask::getTier)
		.thenComparingInt(CombatAchievementTask::getId);

	private ProgressionObjectives() {}

	static GoalObjective evaluate(MilestoneEntry entry, Snapshot snapshot, KnowledgeBase kb, GearComparison gear)
	{
		if (entry.getCategory() != MilestoneCategory.BOSS && entry.getCategory() != MilestoneCategory.GEAR) return null;
		BossProgress progress = snapshot.getBossProgress().get(entry.getId());
		if (entry.getCategory() == MilestoneCategory.GEAR && entry.getOwnedIf().isEmpty()) return null;
		boolean boss = entry.getCategory() == MilestoneCategory.BOSS;
		if (boss && progress == null && entry.getBossRewards().isEmpty()) return null;
		boolean green = boss ? progress != null && Boolean.TRUE.equals(progress.getGreenLogged()) : providerGreenLogged(entry, snapshot);
		List<RewardTarget> targets = new ArrayList<>();
		if (!green)
		{
			if (boss)
			{
				for (BossReward reward : entry.getBossRewards())
				{
					if (!covered(reward, snapshot, gear)) targets.add(target(reward, reward.getName(), reward.getIds(), kb, gear));
				}
			}
			else
			{
				MilestoneEntry provider = entry.getObtainedFrom() == null ? null : kb.milestoneById(entry.getObtainedFrom());
				for (OwnedItem item : entry.getOwnedIf())
				{
					if (gear.covers(item.getIds())) continue;
					BossReward reward = matchingReward(provider, item.getIds(), kb);
					if (reward != null)
					{
						targets.add(target(reward, item.getName(), item.getIds(), kb, gear));
					}
					else
					{
						targets.add(gearTarget(entry, item.getName(), item.getIds(), kb, gear));
					}
				}
			}
		}
		targets.sort(TARGET_ORDER);
		List<CombatAchievementTask> tasks = progress != null && progress.isCombatAchievementsKnown()
			? new ArrayList<>(progress.getRemainingTasks()) : new ArrayList<>();
		tasks.sort(TASK_ORDER);
		return new GoalObjective(targets, tasks, green, progress != null && progress.isCombatAchievementsKnown(),
			targets.stream().anyMatch(RewardTarget::isOwnershipUnknown));
	}

	static GoalObjective upgrade(MilestoneEntry provider, GearLadder.Rung rung, KnowledgeBase kb, GearComparison gear)
	{
		MilestoneEntry rewardSource = provider.getCategory() == MilestoneCategory.BOSS ? provider
			: provider.getObtainedFrom() == null ? null : kb.milestoneById(provider.getObtainedFrom());
		BossReward reward = matchingReward(rewardSource, rung.getVariants(), kb);
		RewardTarget target = reward == null ? gearTarget(provider, rung.getName(), rung.getVariants(), kb, gear)
			: target(reward, rung.getName(), rung.getVariants(), kb, gear);
		return new GoalObjective(List.of(target), List.of(), false, false, target.isOwnershipUnknown());
	}

	private static RewardTarget gearTarget(MilestoneEntry entry, String name, List<Integer> ids, KnowledgeBase kb, GearComparison gear)
	{
		String benefit = String.join("; ", entry.getUnlocks());
		if (benefit.isBlank()) benefit = kb.getGearCatalog().benefit(ids.get(0));
		if (benefit == null || benefit.isBlank()) benefit = entry.getReason();
		if (benefit == null || benefit.isBlank()) benefit = "Completes the remaining " + entry.getName() + " objective";
		return new RewardTarget(name, withReplacement(benefit, ids, kb, gear), RewardValue.USEFUL, !gear.ownershipKnown(ids));
	}

	static boolean providerGreenLogged(MilestoneEntry provider, Snapshot snapshot)
	{
		if (provider == null) return false;
		String bossId = provider.getCategory() == MilestoneCategory.BOSS ? provider.getId() : provider.getObtainedFrom();
		if (bossId == null) return false;
		BossProgress progress = snapshot.getBossProgress().get(bossId);
		return progress != null && Boolean.TRUE.equals(progress.getGreenLogged());
	}

	private static boolean covered(BossReward reward, Snapshot snapshot, GearComparison gear)
	{
		return "rigour".equals(reward.getPrayer()) && snapshot.isRigour()
			|| "augury".equals(reward.getPrayer()) && snapshot.isAugury()
			|| gear.covers(reward.getIds());
	}

	private static RewardTarget target(BossReward reward, String name, List<Integer> ownershipIds, KnowledgeBase kb, GearComparison gear)
	{
		RewardValue value = reward.getValue();
		String benefit = reward.getBenefit();
		List<List<Integer>> context = reward.getSituationalWhenAllOwned();
		if (!context.isEmpty() && context.stream().allMatch(gear::covers))
		{
			if (value.ordinal() < RewardValue.SITUATIONAL.ordinal()) value = RewardValue.SITUATIONAL;
			String existing = gear.coveringName(context.get(0));
			benefit += (benefit.endsWith(".") ? " " : "; ") + "situational rather than a primary upgrade with " + existing + " already available";
		}
		boolean known = reward.getPrayer() != null || gear.ownershipKnown(ownershipIds);
		return new RewardTarget(name, withReplacement(benefit, ownershipIds, kb, gear), value, !known);
	}

	private static String withReplacement(String benefit, List<Integer> targets, KnowledgeBase kb, GearComparison gear)
	{
		Integer best = null;
		for (int owned : gear.ownedIds())
		{
			for (int target : targets)
			{
				if (kb.getGearCatalog().canonicalId(target) != owned && kb.getGearCatalog().covers(target, owned)
					&& (best == null || kb.getGearCatalog().covers(owned, best))) best = owned;
			}
		}
		String name = best == null ? null : kb.getGearCatalog().name(best);
		return name == null ? benefit : benefit + (benefit.endsWith(".") ? " " : "; ") + "replaces your " + name;
	}

	private static BossReward matchingReward(MilestoneEntry provider, List<Integer> ids, KnowledgeBase kb)
	{
		if (provider == null) return null;
		for (BossReward reward : provider.getBossRewards())
		{
			for (int id : ids)
			{
				for (int rewardId : reward.getIds())
				{
					if (kb.getGearCatalog().canonicalId(id) == kb.getGearCatalog().canonicalId(rewardId)) return reward;
				}
			}
		}
		return null;
	}
}

package com.signpost.engine;

import com.signpost.engine.model.Advice;
import com.signpost.engine.model.DiaryTaskGap;
import com.signpost.engine.model.FocusDetail;
import com.signpost.engine.model.Gap;
import com.signpost.engine.model.Goal;
import com.signpost.engine.model.GoalCategory;
import com.signpost.engine.model.GoalStatus;
import com.signpost.engine.model.NextStep;
import com.signpost.engine.model.NextStepType;
import com.signpost.engine.model.PrefsView;
import com.signpost.engine.model.RankedGoal;
import com.signpost.engine.model.Route;
import com.signpost.engine.model.Shortfall;
import com.signpost.engine.model.SkillLevelGap;
import com.signpost.engine.model.SkillPlan;
import com.signpost.kb.KnowledgeBase;
import com.signpost.kb.MilestoneEntry;
import com.signpost.snapshot.DiaryTier;
import com.signpost.snapshot.SkillState;
import com.signpost.snapshot.Snapshot;
import com.signpost.store.AccountData;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import lombok.Value;
import net.runelite.api.Experience;
import net.runelite.api.Skill;

/**
 * Pure entry point wiring {@link GapEngine}, {@link DiaryProgress}, {@link PrefsResolver},
 * {@link SkillTargetSynthesiser}, {@link Ranker}, {@link SuggestSelector}, and {@link WhyBuilder} together: one {@link #run} call
 * turns a {@link Snapshot} + {@link KnowledgeBase} + {@link AccountData} into a complete
 * {@link Advice}. No {@link net.runelite.api.Client}, no I/O (global constraint: engine code is
 * pure).
 */
@Value
public class Engine
{
	GapEngine gapEngine;
	BoostTable boostTable;
	PrefsResolver prefsResolver;
	Ranker ranker;
	SuggestSelector suggestSelector;
	WhyBuilder whyBuilder;
	NextStepPicker nextStepPicker;

	public Engine(BoostTable boostTable)
	{
		this.boostTable = boostTable;
		this.gapEngine = new GapEngine(boostTable);
		this.prefsResolver = new PrefsResolver();
		this.ranker = new Ranker();
		this.suggestSelector = new SuggestSelector();
		this.whyBuilder = new WhyBuilder();
		this.nextStepPicker = new NextStepPicker();
	}

	public Advice run(Snapshot snapshot, KnowledgeBase kb, AccountData data, Instant now)
	{
		return run(snapshot, kb, data, now, null);
	}

	/** As {@link #run(Snapshot, KnowledgeBase, AccountData, Instant)}, also reporting which of {@code previous}'s goals were completed since; {@code previous} may be {@code null}. */
	public Advice run(Snapshot snapshot, KnowledgeBase kb, AccountData data, Instant now, Advice previous)
	{
		return run(snapshot, kb, data, now, previous, Map.of());
	}

	/** As above, also carrying the plugin's observed {@code xpPerHour} per skill through to {@link Advice#getXpPerHour()}. */
	public Advice run(Snapshot snapshot, KnowledgeBase kb, AccountData data, Instant now, Advice previous, Map<Skill, Long> xpPerHour)
	{
		return run(snapshot, kb, data, now, previous, xpPerHour, false);
	}

	public Advice run(Snapshot snapshot, KnowledgeBase kb, AccountData data, Instant now, Advice previous,
		Map<Skill, Long> xpPerHour, boolean includeWilderness)
	{
		Map<DiaryTier, DiaryTierProgress> diaryProgress = DiaryProgress.compute(snapshot, kb);
		GearComparison gear = new GearComparison(snapshot, kb, data.getOwnedManually());
		List<GoalStatus> base = gapEngine.evaluate(snapshot, kb, diaryProgress, data.getOwnedManually(), gear);
		base.addAll(GearUpgradeSynthesiser.run(kb.getGearLadders(), snapshot, kb, data.getOwnedManually(), gapEngine, gear));
		PrefsView basePrefs = prefsResolver.resolve(data, base, now);
		int accountStage = StageEstimator.estimate(snapshot, kb, data.getOwnedManually());
		// Skill targets come from the visible, stage-appropriate goals' skill gaps,
		// then join the statuses so they rank, pin, snooze, and focus like any other goal.
		// A target fully covered by ready quests' reward xp is dropped and those quests
		// count as unblocking its parents (ranked with the fan-out bonus).
		SkillTargetSynthesiser.Synthesis synthesis = SkillTargetSynthesiser.run(base, basePrefs.getHidden(), accountStage, snapshot, kb);
		List<GoalStatus> targets = synthesis.getTargets();
		List<GoalStatus> statuses = new ArrayList<>(base);
		statuses.addAll(targets);
		PrefsView prefs = targets.isEmpty() ? basePrefs : prefsResolver.resolve(data, statuses, now);
		List<RankedGoal> ranked = ranker.rank(statuses, prefs.getHidden(), prefs.getPins(), accountStage, synthesis.getQuestUnblocks());
		List<RankedGoal> picked = suggestSelector.pick3(ranked, kb);
		List<RankedGoal> restAll = suggestSelector.rest(ranked, picked);
		List<RankedGoal> later = ranked.stream().filter(RankedGoal::isLater).collect(Collectors.toList());
		List<RankedGoal> rest = restAll.stream().filter(r -> !r.isLater()).collect(Collectors.toList());

		// The skills that have a ranked skill target, so "speeds up Mining" can point at it.
		Set<Skill> targetSkills = ranked.stream()
			.filter(r -> r.getStatus().getGoal().getCategory() == GoalCategory.SKILL_TARGET)
			.flatMap(r -> r.getStatus().getGaps().stream())
			.filter(gap -> gap instanceof SkillLevelGap)
			.map(gap -> ((SkillLevelGap) gap).getSkill())
			.collect(Collectors.toSet());

		Map<String, String> whys = new LinkedHashMap<>();
		Map<String, List<String>> explanations = new LinkedHashMap<>();
		Map<String, String> reasons = new LinkedHashMap<>();
		for (RankedGoal r : ranked)
		{
			String goalId = r.getStatus().getGoal().getId();
			whys.put(goalId, whyBuilder.why(r, kb, snapshot, targetSkills));
			explanations.put(goalId, whyBuilder.explain(r, kb, snapshot, accountStage));

			MilestoneEntry entry = kb.milestoneById(goalId);
			if (entry != null && r.getStatus().getObjective() == null && entry.getReason() != null && !entry.getReason().isEmpty())
			{
				reasons.put(goalId, entry.getReason());
			}
		}

		FocusDetail focus = computeFocus(prefs, statuses, snapshot, kb, includeWilderness);

		Map<String, String> ownedManuallyNames = new LinkedHashMap<>();
		for (String goalId : data.getOwnedManually())
		{
			MilestoneEntry entry = kb.milestoneById(goalId);
			if (entry != null)
			{
				ownedManuallyNames.put(goalId, entry.getName());
			}
		}
		for (com.signpost.kb.GearLadder ladder : kb.getGearLadders())
		{
			for (com.signpost.kb.GearLadder.Rung rung : ladder.getRungs())
			{
				String id = GearUpgradeSynthesiser.id(ladder, rung);
				if (data.getOwnedManually().contains(id)) ownedManuallyNames.put(id, rung.getName());
			}
		}

		return new Advice(snapshot, statuses, diaryProgress, now, ranked, picked, rest, accountStage, later, whys, explanations, reasons,
			ownedManuallyNames, prefs, focus, completedSince(previous, statuses, snapshot, data.getOwnedManually(), kb, gear), xpPerHour);
	}


	/**
	 * A goal {@code previous} listed that {@code current} no longer does counts as
	 * completed unless it was marked owned by hand, or it is a skill target whose level the player
	 * has not reached (a target also disappears when its parent is hidden or the stage moves on).
	 */
	static List<Goal> completedSince(Advice previous, List<GoalStatus> current, Snapshot snapshot, Set<String> ownedManually,
		KnowledgeBase kb, GearComparison gear)
	{
		if (previous == null)
		{
			return List.of();
		}
		Set<String> currentIds = current.stream().map(s -> s.getGoal().getId()).collect(Collectors.toSet());
		List<Goal> completed = new ArrayList<>();
		for (GoalStatus old : previous.getStatuses())
		{
			Goal goal = old.getGoal();
			if (currentIds.contains(goal.getId()) || ownedManually.contains(goal.getId()))
			{
				continue;
			}
			if (goal.getCategory() == GoalCategory.BOSS && old.getObjective() != null)
			{
				var progress = snapshot.getBossProgress().get(goal.getId());
				if (progress == null || !Boolean.TRUE.equals(progress.getGreenLogged())
					|| !progress.isCombatAchievementsKnown() || !progress.getRemainingTasks().isEmpty())
				{
					continue;
				}
			}
			MilestoneEntry entry = kb.milestoneById(goal.getId());
			if (entry != null && entry.getCategory() == com.signpost.kb.MilestoneCategory.GEAR
				&& entry.getOwnedIf().stream().filter(item -> gear.owns(item.getIds())).count() < entry.getOwnedIfMin())
			{
				continue;
			}
			if (goal.getUpgrade() != null && !gear.owns(goal.getUpgrade().getTarget().getVariants()))
			{
				continue;
			}
			if (goal.getCategory() == GoalCategory.SKILL_TARGET)
			{
				SkillLevelGap gap = (SkillLevelGap) old.getGaps().get(0);
				SkillState state = snapshot.getSkills().get(gap.getSkill());
				if (state == null || state.getLevel() < gap.getNeed())
				{
					continue;
				}
			}
			completed.add(goal);
		}
		return completed;
	}

	/** Thin overload for callers with no account data (e.g. existing tests): behaves as {@link #run} with an empty {@link AccountData} and the current time. */
	public Advice run(Snapshot snapshot, KnowledgeBase kb)
	{
		return run(snapshot, kb, AccountData.empty(), Instant.now());
	}

	/**
	 * Computes the focus goal's full drill-down when {@code prefs.focusGoalId} matches a
	 * goal in {@code statuses} (ready or not - not filtered by hidden/snoozed/ignored, so a focused
	 * goal stays visible in Focus mode even if hidden from Suggest mode); {@code null} when no goal
	 * is focused or the focused goal is no longer present (e.g. completed, so
	 * {@link GapEngine#evaluate} no longer emits it). Reuses the same {@link NextStep}/{@link Route}/
	 * {@link Shortfall} objects {@link NextStepPicker} and {@link ShortfallResolver} compute - never
	 * a second computation.
	 */
	private FocusDetail computeFocus(PrefsView prefs, List<GoalStatus> statuses, Snapshot snapshot, KnowledgeBase kb, boolean includeWilderness)
	{
		String focusGoalId = prefs.getFocusGoalId();
		if (focusGoalId == null)
		{
			return null;
		}

		GoalStatus status = null;
		for (GoalStatus candidate : statuses)
		{
			if (candidate.getGoal().getId().equals(focusGoalId))
			{
				status = candidate;
				break;
			}
		}
		if (status == null)
		{
			return null;
		}

		// A skill target's route was computed once by SkillTargetSynthesiser: reuse it.
		NextStep next = status.getBankRoute() != null
			? NextStep.skill((SkillLevelGap) status.getGaps().get(0), status.getBankRoute())
			: nextStepPicker.next(status, snapshot, kb);
		Route route = next.getType() == NextStepType.SKILL ? next.getRoute() : null;
		Shortfall shortfall = route != null && route.getUncoveredXp() > 0
			? ShortfallResolver.resolve(next.getSkillGap().getSkill(), route, kb, snapshot, includeWilderness)
			: null;
		int fromLevel = next.getType() == NextStepType.SKILL ? next.getSkillGap().getHave() : 0;
		int toLevel = next.getType() == NextStepType.SKILL ? next.getSkillGap().getNeed() : 0;

		List<SkillPlan> skillPlans = computeSkillPlans(status, next, snapshot, kb, includeWilderness);
		SkillPlan nextSkillPlan = next.getType() == NextStepType.SKILL
			? skillPlans.stream().filter(p -> p.getSkill() == next.getSkillGap().getSkill()).findFirst().orElse(null)
			: null;

		NextStep guided = NextStepGuidance.derive(next, shortfall, snapshot, kb);
		return new FocusDetail(status, guided, route, shortfall, fromLevel, toLevel, skillPlans, nextSkillPlan);
	}

	/**
	 * One {@link SkillPlan} per distinct skill of the focused goal's {@link SkillLevelGap}s
	 * - top-level, inside a {@link DiaryTaskGap}, and recommended; a skill appearing more than once
	 * keeps its highest target level. The gap NextStepPicker already picked (if any) reuses its
	 * already-computed {@link Route}/{@link Shortfall} rather than recomputing them.
	 */
	private List<SkillPlan> computeSkillPlans(GoalStatus status, NextStep next, Snapshot snapshot, KnowledgeBase kb, boolean includeWilderness)
	{
		List<FlatSkillGap> flat = new ArrayList<>();
		collectSkillGaps(status.getGaps(), null, flat);

		Map<Skill, FlatSkillGap> bySkill = new LinkedHashMap<>();
		for (FlatSkillGap f : flat)
		{
			FlatSkillGap existing = bySkill.get(f.gap.getSkill());
			if (existing == null || f.gap.getNeed() > existing.gap.getNeed())
			{
				bySkill.put(f.gap.getSkill(), f);
			}
		}

		Map<Integer, Integer> bankAll = NextStepPicker.bankAll(snapshot);
		List<SkillPlan> plans = new ArrayList<>();
		for (FlatSkillGap f : bySkill.values())
		{
			SkillLevelGap gap = f.gap;
			long fromXp = currentXp(snapshot, gap.getSkill());
			long toXp = Experience.getXpForLevel(gap.getNeed());
			Route route = next.getType() == NextStepType.SKILL && next.getSkillGap() == gap
				? next.getRoute()
				: RoutePlanner.route(gap.getSkill(), fromXp, toXp, bankAll, kb);
			boolean covered = route.getUncoveredXp() == 0;
			Shortfall shortfall = covered ? null : ShortfallResolver.resolve(gap.getSkill(), route, kb, snapshot, includeWilderness);
			SkillPlan plan = new SkillPlan(gap.getSkill(), gap.getHave(), gap.getNeed(), fromXp, toXp, gap.isRecommended(), route, shortfall, covered,
				f.source);
			plans.add(GroupStorageShares.apply(plan, snapshot.getGroupStorage()));
		}
		plans.sort(Comparator.comparingLong(p -> p.getToXp() - p.getFromXp()));
		return plans;
	}

	/** Recursively finds every {@link SkillLevelGap}, tagging each with where it came from. */
	private static void collectSkillGaps(List<Gap> gaps, Integer diaryTaskOrdinal, List<FlatSkillGap> out)
	{
		for (Gap gap : gaps)
		{
			if (gap instanceof SkillLevelGap)
			{
				SkillLevelGap skillGap = (SkillLevelGap) gap;
				String source = diaryTaskOrdinal != null
					? "diary task " + diaryTaskOrdinal
					: skillGap.isRecommended() ? "recommended" : "quest";
				out.add(new FlatSkillGap(skillGap, source));
			}
			else if (gap instanceof DiaryTaskGap)
			{
				DiaryTaskGap taskGap = (DiaryTaskGap) gap;
				collectSkillGaps(taskGap.getGaps(), taskGap.getOrdinal(), out);
			}
		}
	}

	private static long currentXp(Snapshot snapshot, Skill skill)
	{
		SkillState state = snapshot.getSkills().get(skill);
		return state == null ? 0 : state.getXp();
	}

	private static final class FlatSkillGap
	{
		final SkillLevelGap gap;
		final String source;

		FlatSkillGap(SkillLevelGap gap, String source)
		{
			this.gap = gap;
			this.source = source;
		}
	}
}

package com.signpost.engine;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Skill;

/**
 * Curated maximum realistic boost per skill. The engine never reads live boosted
 * levels from the client; this table is what {@code SkillLevelGap.boostableFrom} is computed
 * against. Values are display-only estimates of commonly available boosts and may drift from
 * current game balance - update this table deliberately, not the engine, when they do.
 */
public final class BoostTable
{
	private static final Map<Skill, Integer> DEFAULTS = buildDefaults();

	private final Map<Skill, Integer> maxBoosts;

	public BoostTable()
	{
		this(DEFAULTS);
	}

	public BoostTable(Map<Skill, Integer> maxBoosts)
	{
		this.maxBoosts = Map.copyOf(maxBoosts);
	}

	/** The largest realistic temporary boost for {@code skill}, or 0 if none is curated. */
	public int maxBoost(Skill skill)
	{
		return maxBoosts.getOrDefault(skill, 0);
	}

	private static Map<Skill, Integer> buildDefaults()
	{
		Map<Skill, Integer> m = new HashMap<>();
		m.put(Skill.AGILITY, 5);
		m.put(Skill.CONSTRUCTION, 8); // crystal saw (3) + spicy stew (5)
		m.put(Skill.COOKING, 5);
		m.put(Skill.CRAFTING, 4);
		m.put(Skill.FARMING, 5);
		m.put(Skill.FIREMAKING, 5);
		m.put(Skill.FISHING, 5);
		m.put(Skill.FLETCHING, 5);
		m.put(Skill.HERBLORE, 6);
		m.put(Skill.HUNTER, 5);
		m.put(Skill.MAGIC, 10); // imbued heart
		m.put(Skill.MINING, 3);
		m.put(Skill.RUNECRAFT, 5);
		m.put(Skill.SLAYER, 5);
		m.put(Skill.SMITHING, 5);
		m.put(Skill.THIEVING, 5);
		m.put(Skill.WOODCUTTING, 3);
		m.put(Skill.PRAYER, 0);
		return Map.copyOf(m);
	}
}

package com.signpost.engine;

import com.signpost.engine.model.GoalStatus;
import com.signpost.engine.model.PrefsView;
import com.signpost.store.AccountData;
import com.signpost.store.Snooze;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Resolves a player's persisted {@link AccountData} preferences (snoozes/ignores/pins/focus)
 * against the current {@link GoalStatus}es into a {@link PrefsView}. A snooze is active iff
 * {@code now} is before its {@code until} <em>and</em> its stored {@code gapFingerprint} still
 * matches {@link GapFingerprint#of} for that goal (a changed gap ends the snooze
 * early); a goal that no longer appears among {@code statuses} can never match, so its snooze is
 * treated as expired. Pure: no {@link net.runelite.api.Client}, no I/O.
 */
public final class PrefsResolver
{
	public PrefsView resolve(AccountData data, List<GoalStatus> statuses, Instant now)
	{
		Map<String, GoalStatus> byId = new LinkedHashMap<>();
		for (GoalStatus status : statuses)
		{
			byId.put(status.getGoal().getId(), status);
		}

		Set<String> snoozedActive = new LinkedHashSet<>();
		Set<String> snoozedExpired = new LinkedHashSet<>();
		for (Map.Entry<String, Snooze> entry : data.getSnoozes().entrySet())
		{
			String goalId = entry.getKey();
			Snooze snooze = entry.getValue();
			GoalStatus status = byId.get(goalId);
			// A null fingerprint means "not known when snoozed" (no Advice yet): the snooze is
			// time-only rather than silently lost. A null until (hand-edited file) is expired.
			boolean fingerprintMatches = snooze.getGapFingerprint() == null
				|| (status != null && snooze.getGapFingerprint().equals(GapFingerprint.of(status)));
			boolean timeActive = snooze.getUntil() != null && now.isBefore(snooze.getUntil());
			if (timeActive && fingerprintMatches)
			{
				snoozedActive.add(goalId);
			}
			else
			{
				snoozedExpired.add(goalId);
			}
		}

		Set<String> hidden = new LinkedHashSet<>(data.getIgnores());
		hidden.addAll(snoozedActive);

		return new PrefsView(hidden, List.copyOf(data.getPins()), snoozedActive, snoozedExpired, data.getFocusGoalId(),
			Set.copyOf(data.getOwnedManually()));
	}
}

package com.signpost.engine;

import com.signpost.engine.model.Route;
import com.signpost.engine.model.RouteStep;
import com.signpost.engine.model.Shortfall;
import com.signpost.engine.model.ShortfallItem;
import com.signpost.engine.model.SkillPlan;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Decides how much of each route step's materials and each shortfall
 * line's {@code have} the group ironman shared storage supplied, so the detail view can print
 * "in group storage: N". Pure: {@code (SkillPlan, storage) -> SkillPlan}.
 *
 * <p>Storage is spent first, walking the steps and each step's crafts in planner order against a
 * working copy, since the route's pool is one bank-plus-storage sum. Shortfall lines - the primary
 * items, their craft-from children and the alternative - all restate the same post-route
 * {@code have}, so each shows {@code min(have, left)} of what the steps left and consumes nothing.
 */
public final class GroupStorageShares
{
	private GroupStorageShares()
	{
	}

	/** Returns {@code plan} itself when {@code storage} is empty (every non-group account), so a route reused from {@code NextStepPicker} stays the same object. */
	public static SkillPlan apply(SkillPlan plan, Map<Integer, Integer> storage)
	{
		if (storage.isEmpty())
		{
			return plan;
		}
		Map<Integer, Integer> left = new HashMap<>(storage);
		Route route = plan.getRoute();
		Route sharedRoute = route == null
			? null
			: new Route(shareSteps(route.getSteps(), left), route.getUncoveredXp(), route.getFinalXp(), route.getSimulatedBank());
		Shortfall sharedShortfall = shareShortfall(plan.getShortfall(), left);
		return new SkillPlan(plan.getSkill(), plan.getFromLevel(), plan.getToLevel(), plan.getFromXp(), plan.getToXp(), plan.isRecommended(),
			sharedRoute, sharedShortfall, plan.isCovered(), plan.getSource());
	}

	private static List<RouteStep> shareSteps(List<RouteStep> steps, Map<Integer, Integer> left)
	{
		List<RouteStep> result = new ArrayList<>();
		for (RouteStep step : steps)
		{
			// Crafts run before the step's own action, so they draw on the storage first.
			List<RouteStep> crafts = shareSteps(step.getCrafts(), left);
			Map<Integer, Integer> share = new LinkedHashMap<>();
			for (Map.Entry<Integer, Integer> used : step.getMaterialsUsed().entrySet())
			{
				int taken = Math.min(used.getValue(), left.getOrDefault(used.getKey(), 0));
				if (taken > 0)
				{
					share.put(used.getKey(), taken);
					left.merge(used.getKey(), -taken, Integer::sum);
				}
			}
			result.add(new RouteStep(step.getMethod(), step.getCount(), step.getFromLevel(), step.getToLevel(), step.getXpGained(),
				step.getMaterialsUsed(), List.copyOf(crafts), Map.copyOf(share), step.getQuest()));
		}
		return result;
	}

	private static Shortfall shareShortfall(Shortfall shortfall, Map<Integer, Integer> left)
	{
		if (shortfall == null)
		{
			return null;
		}
		return new Shortfall(shortfall.getMethod(), shareItems(shortfall.getItems(), left), shortfall.getXpShort(), shortfall.getActionsNeeded(),
			shareShortfall(shortfall.getAlternative(), left), shortfall.getUnobtainable(), shortfall.getNotes());
	}

	private static List<ShortfallItem> shareItems(List<ShortfallItem> items, Map<Integer, Integer> left)
	{
		List<ShortfallItem> result = new ArrayList<>();
		for (ShortfallItem item : items)
		{
			Integer id = item.getItem().getId();
			int share = id == null ? 0 : Math.min(item.getHave(), left.getOrDefault(id, 0));
			result.add(new ShortfallItem(item.getItem(), item.getHave(), item.getNeed(), item.getSources(), shareItems(item.getCraftFrom(), left),
				item.getWikiUrl(), item.getPlans(), share));
		}
		return List.copyOf(result);
	}
}

package com.signpost.engine;

import com.signpost.engine.model.DiaryTaskGap;
import com.signpost.engine.model.Gap;
import com.signpost.engine.model.GearGap;
import com.signpost.engine.model.ItemGap;
import com.signpost.engine.model.SkillLevelGap;
import java.util.List;

/**
 * Shared leaf-counting and XP-summing over a goal's gap tree, used by both
 * {@link Ranker} (the score formula) and {@link WhyBuilder} ("N requirement(s) away") so the two
 * stay consistent.
 */
final class GoalMetrics
{
	private GoalMetrics()
	{
	}

	/**
	 * Every top-level gap counts 1, except: an {@link ItemGap} with an unknown {@code have} (bank
	 * not seen) counts 0 (it's not a confirmed shortfall, just unknown), and likewise a
	 * {@link GearGap} with {@code bankUnknown} true; a {@link DiaryTaskGap} counts its own
	 * {@link #unmetCount} over its inner gaps (minimum 1).
	 */
	static int unmetCount(List<Gap> gaps)
	{
		int count = 0;
		for (Gap gap : gaps)
		{
			if (gap instanceof DiaryTaskGap)
			{
				count += Math.max(1, unmetCount(((DiaryTaskGap) gap).getGaps()));
			}
			else if (gap instanceof ItemGap && ((ItemGap) gap).getHave() == null)
			{
				continue;
			}
			else if (gap instanceof GearGap && ((GearGap) gap).isBankUnknown())
			{
				continue;
			}
			else
			{
				count += 1;
			}
		}
		return count;
	}

	/** Sum of {@link SkillLevelGap#getXpDelta()} over top-level and nested (inside a {@link DiaryTaskGap}) gaps. */
	static long xpDeltaSum(List<Gap> gaps)
	{
		long sum = 0;
		for (Gap gap : gaps)
		{
			if (gap instanceof SkillLevelGap)
			{
				sum += ((SkillLevelGap) gap).getXpDelta();
			}
			else if (gap instanceof DiaryTaskGap)
			{
				sum += xpDeltaSum(((DiaryTaskGap) gap).getGaps());
			}
		}
		return sum;
	}
}

